  ('g11-arabic-u2-l1-q3', 'g11-arabic-u2-l1', 'true_false', 'كانت القصيدة الجاهلية تبدأ غالباً بالوقوف على الأطلال.', null, 'true'::jsonb, null, 'المقدمة الطللية من سماتها.', 'medium', false, 'seed'),
