  ('g11-arabic-u2-l1-q5', 'g11-arabic-u2-l1', 'fill_blank', 'سميت المعلقات بهذا الاسم لأنها ____ في النفوس لجودتها (على أحد الأقوال).', '["علقت","نسيت","كتبت"]'::jsonb, '"علقت"'::jsonb, null, 'من الأقوال أنها علقت بالأذهان لروعتها.', 'hard', false, 'seed'),
  ('g11-arabic-u2-l2-q1', 'g11-arabic-u2-l2', 'mcq', 'النقد الأدبي هو:', '["دراسة النص وبيان جماله وعيوبه","السخرية من الكاتب","حفظ النص فقط","ترجمة النص"]'::jsonb, '"دراسة النص وبيان جماله وعيوبه"'::jsonb, null, 'النقد تحليل وتقويم.', 'easy', false, 'seed'),
