  ('g11-arabic-u2-l2-q4', 'g11-arabic-u2-l2', 'mcq', 'صدق العاطفة يعني:', '["أن يعبّر الكاتب عن شعور حقيقي","أن يكتب بلا مشاعر","أن يكثر الألفاظ الغريبة","أن يطيل النص"]'::jsonb, '"أن يعبّر الكاتب عن شعور حقيقي"'::jsonb, null, 'العاطفة الصادقة تؤثر في القارئ.', 'medium', false, 'seed'),
  ('g11-arabic-u2-l2-q5', 'g11-arabic-u2-l2', 'word_order', 'رتّب الكلمات لتكوين جملة صحيحة.', null, '["الأسلوب","الجيد","يجمع","بين","الوضوح","والجمال"]'::jsonb, null, 'جملة نقدية مرتبة.', 'hard', false, 'seed'),
  ('g11-english-u1-l1-q1', 'g11-english-u1-l1', 'mcq', 'If it rains tomorrow, we ____ at home.', '["stay","will stay","stayed","would stayed"]'::jsonb, '"will stay"'::jsonb, null, 'First conditional: If + present, will + verb.', 'easy', false, 'seed'),
  ('g11-english-u1-l1-q2', 'g11-english-u1-l1', 'mcq', 'If I ____ a million rials, I would build a school.', '["have","had","will have","having"]'::jsonb, '"had"'::jsonb, null, 'Second conditional: If + past, would + verb.', 'medium', false, 'seed'),
  ('g11-english-u1-l1-q3', 'g11-english-u1-l1', 'true_false', '"If I were you, I would study harder" is a second conditional sentence.', null, 'true'::jsonb, null, 'It describes an imaginary situation.', 'medium', false, 'seed'),
  ('g11-english-u1-l1-q4', 'g11-english-u1-l1', 'word_order', 'Put the words in the correct order.', null, '["If","you","heat","ice","it","melts"]'::jsonb, null, 'Zero conditional: If you heat ice, it melts.', 'hard', false, 'seed'),
  ('g11-english-u1-l1-q5', 'g11-english-u1-l1', 'fill_blank', 'If she studies hard, she ____ pass the exam.', '["will","would","did"]'::jsonb, '"will"'::jsonb, null, 'First conditional uses "will".', 'medium', false, 'seed'),
  ('g11-english-u1-l2-q1', 'g11-english-u1-l2', 'mcq', 'A person who designs buildings is an ____.', '["architect","accountant","astronaut","actor"]'::jsonb, '"architect"'::jsonb, null, 'Architects design buildings.', 'easy', false, 'seed'),
  ('g11-english-u1-l2-q2', 'g11-english-u1-l2', 'mcq', 'Your "CV" is a document that shows your ____.', '["education and experience","favourite food","holiday photos","shopping list"]'::jsonb, '"education and experience"'::jsonb, null, 'A CV lists your education, skills and experience.', 'easy', false, 'seed'),
  ('g11-english-u1-l2-q3', 'g11-english-u1-l2', 'true_false', '"Teamwork" means working well with other people.', null, 'true'::jsonb, null, 'Teamwork is an important skill in most jobs.', 'easy', false, 'seed'),
  ('g11-english-u1-l2-q4', 'g11-english-u1-l2', 'mcq', 'Which sentence is the most formal?', '["Hey, gimme the job!","I am writing to apply for the position of engineer.","Wanna hire me?","Job pls."]'::jsonb, '"I am writing to apply for the position of engineer."'::jsonb, null, 'Formal letters use complete, polite sentences.', 'medium', false, 'seed'),
  ('g11-english-u1-l2-q5', 'g11-english-u1-l2', 'word_order', 'Put the words in the correct order.', null, '["I","am","interested","in","a","career","in","medicine"]'::jsonb, null, 'The correct sentence is: I am interested in a career in medicine.', 'medium', false, 'seed'),
  ('g11-english-u2-l1-q1', 'g11-english-u2-l1', 'mcq', '"Where do you live?" → She asked me where I ____.', '["lived","live","do live","living"]'::jsonb, '"lived"'::jsonb, null, 'Tense moves back and the word order becomes a statement.', 'easy', false, 'seed'),
  ('g11-english-u2-l1-q2', 'g11-english-u2-l1', 'mcq', '"Are you ready?" → He asked if I ____ ready.', '["was","am","are","be"]'::jsonb, '"was"'::jsonb, null, 'Yes/no questions use "if" or "whether".', 'medium', false, 'seed'),
  ('g11-english-u2-l1-q3', 'g11-english-u2-l1', 'true_false', 'In reported questions we don''t use a question mark.', null, 'true'::jsonb, null, 'Reported questions are statements.', 'medium', false, 'seed'),
  ('g11-english-u2-l1-q4', 'g11-english-u2-l1', 'word_order', 'Put the words in the correct order.', null, '["She","asked","me","what","time","it","was"]'::jsonb, null, 'The correct sentence is: She asked me what time it was.', 'hard', false, 'seed'),
  ('g11-english-u2-l1-q5', 'g11-english-u2-l1', 'fill_blank', '"Can you help?" → They asked if I ____ help.', '["could","can","will"]'::jsonb, '"could"'::jsonb, null, '"Can" changes to "could".', 'medium', false, 'seed'),
  ('g11-english-u2-l2-q1', 'g11-english-u2-l2', 'mcq', '"Look up" a word means:', '["find it in a dictionary","look at the sky","forget it","write it"]'::jsonb, '"find it in a dictionary"'::jsonb, null, 'To look up = to search for information.', 'easy', false, 'seed'),
  ('g11-english-u2-l2-q2', 'g11-english-u2-l2', 'mcq', '"Give up" means:', '["stop trying","give a present","stand up","go away"]'::jsonb, '"stop trying"'::jsonb, null, 'To give up = to stop trying.', 'easy', false, 'seed'),
  ('g11-english-u2-l2-q3', 'g11-english-u2-l2', 'true_false', '"Find out" means to discover information.', null, 'true'::jsonb, null, 'Find out = learn or discover.', 'easy', false, 'seed'),
  ('g11-english-u2-l2-q4', 'g11-english-u2-l2', 'mcq', 'Please ____ your phone during the exam.', '["turn off","turn on","turn up","turn into"]'::jsonb, '"turn off"'::jsonb, null, 'Turn off = switch off.', 'medium', false, 'seed'),
  ('g11-english-u2-l2-q5', 'g11-english-u2-l2', 'word_order', 'Put the words in the correct order.', null, '["I","will","look","after","my","little","brother"]'::jsonb, null, 'The correct sentence is: I will look after my little brother.', 'medium', false, 'seed'),
