  ('g11-math-u1-l1-q3', 'g11-math-u1-l1', 'true_false', 'إذا كان المميز سالباً فلا توجد جذور حقيقية.', null, 'true'::jsonb, null, 'الجذر التربيعي لعدد سالب ليس حقيقياً.', 'medium', false, 'seed'),
  ('g11-math-u1-l1-q4', 'g11-math-u1-l1', 'mcq', 'حلول المعادلة x² = 49 هي:', '["7 فقط","-7 فقط","7 و -7","49 و -49"]'::jsonb, '"7 و -7"'::jsonb, null, 'x = ±7.', 'easy', false, 'seed'),
  ('g11-math-u1-l1-q5', 'g11-math-u1-l1', 'fill_blank', 'مجموع جذري المعادلة x² - 7x + 10 = 0 يساوي ____', null, '"7"'::jsonb, '["٧"]'::jsonb, 'مجموع الجذرين = -b/a = 7.', 'hard', false, 'seed'),
  ('g11-math-u1-l2-q1', 'g11-math-u1-l2', 'mcq', 'مشتقة f(x) = x³ هي:', '["3x²","x²","3x³","x⁴/4"]'::jsonb, '"3x²"'::jsonb, null, 'قاعدة القوة: n·x^(n-1).', 'easy', false, 'seed'),
  ('g11-math-u1-l2-q2', 'g11-math-u1-l2', 'mcq', 'مشتقة الدالة الثابتة f(x) = 9 هي:', '["9","0","1","x"]'::jsonb, '"0"'::jsonb, null, 'مشتقة الثابت صفر.', 'easy', false, 'seed'),
  ('g11-math-u1-l2-q3', 'g11-math-u1-l2', 'true_false', 'مشتقة f(x) = 5x² هي 10x.', null, 'true'::jsonb, null, '2 × 5 = 10، والأس يصبح 1.', 'easy', false, 'seed'),
  ('g11-math-u1-l2-q4', 'g11-math-u1-l2', 'mcq', 'ميل المماس للمنحنى y = x² عند x = 3:', '["3","6","9","2"]'::jsonb, '"6"'::jsonb, null, 'y'' = 2x، وعند x = 3 يكون الميل 6.', 'medium', false, 'seed'),
