  ('g11-math-u2-l1-q1', 'g11-math-u2-l1', 'mcq', 'مجموع المتجهين (2, 3) و(1, −1):', '["(3, 2)","(1, 4)","(3, 4)","(2, −3)"]'::jsonb, '"(3, 2)"'::jsonb, null, 'نجمع المركبات المتناظرة.', 'easy', false, 'seed'),
  ('g11-math-u2-l1-q2', 'g11-math-u2-l1', 'mcq', 'طول المتجه (3, 4):', '["5","7","12","25"]'::jsonb, '"5"'::jsonb, null, '√(9 + 16) = 5.', 'medium', false, 'seed'),
  ('g11-math-u2-l1-q3', 'g11-math-u2-l1', 'true_false', 'ضرب المتجه في عدد سالب يعكس اتجاهه.', null, 'true'::jsonb, null, 'الإشارة السالبة تعكس الاتجاه.', 'medium', false, 'seed'),
  ('g11-math-u2-l1-q4', 'g11-math-u2-l1', 'mcq', '2 × (1, −3) = ', '["(2, −6)","(3, −1)","(2, −3)","(−2, 6)"]'::jsonb, '"(2, −6)"'::jsonb, null, 'نضرب كل مركبة في 2.', 'easy', false, 'seed'),
