  ('g11-math-u2-l2-q5', 'g11-math-u2-l2', 'true_false', 'مصفوفة الوحدة 2 × 2 عناصر قطرها الرئيسي أصفار.', null, 'false'::jsonb, null, 'عناصر قطرها الرئيسي واحد.', 'medium', false, 'seed'),
