  ('g11-physics-u1-l2-q2', 'g11-physics-u1-l2', 'mcq', 'سيارة زادت سرعتها من 0 إلى 20 م/ث في 4 ث. تسارعها:', '["5 م/ث²","80 م/ث²","4 م/ث²","0.2 م/ث²"]'::jsonb, '"5 م/ث²"'::jsonb, null, 'a = (20 - 0) ÷ 4 = 5 م/ث².', 'medium', false, 'seed'),
  ('g11-physics-u1-l2-q3', 'g11-physics-u1-l2', 'true_false', 'الجسم الذي يتحرك بسرعة ثابتة في خط مستقيم تسارعه صفر.', null, 'true'::jsonb, null, 'لا تغير في السرعة يعني لا تسارع.', 'easy', false, 'seed'),
