  ('g11-physics-u1-l2-q5', 'g11-physics-u1-l2', 'fill_blank', 'إذا بدأ جسم من السكون بتسارع 2 م/ث² فإن سرعته بعد 5 ث = ____ م/ث', null, '"10"'::jsonb, '["١٠"]'::jsonb, 'v = u + at = 0 + 2 × 5 = 10.', 'hard', false, 'seed'),
  ('g11-physics-u2-l1-q1', 'g11-physics-u2-l1', 'mcq', 'المركبة الأفقية لسرعة المقذوف (بإهمال مقاومة الهواء):', '["ثابتة","تزداد","تتناقص","تساوي صفراً دائماً"]'::jsonb, '"ثابتة"'::jsonb, null, 'لا توجد قوة أفقية.', 'easy', false, 'seed'),
  ('g11-physics-u2-l1-q2', 'g11-physics-u2-l1', 'mcq', 'المركبة الرأسية تتأثر بـ:', '["تسارع الجاذبية","السرعة الأفقية","كتلة الجسم فقط","لون الجسم"]'::jsonb, '"تسارع الجاذبية"'::jsonb, null, 'الجاذبية تؤثر رأسياً.', 'easy', false, 'seed'),
