  ('g12-english-u2-l2-q3', 'g12-english-u2-l2', 'true_false', 'Giving evidence makes an argument stronger.', null, 'true'::jsonb, null, 'Facts and examples support your point.', 'easy', false, 'seed'),
  ('g12-english-u2-l2-q4', 'g12-english-u2-l2', 'mcq', 'A strong argument should be:', '["clear and supported by evidence","rude","very long and repeated","without reasons"]'::jsonb, '"clear and supported by evidence"'::jsonb, null, 'Clarity and evidence persuade people.', 'medium', false, 'seed'),
  ('g12-english-u2-l2-q5', 'g12-english-u2-l2', 'word_order', 'Put the words in the correct order.', null, '["There","are","several","reasons","for","this","view"]'::jsonb, null, 'The correct sentence is: There are several reasons for this view.', 'medium', false, 'seed'),
  ('g12-math-u1-l1-q1', 'g12-math-u1-l1', 'mcq', 'مشتقة f(x) = 3x⁴ - 2x هي:', '["12x³ - 2","12x³","3x³ - 2","12x⁴ - 2"]'::jsonb, '"12x³ - 2"'::jsonb, null, 'نشتق كل حد: 12x³ - 2.', 'easy', false, 'seed'),
  ('g12-math-u1-l1-q2', 'g12-math-u1-l1', 'mcq', 'مشتقة f(x) = (x + 1)(x - 1) هي:', '["2x","1","x² - 1","2"]'::jsonb, '"2x"'::jsonb, null, 'f(x) = x² - 1، إذن f''(x) = 2x.', 'medium', false, 'seed'),
  ('g12-math-u1-l1-q3', 'g12-math-u1-l1', 'true_false', 'مشتقة مجموع دالتين تساوي مجموع مشتقتيهما.', null, 'true'::jsonb, null, 'قاعدة المجموع في الاشتقاق.', 'easy', false, 'seed'),
  ('g12-math-u1-l1-q4', 'g12-math-u1-l1', 'mcq', 'إذا كانت f(x) = x² + 3x فإن f''(2) = ', '["7","10","4","5"]'::jsonb, '"7"'::jsonb, null, 'f''(x) = 2x + 3، f''(2) = 7.', 'medium', false, 'seed'),
  ('g12-math-u1-l1-q5', 'g12-math-u1-l1', 'fill_blank', 'مشتقة f(x) = x⁵ هي f''(x) = ____', null, '"5x⁴"'::jsonb, '["5x^4","5x4"]'::jsonb, 'قاعدة القوة.', 'medium', false, 'seed'),
  ('g12-math-u1-l2-q1', 'g12-math-u1-l2', 'mcq', 'النقطة الحرجة هي التي تكون عندها المشتقة الأولى:', '["صفراً أو غير معرّفة","موجبة دائماً","سالبة دائماً","تساوي 1"]'::jsonb, '"صفراً أو غير معرّفة"'::jsonb, null, 'نبحث عن النقاط التي f''(x) = 0 أو غير موجودة.', 'easy', false, 'seed'),
  ('g12-math-u1-l2-q2', 'g12-math-u1-l2', 'mcq', 'للدالة f(x) = x² - 6x + 1 نقطة حرجة عند:', '["x = 3","x = -3","x = 6","x = 1"]'::jsonb, '"x = 3"'::jsonb, null, 'f''(x) = 2x - 6 = 0 إذن x = 3.', 'medium', false, 'seed'),
  ('g12-math-u1-l2-q3', 'g12-math-u1-l2', 'true_false', 'إذا كانت المشتقة الثانية موجبة عند نقطة حرجة فهي قيمة صغرى محلية.', null, 'true'::jsonb, null, 'المنحنى مقعر للأعلى.', 'hard', false, 'seed'),
  ('g12-math-u1-l2-q4', 'g12-math-u1-l2', 'mcq', 'الدالة تكون متزايدة في فترة إذا كانت مشتقتها فيها:', '["موجبة","سالبة","صفراً","غير معرّفة"]'::jsonb, '"موجبة"'::jsonb, null, 'f''(x) > 0 تعني أن الدالة متزايدة.', 'easy', false, 'seed'),
  ('g12-math-u1-l2-q5', 'g12-math-u1-l2', 'fill_blank', 'القيمة الصغرى للدالة f(x) = x² - 4x + 7 هي ____', null, '"3"'::jsonb, '["٣"]'::jsonb, 'عند x = 2: f(2) = 4 - 8 + 7 = 3.', 'hard', false, 'seed'),
  ('g12-math-u2-l1-q1', 'g12-math-u2-l1', 'mcq', '∫ 2x dx = ', '["x² + C","2x² + C","x + C","2 + C"]'::jsonb, '"x² + C"'::jsonb, null, 'مشتقة x² هي 2x.', 'easy', false, 'seed'),
  ('g12-math-u2-l1-q2', 'g12-math-u2-l1', 'mcq', '∫ 3 dx = ', '["3x + C","3 + C","x³ + C","0"]'::jsonb, '"3x + C"'::jsonb, null, 'تكامل الثابت = الثابت × x.', 'easy', false, 'seed'),
  ('g12-math-u2-l1-q3', 'g12-math-u2-l1', 'true_false', 'التكامل عملية عكسية للاشتقاق.', null, 'true'::jsonb, null, 'التكامل يعيد الدالة الأصلية (مع ثابت).', 'easy', false, 'seed'),
  ('g12-math-u2-l1-q4', 'g12-math-u2-l1', 'mcq', '∫ x² dx = ', '["x³/3 + C","2x + C","x³ + C","3x² + C"]'::jsonb, '"x³/3 + C"'::jsonb, null, 'نرفع الأس بواحد ونقسم عليه.', 'medium', false, 'seed'),
  ('g12-math-u2-l1-q5', 'g12-math-u2-l1', 'fill_blank', '∫ 4x³ dx = ____ + C', null, '"x⁴"'::jsonb, '["x^4","x4"]'::jsonb, '4x³ ← تكاملها x⁴.', 'hard', false, 'seed'),
  ('g12-math-u2-l2-q1', 'g12-math-u2-l2', 'mcq', 'احتمال ظهور صورتين عند رمي قطعتي نقود:', '["1/4","1/2","1/3","2/4"]'::jsonb, '"1/4"'::jsonb, null, '1/2 × 1/2 = 1/4.', 'easy', false, 'seed'),
  ('g12-math-u2-l2-q2', 'g12-math-u2-l2', 'mcq', 'عدد طرق اختيار قميص من 3 وبنطال من 4:', '["12","7","3","4"]'::jsonb, '"12"'::jsonb, null, 'مبدأ العد: 3 × 4 = 12.', 'easy', false, 'seed'),
  ('g12-math-u2-l2-q3', 'g12-math-u2-l2', 'true_false', 'مجموع احتمالات جميع النواتج يساوي 1.', null, 'true'::jsonb, null, 'هذه من مسلّمات الاحتمال.', 'medium', false, 'seed'),
  ('g12-math-u2-l2-q4', 'g12-math-u2-l2', 'mcq', '!4 (مضروب 4) = ', '["24","16","10","4"]'::jsonb, '"24"'::jsonb, null, '4 × 3 × 2 × 1 = 24.', 'medium', false, 'seed'),
  ('g12-math-u2-l2-q5', 'g12-math-u2-l2', 'true_false', 'احتمال الحدث المؤكد يساوي صفراً.', null, 'false'::jsonb, null, 'احتمال الحدث المؤكد يساوي 1.', 'easy', false, 'seed'),
  ('g12-physics-u1-l1-q1', 'g12-physics-u1-l1', 'mcq', 'قانون أوم:', '["V = I × R","V = I ÷ R","R = V × I","I = V × R"]'::jsonb, '"V = I × R"'::jsonb, null, 'الجهد = التيار × المقاومة.', 'easy', false, 'seed'),
  ('g12-physics-u1-l1-q2', 'g12-physics-u1-l1', 'mcq', 'مقاومة 10 أوم يمر بها تيار 2 أمبير. الجهد:', '["5 فولت","20 فولت","12 فولت","0.2 فولت"]'::jsonb, '"20 فولت"'::jsonb, null, 'V = 2 × 10 = 20 فولت.', 'easy', false, 'seed'),
  ('g12-physics-u1-l1-q3', 'g12-physics-u1-l1', 'true_false', 'وحدة المقاومة الكهربائية هي الأوم.', null, 'true'::jsonb, null, 'تقاس المقاومة بالأوم (Ω).', 'easy', false, 'seed'),
  ('g12-physics-u1-l1-q4', 'g12-physics-u1-l1', 'mcq', 'مقاومتان 4 و 6 أوم موصولتان على التوالي. المقاومة المكافئة:', '["10 أوم","2.4 أوم","24 أوم","2 أوم"]'::jsonb, '"10 أوم"'::jsonb, null, 'على التوالي: R = R1 + R2 = 10 أوم.', 'medium', false, 'seed'),
  ('g12-physics-u1-l1-q5', 'g12-physics-u1-l1', 'fill_blank', 'مقاومتان كل منهما 8 أوم على التوازي، المقاومة المكافئة = ____ أوم', null, '"4"'::jsonb, '["٤"]'::jsonb, '1/R = 1/8 + 1/8 = 1/4 إذن R = 4.', 'hard', false, 'seed'),
  ('g12-physics-u1-l2-q1', 'g12-physics-u1-l2', 'mcq', 'القدرة الكهربائية P = ', '["V × I","V ÷ I","I ÷ V","V + I"]'::jsonb, '"V × I"'::jsonb, null, 'القدرة = الجهد × التيار.', 'easy', false, 'seed'),
  ('g12-physics-u1-l2-q2', 'g12-physics-u1-l2', 'mcq', 'وحدة القدرة:', '["الواط","الجول","الأوم","الكولوم"]'::jsonb, '"الواط"'::jsonb, null, 'تقاس القدرة بالواط.', 'easy', false, 'seed'),
  ('g12-physics-u1-l2-q3', 'g12-physics-u1-l2', 'mcq', 'جهاز يعمل على 240 فولت ويسحب 5 أمبير. قدرته:', '["1200 واط","48 واط","245 واط","235 واط"]'::jsonb, '"1200 واط"'::jsonb, null, 'P = 240 × 5 = 1200 واط.', 'medium', false, 'seed'),
  ('g12-physics-u1-l2-q4', 'g12-physics-u1-l2', 'true_false', 'الكيلوواط ساعة وحدة لقياس الطاقة الكهربائية المستهلكة.', null, 'true'::jsonb, null, 'فاتورة الكهرباء تُحسب بالكيلوواط ساعة.', 'medium', false, 'seed'),
