  ('g12-physics-u2-l1-q3', 'g12-physics-u2-l1', 'mcq', 'الملف اللولبي الذي يمر به تيار يسلك سلوك:', '["مغناطيس","عازل","مقاومة فقط","بطارية"]'::jsonb, '"مغناطيس"'::jsonb, null, 'يتكون له قطبان شمالي وجنوبي.', 'easy', false, 'seed'),
  ('g12-physics-u2-l1-q4', 'g12-physics-u2-l1', 'mcq', 'وحدة قياس شدة المجال المغناطيسي:', '["التسلا","الأوم","الفولت","الجول"]'::jsonb, '"التسلا"'::jsonb, null, 'التسلا وحدة المجال المغناطيسي.', 'medium', false, 'seed'),
  ('g12-physics-u2-l1-q5', 'g12-physics-u2-l1', 'fill_blank', 'إدخال قلب من ____ داخل الملف يقوّي المجال المغناطيسي.', '["الحديد","الخشب","البلاستيك"]'::jsonb, '"الحديد"'::jsonb, null, 'الحديد المطاوع يركّز خطوط المجال.', 'medium', false, 'seed'),
  ('g12-physics-u2-l2-q1', 'g12-physics-u2-l2', 'mcq', 'تحريك مغناطيس داخل ملف يولّد:', '["تياراً كهربائياً مستحثاً","حرارة فقط","صوتاً فقط","لا شيء"]'::jsonb, '"تياراً كهربائياً مستحثاً"'::jsonb, null, 'هذا هو الحث الكهرومغناطيسي.', 'easy', false, 'seed'),
