  ('g12-physics-u2-l2-q3', 'g12-physics-u2-l2', 'true_false', 'المولد الكهربائي يعمل بمبدأ الحث الكهرومغناطيسي.', null, 'true'::jsonb, null, 'يحول الطاقة الحركية إلى كهربائية.', 'medium', false, 'seed'),
