  ('g12-chemistry-u2-l2-q5', 'g12-chemistry-u2-l2', 'mcq', 'حفظ الطعام في الثلاجة يبطئ فساده لأن:', '["انخفاض الحرارة يبطئ التفاعلات","الضوء يزداد","الأكسجين يختفي","الطعام يتجمد دائماً"]'::jsonb, '"انخفاض الحرارة يبطئ التفاعلات"'::jsonb, null, 'البرودة تبطئ التفاعلات والميكروبات.', 'hard', false, 'seed'),
  ('g12-biology-u1-l1-q1', 'g12-biology-u1-l1', 'mcq', 'شكل جزيء DNA:', '["حلزون مزدوج","كرة","سلسلة مفردة مستقيمة","مكعب"]'::jsonb, '"حلزون مزدوج"'::jsonb, null, 'DNA حلزون مزدوج.', 'easy', false, 'seed'),
  ('g12-biology-u1-l1-q2', 'g12-biology-u1-l1', 'mcq', 'القاعدة النيتروجينية التي تتزاوج مع الأدينين (A) في DNA:', '["الثايمين (T)","الجوانين (G)","السيتوسين (C)","اليوراسيل (U)"]'::jsonb, '"الثايمين (T)"'::jsonb, null, 'A مع T، و G مع C.', 'easy', false, 'seed'),
  ('g12-biology-u1-l1-q3', 'g12-biology-u1-l1', 'true_false', 'اليوراسيل يوجد في RNA بدلاً من الثايمين.', null, 'true'::jsonb, null, 'RNA يحتوي اليوراسيل.', 'medium', false, 'seed'),
  ('g12-biology-u1-l1-q4', 'g12-biology-u1-l1', 'mcq', 'تضاعف DNA يوصف بأنه شبه محافظ لأن:', '["كل جزيء جديد يحتوي سلسلة قديمة وأخرى جديدة","الجزيء القديم يبقى كما هو","السلسلتان جديدتان","لا يحدث تضاعف"]'::jsonb, '"كل جزيء جديد يحتوي سلسلة قديمة وأخرى جديدة"'::jsonb, null, 'كل سلسلة قديمة تعمل قالباً لسلسلة جديدة.', 'hard', false, 'seed'),
  ('g12-biology-u1-l1-q5', 'g12-biology-u1-l1', 'fill_blank', 'إذا كان تسلسل سلسلة DNA هو ATGC فإن السلسلة المكملة ____', null, '"TACG"'::jsonb, '["tacg"]'::jsonb, 'A↔T و G↔C.', 'medium', false, 'seed'),
  ('g12-biology-u1-l2-q1', 'g12-biology-u1-l2', 'mcq', 'الكائنات المنتجة في النظام البيئي هي:', '["النباتات الخضراء","الحيوانات آكلة اللحوم","الفطريات","الإنسان"]'::jsonb, '"النباتات الخضراء"'::jsonb, null, 'النباتات تصنع غذاءها بالبناء الضوئي.', 'easy', false, 'seed'),
  ('g12-biology-u1-l2-q2', 'g12-biology-u1-l2', 'mcq', 'الكائنات المحللة مثل:', '["البكتيريا والفطريات","الأسود","الأشجار","الطيور"]'::jsonb, '"البكتيريا والفطريات"'::jsonb, null, 'المحللات تحلل بقايا الكائنات الميتة.', 'easy', false, 'seed'),
  ('g12-biology-u1-l2-q3', 'g12-biology-u1-l2', 'true_false', 'تقل الطاقة المنتقلة كلما انتقلنا إلى مستوى غذائي أعلى.', null, 'true'::jsonb, null, 'ينتقل حوالي 10% فقط من الطاقة إلى المستوى التالي.', 'medium', false, 'seed'),
  ('g12-biology-u1-l2-q4', 'g12-biology-u1-l2', 'mcq', 'في السلسلة: عشب ← غزال ← نمر. الغزال يعد:', '["مستهلكاً أول","منتجاً","مستهلكاً ثانياً","محللاً"]'::jsonb, '"مستهلكاً أول"'::jsonb, null, 'الغزال يأكل المنتج مباشرة.', 'easy', false, 'seed'),
  ('g12-biology-u1-l2-q5', 'g12-biology-u1-l2', 'true_false', 'محمية السلاحف في رأس الجنز بعُمان مثال على حماية التنوع الحيوي.', null, 'true'::jsonb, null, 'تحمي المحمية أماكن تعشيش السلاحف.', 'medium', false, 'seed'),
  ('g12-biology-u2-l1-q1', 'g12-biology-u2-l1', 'mcq', 'خط الدفاع الأول في الجسم:', '["الجلد والأغشية المخاطية","الأجسام المضادة","الخلايا الذاكرة","الكبد"]'::jsonb, '"الجلد والأغشية المخاطية"'::jsonb, null, 'يمنع دخول الميكروبات.', 'easy', false, 'seed'),
  ('g12-biology-u2-l1-q2', 'g12-biology-u2-l1', 'mcq', 'الخلايا التي تنتج الأجسام المضادة:', '["الخلايا اللمفاوية البائية","كريات الدم الحمراء","الصفائح الدموية","الخلايا العصبية"]'::jsonb, '"الخلايا اللمفاوية البائية"'::jsonb, null, 'الخلايا البائية تنتج الأجسام المضادة.', 'hard', false, 'seed'),
  ('g12-biology-u2-l1-q3', 'g12-biology-u2-l1', 'true_false', 'اللقاح يحفز الجسم على تكوين مناعة دون الإصابة بالمرض.', null, 'true'::jsonb, null, 'يدرب جهاز المناعة.', 'medium', false, 'seed'),
  ('g12-biology-u2-l1-q4', 'g12-biology-u2-l1', 'true_false', 'المضادات الحيوية تقضي على الفيروسات.', null, 'false'::jsonb, null, 'المضادات الحيوية تعمل ضد البكتيريا لا الفيروسات.', 'medium', false, 'seed'),
  ('g12-biology-u2-l1-q5', 'g12-biology-u2-l1', 'fill_blank', 'البروتينات التي ترتبط بمولدات الضد لتعطيلها تسمى الأجسام ____.', '["المضادة","الحمراء","الدهنية"]'::jsonb, '"المضادة"'::jsonb, null, 'الأجسام المضادة جزء من المناعة النوعية.', 'medium', false, 'seed'),
  ('g12-biology-u2-l2-q1', 'g12-biology-u2-l2', 'mcq', 'الهرمون الذي يخفض سكر الدم:', '["الإنسولين","الأدرينالين","الثيروكسين","هرمون النمو"]'::jsonb, '"الإنسولين"'::jsonb, null, 'يفرزه البنكرياس.', 'easy', false, 'seed'),
  ('g12-biology-u2-l2-q2', 'g12-biology-u2-l2', 'mcq', 'الغدة التي تسمى «سيدة الغدد»:', '["النخامية","الدرقية","الكظرية","البنكرياس"]'::jsonb, '"النخامية"'::jsonb, null, 'تتحكم في عمل كثير من الغدد.', 'medium', false, 'seed'),
  ('g12-biology-u2-l2-q3', 'g12-biology-u2-l2', 'true_false', 'الهرمونات تنتقل في الدم.', null, 'true'::jsonb, null, 'تنقلها الدورة الدموية إلى الأعضاء المستهدفة.', 'easy', false, 'seed'),
  ('g12-biology-u2-l2-q4', 'g12-biology-u2-l2', 'mcq', 'الهرمون المسؤول عن الاستجابة للخوف والطوارئ:', '["الأدرينالين","الإنسولين","الميلاتونين","الجلوكاجون"]'::jsonb, '"الأدرينالين"'::jsonb, null, 'يزيد نبض القلب ويجهز الجسم.', 'medium', false, 'seed'),
  ('g12-biology-u2-l2-q5', 'g12-biology-u2-l2', 'true_false', 'نقص هرمون الإنسولين يسبب مرض السكري.', null, 'true'::jsonb, null, 'السكري من النوع الأول مرتبط بنقص الإنسولين.', 'hard', false, 'seed'),
  ('g12-national-u1-l1-q1', 'g12-national-u1-l1', 'mcq', 'النظام الأساسي للدولة في سلطنة عُمان هو:', '["الوثيقة الدستورية التي تنظم الدولة","قانون المرور","لائحة مدرسية","نظام اقتصادي فقط"]'::jsonb, '"الوثيقة الدستورية التي تنظم الدولة"'::jsonb, null, 'النظام الأساسي يحدد شكل الدولة ونظام الحكم والحقوق والواجبات.', 'easy', false, 'seed'),
  ('g12-national-u1-l1-q2', 'g12-national-u1-l1', 'true_false', 'يكفل النظام الأساسي للدولة حق التعليم للمواطنين.', null, 'true'::jsonb, null, 'التعليم من الحقوق التي يكفلها النظام الأساسي.', 'easy', false, 'seed'),
  ('g12-national-u1-l1-q3', 'g12-national-u1-l1', 'true_false', 'المواطنون متساوون أمام القانون.', null, 'true'::jsonb, null, 'المساواة أمام القانون مبدأ أساسي.', 'easy', false, 'seed'),
  ('g12-national-u1-l1-q4', 'g12-national-u1-l1', 'mcq', 'صدر النظام الأساسي للدولة لأول مرة عام:', '["1970","1996","2010","2020"]'::jsonb, '"1996"'::jsonb, null, 'صدر النظام الأساسي عام 1996م، وصدر نظام أساسي جديد عام 2021م.', 'hard', false, 'seed'),
  ('g12-national-u1-l1-q5', 'g12-national-u1-l1', 'mcq', 'اللغة الرسمية لسلطنة عُمان حسب النظام الأساسي:', '["العربية","الإنجليزية","السواحيلية","الفارسية"]'::jsonb, '"العربية"'::jsonb, null, 'العربية هي اللغة الرسمية.', 'easy', false, 'seed'),
  ('g12-national-u1-l2-q1', 'g12-national-u1-l2', 'mcq', 'يتكون مجلس عُمان من:', '["مجلس الدولة ومجلس الشورى","مجلس الوزراء فقط","المجالس البلدية فقط","المحاكم"]'::jsonb, '"مجلس الدولة ومجلس الشورى"'::jsonb, null, 'مجلس عُمان يضم مجلس الدولة ومجلس الشورى.', 'medium', false, 'seed'),
  ('g12-national-u1-l2-q2', 'g12-national-u1-l2', 'true_false', 'أعضاء مجلس الشورى يُنتخبون من المواطنين.', null, 'true'::jsonb, null, 'يختار المواطنون أعضاء مجلس الشورى بالانتخاب.', 'medium', false, 'seed'),
  ('g12-national-u1-l2-q3', 'g12-national-u1-l2', 'mcq', 'من صور المشاركة المجتمعية:', '["العمل التطوعي","العزلة عن المجتمع","إهمال القضايا العامة","الإضرار بالمرافق"]'::jsonb, '"العمل التطوعي"'::jsonb, null, 'التطوع يخدم المجتمع ويقوّي روابطه.', 'easy', false, 'seed'),
  ('g12-national-u1-l2-q4', 'g12-national-u1-l2', 'mcq', 'تهدف رؤية عُمان 2040 إلى:', '["تنمية مستدامة واقتصاد متنوع","الاعتماد الكامل على النفط","إيقاف التعليم","تقليل الخدمات"]'::jsonb, '"تنمية مستدامة واقتصاد متنوع"'::jsonb, null, 'من أولويات الرؤية التنويع الاقتصادي والتنمية المستدامة.', 'easy', false, 'seed'),
  ('g12-national-u1-l2-q5', 'g12-national-u1-l2', 'fill_blank', 'المجالس ____ تختص بتقديم الآراء والتوصيات في تطوير الخدمات في المحافظات.', '["البلدية","الرياضية","الطلابية"]'::jsonb, '"البلدية"'::jsonb, null, 'المجالس البلدية تهتم بالشؤون المحلية في المحافظات.', 'hard', false, 'seed'),
  ('g12-national-u2-l1-q1', 'g12-national-u2-l1', 'mcq', 'المسؤولية المجتمعية تعني:', '["إسهام الفرد والمؤسسة في خدمة المجتمع","الاهتمام بالنفس فقط","تجاهل مشكلات المجتمع","الإضرار بالبيئة"]'::jsonb, '"إسهام الفرد والمؤسسة في خدمة المجتمع"'::jsonb, null, 'كل فرد مسؤول تجاه مجتمعه.', 'easy', false, 'seed'),
  ('g12-national-u2-l1-q2', 'g12-national-u2-l1', 'true_false', 'التطوع من صور المسؤولية المجتمعية.', null, 'true'::jsonb, null, 'العمل التطوعي يخدم المجتمع.', 'easy', false, 'seed'),
  ('g12-national-u2-l1-q3', 'g12-national-u2-l1', 'mcq', 'من المبادرات التطوعية المناسبة للطلاب:', '["تنظيف الشواطئ","إتلاف الحدائق","نشر الإشاعات","الإسراف في الماء"]'::jsonb, '"تنظيف الشواطئ"'::jsonb, null, 'تنظيف الشواطئ يحمي البيئة.', 'easy', false, 'seed'),
  ('g12-national-u2-l1-q4', 'g12-national-u2-l1', 'true_false', 'المحافظة على المرافق العامة جزء من المسؤولية الوطنية.', null, 'true'::jsonb, null, 'المرافق ملك للجميع.', 'medium', false, 'seed'),
  ('g12-national-u2-l1-q5', 'g12-national-u2-l1', 'fill_blank', 'العمل الذي يقدمه الإنسان بلا مقابل لخدمة الآخرين يسمى العمل ____.', '["التطوعي","الإجباري","التجاري"]'::jsonb, '"التطوعي"'::jsonb, null, 'التطوع عطاء بلا مقابل.', 'easy', false, 'seed'),
  ('g12-national-u2-l2-q1', 'g12-national-u2-l2', 'mcq', 'من الحيوانات المهددة بالانقراض في عُمان:', '["النمر العربي","القطط المنزلية","الدجاج","الماعز"]'::jsonb, '"النمر العربي"'::jsonb, null, 'النمر العربي من الأنواع النادرة.', 'medium', false, 'seed'),
  ('g12-national-u2-l2-q2', 'g12-national-u2-l2', 'mcq', 'محمية طبيعية في عُمان اشتهرت بحماية المها العربي:', '["محمية المها العربي (جدة الحراسيس)","محمية الغابات الاستوائية","محمية الثلوج","محمية البراكين"]'::jsonb, '"محمية المها العربي (جدة الحراسيس)"'::jsonb, null, 'خصصت لحماية المها العربي في الوسطى.', 'hard', false, 'seed'),
  ('g12-national-u2-l2-q3', 'g12-national-u2-l2', 'true_false', 'رمي النفايات البلاستيكية في البحر يضر السلاحف البحرية.', null, 'true'::jsonb, null, 'تبتلع السلاحف البلاستيك ظناً أنه طعام.', 'easy', false, 'seed'),
  ('g12-national-u2-l2-q4', 'g12-national-u2-l2', 'true_false', 'الاحتطاب الجائر يحمي الأشجار البرية.', null, 'false'::jsonb, null, 'الاحتطاب الجائر يدمر الغطاء النباتي.', 'easy', false, 'seed'),
  ('g12-national-u2-l2-q5', 'g12-national-u2-l2', 'mcq', 'أفضل تصرف عند التنزه في الأودية:', '["إعادة النفايات معنا","ترك النفايات","إشعال النار في الأشجار","كتابة الأسماء على الصخور"]'::jsonb, '"إعادة النفايات معنا"'::jsonb, null, 'نترك المكان نظيفاً كما وجدناه.', 'easy', false, 'seed')
insert into public.summaries (lesson_id, content, model, status, approved_at) values
  ('g1-arabic-u1-l1', '{"overview":"الحروف الهجائية ثمانية وعشرون حرفاً، نكتب منها كل الكلمات العربية.","concepts":["أول الحروف الهجائية: أ، ثم ب، ثم ت، ثم ث.","بعض الحروف تتشابه في الشكل وتختلف في عدد النقاط ومكانها، مثل: ب ت ث.","الباء لها نقطة من تحت، والتاء نقطتان من فوق، والثاء ثلاث نقاط من فوق."],"definitions":[],"review":["ما الحرف الذي يأتي بعد الباء؟","ما الفرق بين ب و ت في الكتابة؟"],"example":"ج ح خ: شكلها واحد، والجيم نقطتها في الداخل، والحاء بلا نقطة، والخاء نقطتها فوق."}'::jsonb, 'claude', 'draft', null),
  ('g1-arabic-u1-l2', '{"overview":"نقرأ كلمات قصيرة من حولنا ونعرف معناها.","concepts":["كل كلمة تتكون من حروف متصلة أو منفصلة.","بعض الكلمات تدل على حيوان مثل: قطة، وبعضها على شيء مثل: قلم.","نعرف أول حرف في الكلمة بالاستماع إلى صوتها، مثل: شمس تبدأ بالشين."],"definitions":[],"review":["اذكر كلمة تدل على حيوان.","بأي حرف تبدأ كلمة «قمر»؟"]}'::jsonb, 'claude', 'draft', null),
  ('g1-arabic-u2-l1', '{"overview":"الحركات القصيرة ثلاث: الفتحة والضمة والكسرة، وهي تغيّر صوت الحرف.","concepts":["الفتحة خط صغير فوق الحرف: بَ.","الضمة واو صغيرة فوق الحرف: بُ.","الكسرة خط صغير تحت الحرف: بِ."],"definitions":[{"term":"الحركة","meaning":"علامة صغيرة نضعها على الحرف لنعرف كيف ننطقه."}],"review":["ما الحركة التي تحت الحرف؟","اقرأ: مَ مُ مِ."],"example":"دَ دُ دِ — بَ بُ بِ — سَ سُ سِ"}'::jsonb, 'claude', 'draft', null),
  ('g1-arabic-u2-l2', '{"overview":"المد يجعل صوت الحرف أطول، ويكون بالألف أو الواو أو الياء.","concepts":["المد بالألف بعد الفتحة: بَا، مثل: باب.","المد بالواو بعد الضمة: بُو، مثل: نور.","المد بالياء بعد الكسرة: بِي، مثل: فيل."],"definitions":[],"review":["اذكر كلمة فيها مد بالألف.","ما نوع المد في كلمة «فيل»؟"]}'::jsonb, 'claude', 'draft', null),
  ('g1-english-u1-l1', '{"overview":"We say hello in different ways and we learn the names of colours.","concepts":["Say \"Good morning\" in the morning and \"Hello\" any time.","Answer \"How are you?\" with \"I am fine, thank you.\"","Colours: red, blue, green, yellow, black and white."],"definitions":[],"review":["What do you say in the morning?","What colour is the sky?"],"example":"The sun is yellow. The grass is green."}'::jsonb, 'claude', 'draft', null),
  ('g1-english-u1-l2', '{"overview":"We count from one to ten in English.","concepts":["one, two, three, four, five.","six, seven, eight, nine, ten.","We use numbers to count things: three cats, five pens."],"definitions":[],"review":["What number comes after four?","Count to ten."]}'::jsonb, 'claude', 'draft', null),
  ('g1-english-u2-l1', '{"overview":"We learn the names of body parts and what we do with them.","concepts":["We see with our eyes and hear with our ears.","We smell with our nose and eat with our mouth.","We walk with our feet and hold things with our hands."],"definitions":[],"review":["What do we see with?","What do we walk with?"]}'::jsonb, 'claude', 'draft', null),
  ('g1-english-u2-l2', '{"overview":"We name foods and say what we like.","concepts":["Fruits: apple, banana, dates, orange.","Drinks: water, milk, juice.","We say: \"I like dates.\" or \"I don''t like onions.\""],"definitions":[],"review":["Name a drink.","Say one food you like."]}'::jsonb, 'claude', 'draft', null),
  ('g1-islamic-u1-l1', '{"overview":"الإسلام دين عظيم يقوم على خمسة أركان، وكل مسلم يحفظها ويعمل بها.","concepts":["أركان الإسلام خمسة: الشهادتان، والصلاة، والزكاة، وصوم رمضان، وحج البيت لمن استطاع.","الشهادتان أول الأركان: أشهد أن لا إله إلا الله، وأشهد أن محمداً رسول الله.","الصلاة نصليها كل يوم خمس مرات."],"definitions":[{"term":"الركن","meaning":"الجزء المهم الذي يقوم عليه الشيء."}],"review":["اذكر أركان الإسلام الخمسة بالترتيب.","ما أول ركن من أركان الإسلام؟"]}'::jsonb, 'claude', 'draft', null),
  ('g1-islamic-u1-l2', '{"overview":"علّمنا ديننا آداباً جميلة عند الأكل والشرب تجعلنا نشكر الله على نعمه.","concepts":["نقول «بسم الله» قبل أن نبدأ الأكل.","نأكل باليد اليمنى ومما يلينا.","نقول «الحمد لله» بعد أن ننتهي من الأكل.","نغسل أيدينا قبل الأكل وبعده."],"definitions":[],"review":["ماذا نقول قبل الأكل وبعده؟","بأي يد نأكل؟"]}'::jsonb, 'claude', 'draft', null),
  ('g1-islamic-u2-l1', '{"overview":"التحية في الإسلام هي «السلام عليكم»، وهي تنشر المحبة بين الناس.","concepts":["نبدأ من نلقاه بقولنا: السلام عليكم.","نرد التحية بقولنا: وعليكم السلام، ويمكن أن نزيد: ورحمة الله وبركاته.","نرد التحية بمثلها أو بأحسن منها."],"definitions":[],"review":["ما تحية المسلمين؟","كيف نرد على من قال: السلام عليكم؟"]}'::jsonb, 'claude', 'draft', null),
  ('g1-islamic-u2-l2', '{"overview":"الصدق والأمانة من أجمل الأخلاق، ويحب الله الصادقين الأمناء.","concepts":["الصادق يقول الحقيقة دائماً حتى لو أخطأ.","الأمين يحافظ على أشياء غيره ويعيدها إلى أصحابها.","الكذب وأخذ أشياء الآخرين أخلاق سيئة."],"definitions":[{"term":"الأمانة","meaning":"أن نحافظ على ما ليس لنا ونرده إلى صاحبه."}],"review":["ماذا تفعل إذا وجدت شيئاً ليس لك؟","لماذا نحب الطفل الصادق؟"],"example":"وجدت قلماً ليس لك في الفصل، فأعطيته للمعلم ليعيده إلى صاحبه."}'::jsonb, 'claude', 'draft', null),
  ('g1-math-u1-l1', '{"overview":"نعدّ الأشياء من 1 إلى 20، ونقارن بين عددين لنعرف الأكبر والأصغر.","concepts":["نعدّ الأشياء واحداً واحداً دون أن نكرر شيئاً.","العدد الذي يأتي بعد عدد آخر يكون أكبر منه بواحد.","نقول: 6 أكبر من 4، و4 أصغر من 6."],"definitions":[],"review":["أيهما أكبر: 12 أم 17؟","ما العدد الذي يأتي بعد 19؟"],"example":"العدد بعد 9 هو 10، والعدد قبل 15 هو 14."}'::jsonb, 'claude', 'draft', null),
  ('g1-math-u1-l2', '{"overview":"الجمع يعني أن نضع الأشياء معاً، والطرح يعني أن نأخذ منها.","concepts":["علامة الجمع (+) وعلامة الطرح (−) وعلامة المساواة (=).","عند الجمع يكبر العدد، وعند الطرح يصغر.","يمكن أن نعدّ على أصابعنا أو بالرسم لنحل المسألة."],"definitions":[],"review":["2 + 3 = ؟","كان معك 8 أقلام وأعطيت صديقك 2، كم بقي معك؟"],"example":"معي 6 تمرات وأخذت 4 أخرى: 6 + 4 = 10 تمرات."}'::jsonb, 'claude', 'draft', null),
  ('g1-math-u2-l1', '{"overview":"نتعرف على الأشكال الهندسية من حولنا ونعدّ أضلاعها.","concepts":["المثلث له 3 أضلاع.","المربع له 4 أضلاع متساوية.","المستطيل له 4 أضلاع، كل ضلعين متقابلين متساويان.","الدائرة ليس لها أضلاع."],"definitions":[{"term":"الضلع","meaning":"الخط المستقيم الذي يحد الشكل."}],"review":["كم ضلعاً للمثلث؟","اذكر شكلاً ليس له أضلاع."]}'::jsonb, 'claude', 'draft', null),
  ('g1-math-u2-l2', '{"overview":"نقارن بين أطوال الأشياء باستخدام كلمتي «أطول» و«أقصر».","concepts":["نضع الشيئين بجانب بعضهما من نقطة البداية نفسها لنقارن.","النخلة أطول من الشجيرة، والقلم أقصر من المسطرة.","يمكن أن نرتب الأشياء من الأقصر إلى الأطول."],"definitions":[],"review":["أيهما أطول: الباب أم الكرسي؟","كيف نقارن بين طول قلمين؟"]}'::jsonb, 'claude', 'draft', null),
  ('g1-science-u1-l1', '{"overview":"لنا خمس حواس نتعرف بها على العالم من حولنا.","concepts":["البصر بالعين، والسمع بالأذن، والشم بالأنف.","التذوق باللسان، واللمس بالجلد.","نحافظ على حواسنا ونحميها من الأذى."],"definitions":[{"term":"الحاسة","meaning":"قدرة نعرف بها الأشياء من حولنا."}],"review":["بأي عضو نسمع؟","ما الحاسة التي نعرف بها طعم الحلوى؟"]}'::jsonb, 'claude', 'draft', null),
  ('g1-science-u1-l2', '{"overview":"النظافة تحمينا من الجراثيم والأمراض.","concepts":["نغسل أيدينا بالماء والصابون قبل الأكل وبعده وبعد اللعب.","ننظف أسناننا بالفرشاة صباحاً وقبل النوم.","نستحم ونلبس ملابس نظيفة ونقص أظافرنا."],"definitions":[{"term":"الجراثيم","meaning":"كائنات صغيرة جداً لا نراها، وقد تسبب المرض."}],"review":["متى نغسل أيدينا؟","لماذا ننظف أسناننا كل يوم؟"]}'::jsonb, 'claude', 'draft', null),
  ('g1-science-u2-l1', '{"overview":"تعيش الحيوانات في أماكن مختلفة تناسبها.","concepts":["بعض الحيوانات تعيش في الماء مثل السمكة.","بعضها يعيش على اليابسة مثل الجمل في الصحراء.","الطيور تبني أعشاشها على الأشجار."],"definitions":[],"review":["أين تعيش السمكة؟","اذكر حيواناً يعيش في الصحراء."],"example":"الجمل يتحمل العطش والحر، لذلك يعيش في الصحراء."}'::jsonb, 'claude', 'draft', null),
  ('g1-science-u2-l2', '{"overview":"لكل حيوان صغار لها أسماء، والأمهات تعتني بصغارها.","concepts":["صغير القطة هريرة، وصغير الدجاجة كتكوت.","صغير الناقة حُوار، وصغير البقرة عجل.","الأم تطعم صغارها وتحميها حتى تكبر."],"definitions":[],"review":["ما اسم صغير الدجاجة؟","كيف تعتني الحيوانات بصغارها؟"]}'::jsonb, 'claude', 'draft', null),
  ('g10-arabic-u1-l1', '{"overview":"النثر كلام غير موزون، ومن فنونه القصة والمقالة والخطبة والرسالة.","concepts":["القصة: سرد لأحداث متخيلة أو واقعية.","عناصر القصة: الشخصيات، والزمان، والمكان، والأحداث، والعقدة، والحل.","المقالة تعرض فكرة بأسلوب منظم، والخطبة تخاطب الجمهور للإقناع."],"definitions":[{"term":"العقدة","meaning":"ذروة الأحداث في القصة."}],"review":["اذكر عناصر القصة.","ما الفرق بين المقالة والخطبة؟"]}'::jsonb, 'claude', 'draft', null),
  ('g10-arabic-u1-l2', '{"overview":"الشعر كلام موزون مقفى يعبّر عن المشاعر.","concepts":["البيت الشعري يتكون من شطرين: الصدر والعجز.","الشعر العمودي يلتزم وزناً واحداً وقافية واحدة.","شعر التفعيلة يعتمد على التفعيلة ولا يلتزم عدداً ثابتاً منها في السطر."],"definitions":[{"term":"القافية","meaning":"الحروف التي يلتزمها الشاعر في آخر الأبيات."}],"review":["ما شطرا البيت الشعري؟","ما الفرق بين الشعر العمودي وشعر التفعيلة؟"]}'::jsonb, 'claude', 'draft', null),
  ('g10-arabic-u2-l1', '{"overview":"المفعول المطلق مصدر منصوب يُذكر بعد فعل من لفظه.","concepts":["يؤكد الفعل: فرحتُ فرحاً.","يبيّن النوع: سرتُ سيرَ الواثقين.","يبيّن العدد: قفزتُ قفزتين."],"definitions":[],"review":["استخرج المفعول المطلق: اجتهد الطالب اجتهاداً.","ما نوع المفعول المطلق في: ضربتُ الكرة ضربتين؟"]}'::jsonb, 'claude', 'draft', null),
  ('g10-arabic-u2-l2', '{"overview":"المفعول لأجله مصدر منصوب يبيّن سبب حدوث الفعل.","concepts":["يجيب عن سؤال: لماذا؟","في «وقف الطلابُ احتراماً للمعلم» المفعول لأجله: احتراماً.","يكون غالباً مصدراً قلبياً مثل: حباً، خوفاً، رغبةً."],"definitions":[],"review":["استخرج المفعول لأجله: ذاكرتُ رغبةً في النجاح.","عن أي سؤال يجيب المفعول لأجله؟"]}'::jsonb, 'claude', 'draft', null),
  ('g10-english-u1-l1', '{"overview":"We use the passive voice when the action is more important than who did it.","concepts":["Form: be + past participle.","Active: People speak Arabic in Oman. → Passive: Arabic is spoken in Oman.","We can add \"by\" for the doer: The fort was built by the Ya''ruba."],"definitions":[],"review":["Change to passive: They clean the room every day.","Why do we use the passive?"]}'::jsonb, 'claude', 'draft', null),
  ('g10-english-u1-l2', '{"overview":"We discuss environmental problems and suggest solutions.","concepts":["Problems: pollution, plastic waste, water shortage, climate change.","Solutions: recycle, reduce plastic, save water, plant trees.","Use \"We should...\" and \"It is important to...\""],"definitions":[],"review":["Name two environmental problems.","Suggest a solution with \"We should\"."]}'::jsonb, 'claude', 'draft', null),
  ('g10-english-u2-l1', '{"overview":"We express opinions and agree or disagree politely.","concepts":["Opinions: In my opinion..., I think..., I believe...","Agree: I agree with you. That''s a good point.","Disagree politely: I see your point, but..."],"definitions":[],"review":["Give your opinion about homework.","How can you disagree politely?"]}'::jsonb, 'claude', 'draft', null),
  ('g10-english-u2-l2', '{"overview":"We use linking words to connect ideas clearly.","concepts":["Adding: and, also, moreover.","Contrast: but, however, although.","Result: so, therefore. Sequence: first, then, finally."],"definitions":[],"review":["Join with \"however\": It was hot. We played outside.","Name two linking words for adding ideas."]}'::jsonb, 'claude', 'draft', null),
  ('g10-islamic-u1-l1', '{"overview":"الحج ركن من أركان الإسلام، يجب مرة في العمر على المسلم المستطيع.","concepts":["شروط وجوبه: الإسلام، والبلوغ، والعقل، والحرية، والاستطاعة.","من أركانه: الإحرام، والوقوف بعرفة، وطواف الإفاضة، والسعي.","الوقوف بعرفة أعظم أركانه، وهو في اليوم التاسع من ذي الحجة."],"definitions":[{"term":"الإحرام","meaning":"نية الدخول في النسك."}],"review":["اذكر شروط وجوب الحج.","متى يكون الوقوف بعرفة؟"]}'::jsonb, 'claude', 'draft', null),
  ('g10-islamic-u1-l2', '{"overview":"غزوة بدر أول معركة كبرى بين المسلمين وقريش، وقعت في رمضان من السنة الثانية للهجرة.","concepts":["كان المسلمون نحو 313 رجلاً والمشركون نحو ألف.","نصر الله المسلمين رغم قلة عددهم.","من دروسها: التوكل على الله مع الأخذ بالأسباب، والشورى، والثبات."],"definitions":[],"review":["متى وقعت غزوة بدر؟","اذكر درسين من الغزوة."]}'::jsonb, 'claude', 'draft', null),
  ('g10-islamic-u2-l1', '{"overview":"اللسان نعمة، وحفظه من الآفات طريق إلى رضا الله.","concepts":["الغيبة: ذكر أخيك بما يكره في غيابه.","النميمة: نقل الكلام بين الناس للإفساد.","قال ﷺ: «من كان يؤمن بالله واليوم الآخر فليقل خيراً أو ليصمت»."],"definitions":[],"review":["ما الفرق بين الغيبة والنميمة؟","كيف نحفظ ألسنتنا؟"]}'::jsonb, 'claude', 'draft', null),
  ('g10-islamic-u2-l2', '{"overview":"العفو ترك معاقبة المسيء مع القدرة، وهو من أخلاق المؤمنين.","concepts":["قال تعالى: ﴿وَلْيَعْفُوا وَلْيَصْفَحُوا﴾.","عفا النبي ﷺ عن أهل مكة يوم الفتح.","التسامح ينشر المحبة ويقلل الخصومات في المجتمع."],"definitions":[{"term":"العفو","meaning":"التجاوز عن خطأ المسيء."}],"review":["ما العفو؟","اذكر أثراً للتسامح في المجتمع."]}'::jsonb, 'claude', 'draft', null),
  ('g10-math-u1-l1', '{"overview":"نظام المعادلتين يُحل بإيجاد قيمتي المتغيرين اللتين تحققانهما معاً.","concepts":["التعويض: نعبّر عن أحد المتغيرين من معادلة ونعوض في الأخرى.","الحذف: نجمع أو نطرح المعادلتين لحذف متغير.","الحل نقطة تقاطع المستقيمين."],"definitions":[],"review":["حل: x + y = 7، x − y = 1.","ما المعنى البياني لحل النظام؟"],"example":"x + y = 10، x − y = 2: بالجمع 2x = 12 ← x = 6، y = 4."}'::jsonb, 'claude', 'draft', null),
  ('g10-math-u1-l2', '{"overview":"الدالة علاقة تربط كل مدخل بمخرج واحد فقط.","concepts":["نكتب الدالة: f(x) = 2x + 1.","لحساب f(3) نعوض x = 3: f(3) = 7.","مجال الدالة: مجموعة المدخلات، ومداها: مجموعة المخرجات."],"definitions":[],"review":["إذا f(x) = x² − 1 فما f(4)؟","هل كل علاقة دالة؟ ولماذا؟"]}'::jsonb, 'claude', 'draft', null),
  ('g10-math-u2-l1', '{"overview":"النسب المثلثية تربط زوايا المثلث القائم بأطوال أضلاعه.","concepts":["جا θ = المقابل ÷ الوتر.","جتا θ = المجاور ÷ الوتر.","ظا θ = المقابل ÷ المجاور."],"definitions":[],"review":["ما تعريف ظا θ؟","احسب جا θ إذا كان المقابل 5 والوتر 13."],"example":"مثلث قائم: المقابل 3، والمجاور 4، والوتر 5: جا θ = 3/5، وجتا θ = 4/5، وظا θ = 3/4."}'::jsonb, 'claude', 'draft', null),
  ('g10-math-u2-l2', '{"overview":"المتتابعة الحسابية يكون الفرق بين كل حدين متتاليين ثابتاً.","concepts":["الفرق المشترك d = الحد الثاني − الحد الأول.","الحد العام: aₙ = a₁ + (n − 1)d.","مثال: 3، 7، 11، 15… الفرق 4."],"definitions":[],"review":["ما الفرق المشترك في 5، 8، 11؟","احسب الحد العشرين في 2، 4، 6…"],"example":"الحد العاشر في 3، 7، 11…: a₁₀ = 3 + 9 × 4 = 39."}'::jsonb, 'claude', 'draft', null),
  ('g10-science-u1-l1', '{"overview":"الوراثة انتقال الصفات من الآباء إلى الأبناء عبر الجينات.","concepts":["الكروموسومات في نواة الخلية وتحمل الجينات.","الجين جزء من DNA يحدد صفة معينة.","الصفة السائدة تظهر عند وجود جين واحد لها، والمتنحية لا تظهر إلا مع جينين متنحيين."],"definitions":[{"term":"الجين","meaning":"وحدة الوراثة التي تحدد الصفة."}],"review":["أين توجد الكروموسومات؟","ما الفرق بين الصفة السائدة والمتنحية؟"]}'::jsonb, 'claude', 'draft', null),
  ('g10-science-u1-l2', '{"overview":"الشغل ينجز عندما تحرك قوة جسماً مسافة في اتجاهها.","concepts":["الشغل = القوة × المسافة، ووحدته الجول.","الطاقة الحركية طاقة الجسم بسبب حركته.","طاقة الوضع طاقة مختزنة بسبب موضع الجسم أو ارتفاعه."],"definitions":[],"review":["ما وحدة الشغل؟","متى تكون طاقة الوضع أكبر؟"],"example":"قوة 10 نيوتن حركت صندوقاً 5 م: الشغل = 50 جول."}'::jsonb, 'claude', 'draft', null),
  ('g10-science-u2-l1', '{"overview":"الروابط الكيميائية تربط الذرات لتكوين المركبات.","concepts":["الرابطة الأيونية: انتقال إلكترونات من فلز إلى لافلز، مثل NaCl.","الرابطة التساهمية: مشاركة إلكترونات بين لافلزات، مثل H₂O.","المركبات الأيونية غالباً صلبة ذات درجات انصهار عالية."],"definitions":[],"review":["ما نوع الرابطة في ملح الطعام؟","ما الفرق بين الرابطتين الأيونية والتساهمية؟"]}'::jsonb, 'claude', 'draft', null),
  ('g10-science-u2-l2', '{"overview":"الموجة اضطراب ينقل الطاقة دون نقل المادة.","concepts":["خصائص الموجة: الطول الموجي، والتردد، والسعة.","الصوت موجة طولية تحتاج إلى وسط ولا تنتقل في الفراغ.","سرعة الموجة = التردد × الطول الموجي."],"definitions":[],"review":["لماذا لا ينتقل الصوت في الفضاء؟","اذكر خصائص الموجة."]}'::jsonb, 'claude', 'draft', null),
  ('g10-social-u1-l1', '{"overview":"تأسس مجلس التعاون لدول الخليج العربية عام 1981.","concepts":["الدول الأعضاء: عُمان، والسعودية، والإمارات، والكويت، وقطر، والبحرين.","مقره الرياض.","من أهدافه: التعاون في الاقتصاد والأمن والتعليم وتعزيز الروابط بين شعوبه."],"definitions":[],"review":["متى تأسس مجلس التعاون؟","اذكر هدفين للمجلس."]}'::jsonb, 'claude', 'draft', null),
  ('g10-social-u1-l2', '{"overview":"تقوم السياسة الخارجية العمانية على السلام وحسن الجوار والحوار.","concepts":["عدم التدخل في الشؤون الداخلية للدول.","حل الخلافات بالطرق السلمية والحوار.","قامت عُمان بأدوار في الوساطة بين دول متنازعة."],"definitions":[],"review":["اذكر مبدأين من مبادئ السياسة الخارجية العمانية.","ما دور عُمان في الوساطة؟"]}'::jsonb, 'claude', 'draft', null),
  ('g10-social-u2-l1', '{"overview":"تواجه عُمان تحديات في الموارد المائية لقلة الأمطار.","concepts":["مصادر المياه: الأفلاج، والآبار، والسدود، وتحلية مياه البحر.","من التحديات: الجفاف، وزيادة الاستهلاك، وتملح المياه الجوفية.","من الحلول: الري الحديث، وإعادة استخدام المياه المعالجة، وترشيد الاستهلاك."],"definitions":[],"review":["اذكر مصدرين للمياه في عُمان.","اقترح حلاً لترشيد استهلاك المياه."]}'::jsonb, 'claude', 'draft', null),
  ('g10-social-u2-l2', '{"overview":"تمتلك عُمان مقومات سياحية طبيعية وتراثية متنوعة.","concepts":["المقومات الطبيعية: الشواطئ والجبال والأودية والصحارى وخريف ظفار.","المقومات التراثية: القلاع والحصون والأسواق التقليدية.","السياحة توفر فرص عمل وتنوع مصادر الدخل."],"definitions":[],"review":["اذكر مقومين سياحيين في عُمان.","ما أثر السياحة في الاقتصاد؟"]}'::jsonb, 'claude', 'draft', null),
  ('g11-arabic-u1-l1', '{"overview":"الاستعارة تشبيه حُذف أحد طرفيه.","concepts":["الاستعارة التصريحية: يُصرّح فيها بالمشبه به ويُحذف المشبه، مثل: رأيتُ أسداً يخطب (الأسد = الرجل الشجاع).","الاستعارة المكنية: يُحذف المشبه به ويُرمز إليه بشيء من لوازمه، مثل: تبتسم الأزهار.","الاستعارة أبلغ من التشبيه لأنها تدمج الطرفين."],"definitions":[],"review":["ما نوع الاستعارة في: غرّد الطفل؟","ما الفرق بين الاستعارة والتشبيه؟"]}'::jsonb, 'claude', 'draft', null),
  ('g11-arabic-u1-l2', '{"overview":"المحسنات البديعية تزيّن الكلام لفظاً أو معنى.","concepts":["الطباق: الجمع بين الكلمة وضدها، مثل: الليل والنهار.","الجناس: تشابه كلمتين في اللفظ واختلافهما في المعنى.","السجع: توافق أواخر الفواصل في الحرف الأخير في النثر."],"definitions":[],"review":["استخرج الطباق: يحيي ويميت.","عرّف السجع."]}'::jsonb, 'claude', 'draft', null),
  ('g11-arabic-u2-l1', '{"overview":"الشعر الجاهلي صورة لحياة العرب وبيئتهم قبل الإسلام.","concepts":["من سماته: وصف الصحراء والناقة، والفخر، والوقوف على الأطلال.","المعلقات من أشهر قصائده، ومن أصحابها امرؤ القيس.","يُعد مصدراً مهماً للغة العربية وتاريخ العرب."],"definitions":[],"review":["اذكر سمتين من سمات الشعر الجاهلي.","من أشهر شعراء المعلقات؟"]}'::jsonb, 'claude', 'draft', null),
  ('g11-arabic-u2-l2', '{"overview":"النقد الأدبي دراسة النص وتقويمه ببيان جماله وعيوبه.","concepts":["من عناصر النص: العاطفة، والفكرة، والخيال، والأسلوب.","صدق العاطفة أن يعبّر الكاتب عن شعور حقيقي.","الصور البيانية من وسائل جمال النص."],"definitions":[],"review":["عرّف النقد الأدبي.","اذكر عنصرين من عناصر النص الأدبي."]}'::jsonb, 'claude', 'draft', null),
  ('g11-biology-u1-l1', '{"overview":"الخلية تحتوي على عضيات لكل منها وظيفة.","concepts":["الميتوكوندريا تنتج الطاقة، والرايبوسومات تصنع البروتين.","البلاستيدات الخضراء في الخلايا النباتية للبناء الضوئي.","الخلية بدائية النواة (كالبكتيريا) لا غلاف لنواتها، والحقيقية لها نواة محاطة بغلاف."],"definitions":[],"review":["ما وظيفة الميتوكوندريا؟","ما الفرق بين الخلية بدائية النواة وحقيقية النواة؟"]}'::jsonb, 'claude', 'draft', null),
  ('g11-biology-u1-l2', '{"overview":"الانقسام الخلوي نوعان: متساوٍ للنمو، ومنصّف لتكوين الأمشاج.","concepts":["الانقسام المتساوي ينتج خليتين متطابقتين بعدد الكروموسومات نفسه.","مراحله: التمهيدية، والاستوائية، والانفصالية، والنهائية.","الانقسام المنصف ينتج أربع خلايا بنصف عدد الكروموسومات."],"definitions":[],"review":["رتب مراحل الانقسام المتساوي.","ما الغرض من الانقسام المنصف؟"]}'::jsonb, 'claude', 'draft', null),
  ('g11-biology-u2-l1', '{"overview":"الإنزيمات بروتينات تسرّع التفاعلات الحيوية.","concepts":["لكل إنزيم مادة تفاعل خاصة (نموذج القفل والمفتاح).","تتأثر بدرجة الحرارة والرقم الهيدروجيني.","الحرارة العالية جداً تغيّر بنية الإنزيم فيفقد نشاطه، والأميليز يهضم النشا في الفم."],"definitions":[],"review":["ما طبيعة الإنزيمات؟","اذكر عاملين يؤثران في نشاط الإنزيم."]}'::jsonb, 'claude', 'draft', null),
  ('g11-biology-u2-l2', '{"overview":"تنتقل المواد عبر غشاء الخلية بطرق مختلفة.","concepts":["الانتشار: من التركيز المرتفع إلى المنخفض دون طاقة.","الخاصية الأسموزية: انتشار الماء عبر غشاء شبه منفذ.","النقل النشط: ضد منحدر التركيز ويحتاج طاقة ATP."],"definitions":[],"review":["ما الفرق بين الانتشار والنقل النشط؟","عرّف الخاصية الأسموزية."],"example":"خلية دم حمراء في ماء مقطر تنتفخ لأن الماء يدخلها بالأسموزية."}'::jsonb, 'claude', 'draft', null),
  ('g11-chemistry-u1-l1', '{"overview":"تتكون الذرة من نواة فيها بروتونات ونيوترونات، وتدور حولها إلكترونات.","concepts":["البروتون موجب، والإلكترون سالب، والنيوترون متعادل.","العدد الذري = عدد البروتونات.","عدد النيوترونات = العدد الكتلي − العدد الذري."],"definitions":[],"review":["ما شحنة الإلكترون؟","احسب نيوترونات ذرة عددها الذري 6 والكتلي 12."],"example":"الصوديوم: العدد الذري 11 والكتلي 23 ← 12 نيوتروناً."}'::jsonb, 'claude', 'draft', null),
  ('g11-chemistry-u1-l2', '{"overview":"الجدول الدوري يرتب العناصر تصاعدياً حسب العدد الذري.","concepts":["الصفوف الأفقية دورات، والأعمدة الرأسية مجموعات.","عناصر المجموعة الواحدة متشابهة في الخصائص لتشابه إلكترونات التكافؤ.","الفلزات على اليسار، واللافلزات على اليمين، والغازات النبيلة في المجموعة الأخيرة."],"definitions":[],"review":["ما أساس ترتيب العناصر في الجدول الدوري؟","لماذا تتشابه عناصر المجموعة الواحدة؟"]}'::jsonb, 'claude', 'draft', null),
  ('g11-chemistry-u2-l1', '{"overview":"المول وحدة لقياس كمية المادة.","concepts":["المول يحتوي على 6.02 × 10²³ جسيماً (عدد أفوجادرو).","الكتلة المولية مجموع الكتل الذرية في الصيغة.","عدد المولات = الكتلة ÷ الكتلة المولية."],"definitions":[],"review":["ما الكتلة المولية لـ CO₂؟","كم مولاً في 9 غ من الماء؟"],"example":"36 غ من الماء (18 غ/مول) = 2 مول."}'::jsonb, 'claude', 'draft', null),
  ('g11-chemistry-u2-l2', '{"overview":"تُصنف التفاعلات الكيميائية إلى أنواع حسب ما يحدث للمواد.","concepts":["الاتحاد: A + B → AB.","التفكك: AB → A + B.","الإحلال، والتعادل (حمض + قاعدة → ملح + ماء)، والاحتراق الذي ينتج CO₂ وH₂O."],"definitions":[],"review":["ما نوع التفاعل AB → A + B؟","ماذا ينتج من تفاعل حمض مع قاعدة؟"]}'::jsonb, 'claude', 'draft', null),
  ('g11-english-u1-l1', '{"overview":"We use conditionals to talk about real and imaginary situations.","concepts":["First conditional (real future): If it rains, we will stay at home.","Second conditional (imaginary): If I had a million rials, I would build a school.","The if-clause can come first or second."],"definitions":[],"review":["Complete: If you study hard, you ____ pass.","Make a second conditional sentence."]}'::jsonb, 'claude', 'draft', null),
  ('g11-english-u1-l2', '{"overview":"We talk about careers, skills and job applications.","concepts":["Skills: teamwork, communication, problem-solving.","A job application includes your experience and why you want the job.","Formal phrases: \"I am writing to apply for...\", \"I would welcome the opportunity...\""],"definitions":[],"review":["Name two important work skills.","How do you start a job application?"]}'::jsonb, 'claude', 'draft', null),
  ('g11-english-u2-l1', '{"overview":"We report questions without question word order.","concepts":["\"Where do you live?\" → She asked me where I lived.","Yes/no questions use \"if\" or \"whether\": He asked if I was ready.","Tenses move back and there is no question mark."],"definitions":[],"review":["Report: \"Can you help?\"","Why is there no question mark in reported questions?"]}'::jsonb, 'claude', 'draft', null),
  ('g11-english-u2-l2', '{"overview":"Phrasal verbs are verbs with a particle that change the meaning.","concepts":["look up = find in a dictionary; give up = stop trying.","find out = discover; turn off = switch off.","look after = take care of."],"definitions":[],"review":["What does \"give up\" mean?","Use \"look after\" in a sentence."]}'::jsonb, 'claude', 'draft', null),
  ('g11-islamic-u1-l1', '{"overview":"جاءت الشريعة الإسلامية لحفظ خمس ضروريات لا تستقيم الحياة بدونها.","concepts":["الضروريات الخمس: الدين، والنفس، والعقل، والنسل، والمال.","حفظ النفس بتحريم القتل، وحفظ العقل بتحريم المسكرات والمخدرات.","حفظ المال بتحريم السرقة والغش، وحفظ النسل بتشريع الزواج."],"definitions":[{"term":"مقاصد الشريعة","meaning":"الغايات التي جاءت الشريعة لتحقيقها."}],"review":["اذكر الضروريات الخمس.","بأي حكم تحفظ الشريعة العقل؟"]}'::jsonb, 'claude', 'draft', null),
  ('g11-islamic-u1-l2', '{"overview":"الحوار وسيلة للتفاهم، وللاختلاف في الإسلام آداب.","concepts":["من آداب الحوار: الإنصات، وحسن الكلام، واحترام المخالف، والرجوع إلى الحق.","الاختلاف في الآراء الاجتهادية مقبول، والتعصب والسب مذمومان.","قال تعالى: ﴿وَجَادِلْهُم بِالَّتِي هِيَ أَحْسَنُ﴾."],"definitions":[],"review":["اذكر ثلاثة من آداب الحوار.","متى يكون الاختلاف محموداً؟"]}'::jsonb, 'claude', 'draft', null),
  ('g11-islamic-u2-l1', '{"overview":"حثّ الإسلام على الكسب الحلال وجعل المال أمانة يُسأل عنها الإنسان.","concepts":["من صور الكسب الحلال: العمل والتجارة المشروعة.","حرّم الإسلام الرشوة والغش والاحتكار والربا.","يُسأل الإنسان عن ماله من أين اكتسبه وفيم أنفقه."],"definitions":[],"review":["اذكر صورتين للكسب الحلال.","ما الاحتكار ولماذا حُرّم؟"]}'::jsonb, 'claude', 'draft', null),
  ('g11-islamic-u2-l2', '{"overview":"الوقف حبس الأصل وتسبيل منفعته في وجوه الخير.","concepts":["يبقى أصل الوقف ويُنتفع بريعه، كمسجد أو مكتبة أو بئر.","الوقف صدقة جارية يستمر أجرها بعد موت صاحبه.","دعمت الأوقاف عبر التاريخ التعليم والصحة والخدمات، وتشرف عليها في عُمان وزارة الأوقاف والشؤون الدينية."],"definitions":[{"term":"الوقف","meaning":"حبس الأصل وجعل منفعته للخير."}],"review":["ما الوقف؟","اذكر مثالين على الأوقاف."]}'::jsonb, 'claude', 'draft', null),
  ('g11-math-u1-l1', '{"overview":"المعادلة التربيعية صورتها ax² + bx + c = 0، ولها حتى حلان.","concepts":["نحلها بالتحليل: x² − 5x + 6 = 0 ← (x − 2)(x − 3) = 0 ← x = 2 أو 3.","المميز Δ = b² − 4ac يحدد عدد الحلول.","Δ > 0 حلان، وΔ = 0 حل واحد، وΔ < 0 لا حلول حقيقية."],"definitions":[{"term":"المميز","meaning":"b² − 4ac"}],"review":["حل: x² − 9 = 0.","كم حلاً للمعادلة x² + 2x + 5 = 0؟"]}'::jsonb, 'claude', 'draft', null),
  ('g11-math-u1-l2', '{"overview":"المشتقة تقيس معدل تغير الدالة، وتمثل ميل المماس.","concepts":["قاعدة القوة: مشتقة xⁿ هي n·xⁿ⁻¹.","مشتقة الثابت صفر، ومشتقة ax هي a.","نشتق كثيرة الحدود حداً حداً."],"definitions":[],"review":["اشتق: x⁴.","ما ميل المماس لـ y = x² عند x = 3؟"],"example":"f(x) = 3x² + 2x − 5 ← f′(x) = 6x + 2."}'::jsonb, 'claude', 'draft', null),
  ('g11-math-u2-l1', '{"overview":"المتجه كمية لها مقدار واتجاه.","concepts":["نجمع المتجهات بجمع المركبات المتناظرة: (2، 3) + (1، −1) = (3، 2).","طول المتجه (a، b) = √(a² + b²).","ضرب المتجه في عدد سالب يعكس اتجاهه."],"definitions":[],"review":["اجمع (1، 2) و(4، −3).","ما طول المتجه (6، 8)؟"],"example":"طول المتجه (3، 4) = √(9 + 16) = 5."}'::jsonb, 'claude', 'draft', null),
  ('g11-math-u2-l2', '{"overview":"المصفوفة ترتيب للأعداد في صفوف وأعمدة.","concepts":["رتبة المصفوفة = عدد الصفوف × عدد الأعمدة.","نجمع مصفوفتين من الرتبة نفسها بجمع العناصر المتناظرة.","محدد المصفوفة [[a، b]، [c، d]] = ad − bc."],"definitions":[],"review":["ما رتبة مصفوفة فيها 3 صفوف وعمودان؟","احسب محدد [[1، 2]، [3، 4]]."],"example":"محدد [[2، 1]، [4، 3]] = 2×3 − 1×4 = 2."}'::jsonb, 'claude', 'draft', null),
  ('g11-national-u1-l1', '{"overview":"المواطنة انتماء للوطن يترتب عليه حقوق وواجبات.","concepts":["من الحقوق: التعليم، والرعاية الصحية، والأمن.","من الواجبات: احترام القانون، والمحافظة على الممتلكات العامة، والإخلاص في العمل.","المواطن الصالح يشارك في بناء وطنه."],"definitions":[],"review":["عرّف المواطنة.","اذكر حقاً وواجباً للمواطن."]}'::jsonb, 'claude', 'draft', null),
  ('g11-national-u1-l2', '{"overview":"للهوية العمانية مكونات تميزها وتربط أبناءها.","concepts":["من مكوناتها: الدين الإسلامي، واللغة العربية، والتاريخ، والعادات.","من الموروث: الزي العماني، والقهوة العمانية، والفنون الشعبية، والضيافة.","المحافظة على الهوية مع الانفتاح على العالم."],"definitions":[],"review":["اذكر ثلاثة مكونات للهوية العمانية.","كيف نحافظ على الموروث الثقافي؟"]}'::jsonb, 'claude', 'draft', null),
  ('g11-national-u2-l1', '{"overview":"رؤية عُمان 2040 خطة وطنية لمستقبل السلطنة.","concepts":["من محاورها: الإنسان والمجتمع، والاقتصاد والتنمية، والحوكمة، والبيئة المستدامة.","من أولوياتها: التعليم والبحث العلمي والتنويع الاقتصادي.","للشباب دور أساسي في تحقيقها بالتعلم والعمل والإبداع."],"definitions":[],"review":["اذكر محورين من محاور الرؤية.","ما دورك في تحقيق الرؤية؟"]}'::jsonb, 'claude', 'draft', null),
  ('g11-national-u2-l2', '{"overview":"ريادة الأعمال إنشاء مشروع جديد وإدارته وتحمّل مخاطره.","concepts":["صفات رائد الأعمال: المبادرة، والإبداع، والمثابرة، وتحمل المسؤولية.","دراسة الجدوى قبل البدء تقيس فرص النجاح.","المؤسسات الصغيرة والمتوسطة توفر فرص عمل وتنوع الاقتصاد."],"definitions":[{"term":"دراسة الجدوى","meaning":"تقييم المشروع قبل تنفيذه."}],"review":["اذكر ثلاث صفات لرائد الأعمال.","لماذا نقوم بدراسة الجدوى؟"]}'::jsonb, 'claude', 'draft', null),
  ('g11-physics-u1-l1', '{"overview":"نميز بين الكميات القياسية والمتجهة في وصف الحركة.","concepts":["المسافة طول المسار الكلي (قياسية)، والإزاحة أقصر خط بين البداية والنهاية مع الاتجاه (متجهة).","السرعة القياسية = المسافة ÷ الزمن.","السرعة المتجهة = الإزاحة ÷ الزمن."],"definitions":[],"review":["ما الفرق بين المسافة والإزاحة؟","هل يمكن أن تكون الإزاحة صفراً والمسافة غير صفر؟"],"example":"عدّاء دار حول مضمار 400 م وعاد لنقطة البداية: المسافة 400 م والإزاحة صفر."}'::jsonb, 'claude', 'draft', null),
  ('g11-physics-u1-l2', '{"overview":"التسارع معدل تغير السرعة المتجهة.","concepts":["التسارع a = (v − u) ÷ t، ووحدته م/ث².","معادلات الحركة: v = u + at، وs = ut + ½at²، وv² = u² + 2as.","التسارع السالب يعني تباطؤاً."],"definitions":[],"review":["ما وحدة التسارع؟","جسم بدأ من السكون بتسارع 2 م/ث²، كم سرعته بعد 3 ث؟"],"example":"سيارة من السكون إلى 20 م/ث في 5 ث: a = 4 م/ث²."}'::jsonb, 'claude', 'draft', null),
  ('g11-physics-u2-l1', '{"overview":"المقذوف يتحرك في بعدين، ونحلل حركته إلى مركبتين.","concepts":["المركبة الأفقية للسرعة ثابتة بإهمال مقاومة الهواء.","المركبة الرأسية تتأثر بتسارع الجاذبية.","المسار قطع مكافئ، والسرعة الرأسية صفر عند أقصى ارتفاع."],"definitions":[],"review":["لماذا تبقى المركبة الأفقية ثابتة؟","ما السرعة الرأسية عند أقصى ارتفاع؟"]}'::jsonb, 'claude', 'draft', null),
  ('g11-physics-u2-l2', '{"overview":"الزخم حاصل ضرب الكتلة في السرعة، وهو كمية محفوظة.","concepts":["p = m × v، ووحدته كغ·م/ث.","في النظام المعزول يبقى الزخم الكلي ثابتاً.","الدفع = القوة × الزمن = التغير في الزخم."],"definitions":[],"review":["ما قانون حفظ الزخم؟","احسب زخم كرة كتلتها 0.5 كغ وسرعتها 8 م/ث."],"example":"جسم كتلته 2 كغ وسرعته 5 م/ث: زخمه 10 كغ·م/ث."}'::jsonb, 'claude', 'draft', null),
  ('g12-arabic-u1-l1', '{"overview":"الممنوع من الصرف اسم لا يُنوَّن ويُجر بالفتحة.","concepts":["من أمثلته: الأعلام الأعجمية والمؤنثة مثل إبراهيم وفاطمة.","وصيغة منتهى الجموع مثل: مساجد، مصابيح.","يُجر بالكسرة إذا عُرّف بـ «ال» أو أُضيف: في المساجدِ."],"definitions":[],"review":["ما علامة جر الممنوع من الصرف؟","متى يُجر بالكسرة؟"],"example":"مررتُ بمساجدَ كثيرة ← مجرور بالفتحة."}'::jsonb, 'claude', 'draft', null),
  ('g12-arabic-u1-l2', '{"overview":"أسلوب الشرط يتكون من أداة وفعل شرط وجوابه.","concepts":["من أدوات الشرط الجازمة: إنْ، مَن، ما، متى، أينما.","في «إنْ تجتهدْ تنجحْ»: إن أداة، وتجتهد فعل الشرط، وتنجح جوابه.","تجزم الأداة فعل الشرط وجوابه."],"definitions":[],"review":["حدد أركان الشرط: من يزرعْ يحصدْ.","اذكر ثلاث أدوات شرط جازمة."]}'::jsonb, 'claude', 'draft', null),
  ('g12-arabic-u2-l1', '{"overview":"التعجب انفعال يحدث في النفس عند رؤية شيء عظيم.","concepts":["صيغتا التعجب القياسيتان: ما أفعلَه! وأفعِلْ به!","مثال: ما أجملَ السماءَ! أكرِمْ بالمعلمِ!","المتعجب منه بعد «ما أفعل» مفعول به منصوب."],"definitions":[],"review":["تعجب من جمال البحر.","أعرب «الإخلاص» في: ما أروعَ الإخلاصَ!"]}'::jsonb, 'claude', 'draft', null),
  ('g12-arabic-u2-l2', '{"overview":"أسلوب المدح والذم يستخدم «نعم» للمدح و«بئس» للذم.","concepts":["نِعْمَ للمدح، وبِئْسَ للذم.","في «نِعْمَ الخلقُ الصدقُ» المخصوص بالمدح: الصدق.","«حبذا» للمدح، و«لا حبذا» للذم."],"definitions":[{"term":"المخصوص","meaning":"الاسم المقصود بالمدح أو الذم."}],"review":["حدد المخصوص بالذم: بئس الخلقُ الكذبُ.","كوّن جملة مدح بـ «نعم»."]}'::jsonb, 'claude', 'draft', null),
  ('g12-biology-u1-l1', '{"overview":"DNA جزيء يحمل المعلومات الوراثية.","concepts":["تركيبه سلم حلزوني مزدوج من نيوكليوتيدات.","القواعد النيتروجينية تتزاوج: A مع T، وC مع G.","يتضاعف DNA قبل الانقسام بطريقة شبه محافظة."],"definitions":[],"review":["ما قاعدة تزاوج القواعد في DNA؟","متى يتضاعف DNA؟"]}'::jsonb, 'claude', 'draft', null),
  ('g12-biology-u1-l2', '{"overview":"النظام البيئي مجموعة كائنات حية تتفاعل مع بيئتها غير الحية.","concepts":["المكونات الحية: منتجات ومستهلكات ومحللات، وغير الحية: الماء والضوء والتربة.","تنتقل الطاقة في السلسلة الغذائية من المنتج إلى المستهلكات.","ينتقل نحو 10% فقط من الطاقة إلى المستوى التالي."],"definitions":[{"term":"المحللات","meaning":"كائنات تحلل بقايا الكائنات الميتة كالبكتيريا والفطريات."}],"review":["اذكر مكونات النظام البيئي.","لماذا تقل الطاقة في كل مستوى غذائي؟"]}'::jsonb, 'claude', 'draft', null),
  ('g12-biology-u2-l1', '{"overview":"جهاز المناعة يحمي الجسم من مسببات الأمراض.","concepts":["خط الدفاع الأول: الجلد والأغشية المخاطية.","الخلايا اللمفاوية البائية تنتج الأجسام المضادة.","اللقاح يحفز تكوين مناعة دون الإصابة بالمرض، والمضادات الحيوية تعمل ضد البكتيريا لا الفيروسات."],"definitions":[{"term":"الأجسام المضادة","meaning":"بروتينات ترتبط بمولدات الضد لتعطيلها."}],"review":["ما خط الدفاع الأول؟","كيف يعمل اللقاح؟"]}'::jsonb, 'claude', 'draft', null),
  ('g12-biology-u2-l2', '{"overview":"الهرمونات مواد كيميائية تفرزها الغدد الصماء وتنقلها الدورة الدموية.","concepts":["الإنسولين يفرزه البنكرياس ويخفض سكر الدم.","الغدة النخامية «سيدة الغدد» تتحكم في غدد أخرى.","الأدرينالين يجهز الجسم للطوارئ."],"definitions":[],"review":["ما وظيفة الإنسولين؟","لماذا تسمى النخامية سيدة الغدد؟"]}'::jsonb, 'claude', 'draft', null),
  ('g12-chemistry-u1-l1', '{"overview":"موازنة المعادلة تطبيق لقانون حفظ الكتلة.","concepts":["عدد ذرات كل عنصر متساوٍ في الطرفين.","نوازن بتغيير المعاملات لا الصيغ.","نبدأ بالعناصر التي تظهر مرة واحدة في كل طرف."],"definitions":[],"review":["وازن: N₂ + H₂ → NH₃.","لماذا لا نغيّر الصيغة الكيميائية عند الموازنة؟"],"example":"H₂ + O₂ → H₂O ← 2H₂ + O₂ → 2H₂O."}'::jsonb, 'claude', 'draft', null),
  ('g12-chemistry-u1-l2', '{"overview":"الأحماض تطلق أيونات H⁺ في الماء، والقواعد تطلق OH⁻.","concepts":["مقياس pH من 0 إلى 14: أقل من 7 حمضي، و7 متعادل، وأكثر من 7 قاعدي.","التعادل: حمض + قاعدة → ملح + ماء.","من الأحماض: HCl، ومن القواعد: NaOH."],"definitions":[],"review":["ما قيمة pH للمحلول المتعادل؟","ماذا ينتج من تفاعل HCl مع NaOH؟"]}'::jsonb, 'claude', 'draft', null),
  ('g12-chemistry-u2-l1', '{"overview":"الهيدروكربونات مركبات من الكربون والهيدروجين فقط.","concepts":["الألكانات روابطها أحادية، وصيغتها العامة CₙH₂ₙ₊₂، وأبسطها الميثان CH₄.","الألكينات فيها رابطة ثنائية، وصيغتها CₙH₂ₙ، مثل الإيثين C₂H₄.","يُستخرج معظمها من النفط."],"definitions":[],"review":["ما الصيغة العامة للألكانات؟","ما الفرق بين الألكان والألكين؟"]}'::jsonb, 'claude', 'draft', null),
  ('g12-chemistry-u2-l2', '{"overview":"سرعة التفاعل التغير في تركيز المواد خلال وحدة الزمن.","concepts":["زيادة درجة الحرارة تزيد السرعة.","زيادة التركيز ومساحة السطح تزيد التصادمات والسرعة.","العامل الحفاز يسرّع التفاعل بخفض طاقة التنشيط دون أن يُستهلك."],"definitions":[],"review":["اذكر ثلاثة عوامل تزيد سرعة التفاعل.","ما العامل الحفاز؟"],"example":"حفظ الطعام في الثلاجة يبطئ فساده لأن البرودة تبطئ التفاعلات."}'::jsonb, 'claude', 'draft', null),
  ('g12-english-u1-l1', '{"overview":"We use reported speech to tell what someone said.","concepts":["Tenses move back: \"I am tired\" → He said (that) he was tired.","Pronouns and time words change: today → that day, tomorrow → the next day.","say vs tell: He said (that)... / He told me (that)..."],"definitions":[],"review":["Report: \"I will call you tomorrow.\"","What is the difference between \"say\" and \"tell\"?"]}'::jsonb, 'claude', 'draft', null),
  ('g12-english-u1-l2', '{"overview":"We evaluate news sources and separate facts from opinions.","concepts":["A fact can be checked; an opinion is a personal view.","Check the source, the date and other reliable sources.","Be careful with headlines that are designed to get clicks."],"definitions":[],"review":["Give an example of a fact and an opinion.","Name two ways to check a news story."]}'::jsonb, 'claude', 'draft', null),
  ('g12-english-u2-l1', '{"overview":"We write formal emails with polite greetings and closings.","concepts":["Start: \"Dear Sir or Madam,\" or \"Dear Mr ...,\"","Use formal phrases: \"I am writing to request...\"","End: \"I look forward to hearing from you. Yours faithfully / sincerely,\""],"definitions":[],"review":["Write a formal opening sentence.","Complete: I look forward to ____ from you."]}'::jsonb, 'claude', 'draft', null),
  ('g12-english-u2-l2', '{"overview":"We present arguments and use persuasive language in a debate.","concepts":["Introduce points: Firstly, Secondly, Moreover.","Counter-argument: On the other hand, However.","Conclude: To sum up, In conclusion. Support points with evidence."],"definitions":[],"review":["Which phrase introduces a counter-argument?","Why is evidence important in a debate?"]}'::jsonb, 'claude', 'draft', null),
  ('g12-islamic-u1-l1', '{"overview":"الأسرة أساس المجتمع، واهتم الإسلام ببنائها على المودة والرحمة.","concepts":["قال تعالى: ﴿وَجَعَلَ بَيْنَكُم مَّوَدَّةً وَرَحْمَةً﴾.","للزوجين حقوق متبادلة، وللأبناء حق التربية والرعاية.","على الأبناء بر الوالدين وطاعتهما في المعروف."],"definitions":[],"review":["ما مكانة الأسرة في الإسلام؟","اذكر حقاً من حقوق الأبناء."]}'::jsonb, 'claude', 'draft', null),
  ('g12-islamic-u1-l2', '{"overview":"العمل في الإسلام عبادة إذا صلحت النية.","concepts":["حثّ الإسلام على العمل وذم البطالة والتسول.","من أخلاقيات العمل: الإتقان، والأمانة، والالتزام بالوقت.","قال ﷺ: «إن الله يحب إذا عمل أحدكم عملاً أن يتقنه»."],"definitions":[],"review":["اذكر ثلاثاً من أخلاقيات العمل.","متى يكون العمل عبادة؟"]}'::jsonb, 'claude', 'draft', null),
  ('g12-islamic-u2-l1', '{"overview":"الوسطية اعتدال بلا إفراط ولا تفريط، وهي سمة هذه الأمة.","concepts":["قال تعالى: ﴿وَكَذَٰلِكَ جَعَلْنَاكُمْ أُمَّةً وَسَطًا﴾.","الغلو والتشدد وتكفير الآخرين مذموم.","الوسطية تشمل العبادة والإنفاق والسلوك."],"definitions":[{"term":"الإفراط","meaning":"تجاوز الحد."},{"term":"التفريط","meaning":"التقصير."}],"review":["عرّف الوسطية.","اذكر مظهراً من مظاهر الغلو."]}'::jsonb, 'claude', 'draft', null),
  ('g12-islamic-u2-l2', '{"overview":"كفل الإسلام حقوق الإنسان وكرّمه.","concepts":["من الحقوق: الحياة، والكرامة، والتعليم، والعدل.","قال تعالى: ﴿وَلَقَدْ كَرَّمْنَا بَنِي آدَمَ﴾.","حرية الرأي مضبوطة بعدم الإضرار بالآخرين."],"definitions":[],"review":["اذكر حقين كفلهما الإسلام.","ما ضابط حرية الرأي؟"]}'::jsonb, 'claude', 'draft', null),
  ('g12-math-u1-l1', '{"overview":"قواعد الاشتقاق تسهّل إيجاد مشتقات الدوال.","concepts":["قاعدة القوة: (xⁿ)′ = n·xⁿ⁻¹.","مشتقة المجموع مجموع المشتقات.","قاعدة الضرب: (f·g)′ = f′·g + f·g′."],"definitions":[],"review":["اشتق: 5x³ − 2x.","اشتق: (x + 2)(x − 3) بقاعدة الضرب."],"example":"(x²·(x + 1))′ = 2x(x + 1) + x² = 3x² + 2x."}'::jsonb, 'claude', 'draft', null),
  ('g12-math-u1-l2', '{"overview":"نستخدم المشتقة لإيجاد القيم العظمى والصغرى للدالة.","concepts":["النقاط الحرجة عندما f′(x) = 0.","إذا تغيرت إشارة f′ من موجب إلى سالب فالنقطة قيمة عظمى محلية، ومن سالب إلى موجب صغرى محلية.","يمكن استخدام المشتقة الثانية: f″ < 0 عظمى، وf″ > 0 صغرى."],"definitions":[],"review":["أوجد النقطة الحرجة لـ f(x) = x² + 6x.","كيف نميز العظمى من الصغرى؟"],"example":"f(x) = x² − 4x: f′(x) = 2x − 4 = 0 ← x = 2، وf″ = 2 > 0 فهي صغرى، وقيمتها f(2) = −4."}'::jsonb, 'claude', 'draft', null),
  ('g12-math-u2-l1', '{"overview":"التكامل غير المحدد عملية عكسية للاشتقاق.","concepts":["∫ xⁿ dx = xⁿ⁺¹ ÷ (n + 1) + C.","∫ a dx = ax + C.","نضيف ثابت التكامل C لأن مشتقة الثابت صفر."],"definitions":[],"review":["احسب: ∫ 4x³ dx.","لماذا نضيف C؟"],"example":"∫ (3x² + 2) dx = x³ + 2x + C."}'::jsonb, 'claude', 'draft', null),
  ('g12-math-u2-l2', '{"overview":"الاحتمال يقيس فرصة وقوع الحدث، ونستخدم مبدأ العد لحساب النواتج.","concepts":["مبدأ العد: إذا كان لعملية m طريقة ولأخرى n طريقة فلهما معاً m × n.","الحدثان المستقلان: P(A و B) = P(A) × P(B).","مجموع احتمالات جميع النواتج = 1."],"definitions":[],"review":["كم طريقة لاختيار قميص من 3 وبنطال من 4؟","احسب 4! (مضروب 4)."],"example":"احتمال صورتين في رمي قطعتي نقود = 1/2 × 1/2 = 1/4."}'::jsonb, 'claude', 'draft', null),
  ('g12-national-u1-l1', '{"overview":"النظام الأساسي للدولة هو المرجع الدستوري لسلطنة عُمان.","concepts":["يحدد شكل الدولة ونظام الحكم.","يقر مبادئ منها: العدل، والمساواة، وسيادة القانون.","يحدد الحقوق والواجبات العامة للمواطنين."],"definitions":[],"review":["ما النظام الأساسي للدولة؟","اذكر مبدأين يقرهما."]}'::jsonb, 'claude', 'draft', null),
  ('g12-national-u1-l2', '{"overview":"مجلس عُمان يتكون من مجلس الدولة ومجلس الشورى.","concepts":["مجلس الشورى يُنتخب أعضاؤه من المواطنين.","مجلس الدولة يُعيَّن أعضاؤه من ذوي الخبرة.","المشاركة المجتمعية، كالتصويت والتطوع، تعزز التنمية."],"definitions":[],"review":["مم يتكون مجلس عُمان؟","كيف يشارك المواطن في الحياة العامة؟"]}'::jsonb, 'claude', 'draft', null),
  ('g12-national-u2-l1', '{"overview":"المسؤولية المجتمعية إسهام الفرد والمؤسسة في خدمة المجتمع.","concepts":["التطوع عمل بلا مقابل لخدمة الآخرين.","من المبادرات: تنظيف الشواطئ، ومساعدة كبار السن، وحملات التوعية.","المحافظة على المرافق العامة جزء من المسؤولية الوطنية."],"definitions":[],"review":["عرّف المسؤولية المجتمعية.","اقترح مبادرة تطوعية لطلاب مدرستك."]}'::jsonb, 'claude', 'draft', null),
  ('g12-national-u2-l2', '{"overview":"تتميز عُمان بتنوع بيئي يستحق الحماية.","concepts":["من الكائنات المهددة: النمر العربي والسلاحف البحرية.","محمية المها العربي في الوسطى أُنشئت لحماية المها.","نحمي البيئة بعدم رمي النفايات، وتجنب الاحتطاب الجائر، وإعادة النفايات معنا من الرحلات."],"definitions":[],"review":["اذكر كائناً مهدداً في عُمان.","كيف نحمي البيئة عند التنزه في الأودية؟"]}'::jsonb, 'claude', 'draft', null),
  ('g12-physics-u1-l1', '{"overview":"قانون أوم يربط الجهد بالتيار والمقاومة.","concepts":["V = I × R.","وحدة الجهد الفولت، والتيار الأمبير، والمقاومة الأوم.","عند ثبات المقاومة يتناسب التيار طردياً مع الجهد."],"definitions":[],"review":["احسب المقاومة إذا كان V = 9 فولت وI = 3 أمبير.","ما وحدة المقاومة؟"],"example":"جهد 12 فولت ومقاومة 4 أوم: I = 3 أمبير."}'::jsonb, 'claude', 'draft', null),
  ('g12-physics-u1-l2', '{"overview":"القدرة الكهربائية معدل استهلاك الطاقة الكهربائية.","concepts":["P = V × I، ووحدتها الواط.","الطاقة المستهلكة = القدرة × الزمن.","نحسب الاستهلاك المنزلي بالكيلوواط ساعة."],"definitions":[],"review":["احسب قدرة جهاز يعمل على 220 فولت ويسحب 5 أمبير.","ما وحدة استهلاك الكهرباء في الفاتورة؟"],"example":"جهاز 2000 واط يعمل 3 ساعات: 2 كيلوواط × 3 = 6 كيلوواط ساعة."}'::jsonb, 'claude', 'draft', null),
  ('g12-physics-u2-l1', '{"overview":"مرور التيار في سلك يولّد حوله مجالاً مغناطيسياً.","concepts":["اكتشف أورستد هذه الظاهرة.","يزداد المجال بزيادة شدة التيار، ونحدد اتجاهه بقاعدة اليد اليمنى.","الملف اللولبي الذي يمر به تيار يسلك سلوك المغناطيس، والقلب الحديدي يقويه."],"definitions":[{"term":"التسلا","meaning":"وحدة قياس شدة المجال المغناطيسي."}],"review":["من اكتشف أن التيار يولّد مجالاً مغناطيسياً؟","كيف نقوّي المجال في الملف؟"]}'::jsonb, 'claude', 'draft', null),
  ('g12-physics-u2-l2', '{"overview":"الحث الكهرومغناطيسي توليد تيار كهربائي بتغيير المجال المغناطيسي.","concepts":["اكتشفه فاراداي.","تحريك مغناطيس داخل ملف يولّد تياراً مستحثاً.","من تطبيقاته: المولد الكهربائي، والمحوّل الذي يعمل بالتيار المتردد."],"definitions":[],"review":["ما مبدأ عمل المولد الكهربائي؟","لماذا لا يعمل المحول بالتيار المستمر؟"],"example":"المحول الرافع: لفات الملف الثانوي أكثر من الابتدائي فيرتفع الجهد."}'::jsonb, 'claude', 'draft', null),
  ('g2-arabic-u1-l1', '{"overview":"الكلمة المفرد تدل على واحد، والجمع يدل على أكثر من اثنين.","concepts":["كتاب مفرد، وكتب جمع.","قلم مفرد، وأقلام جمع.","ولد مفرد، وأولاد جمع."],"definitions":[{"term":"المفرد","meaning":"ما يدل على شيء واحد."},{"term":"الجمع","meaning":"ما يدل على ثلاثة أو أكثر."}],"review":["ما جمع كلمة «بيت»؟","ما مفرد كلمة «أقلام»؟"]}'::jsonb, 'claude', 'draft', null),
  ('g2-arabic-u1-l2', '{"overview":"الجملة المفيدة كلمات مرتبة تعطي معنى كاملاً.","concepts":["نرتب الكلمات حتى يفهم القارئ المعنى.","نضع النقطة (.) في نهاية الجملة الخبرية.","نضع علامة الاستفهام (؟) في نهاية السؤال."],"definitions":[],"review":["ماذا نضع في نهاية الجملة الخبرية؟","كوّن جملة من: المدرسة، إلى، ذهبت."],"example":"الولد يقرأ الكتاب. — أين الكتاب؟"}'::jsonb, 'claude', 'draft', null),
  ('g2-arabic-u2-l1', '{"overview":"اللام الشمسية تُكتب ولا تُنطق، ويُشدَّد الحرف الذي بعدها.","concepts":["في «الشمس» نكتب اللام ولا ننطقها.","الحرف بعد اللام الشمسية عليه شدة: الشَّمس، النَّهر.","من أمثلتها: السماء، الدرس، النور."],"definitions":[],"review":["اذكر كلمة فيها لام شمسية.","لماذا سُميت شمسية؟"]}'::jsonb, 'claude', 'draft', null),
  ('g2-arabic-u2-l2', '{"overview":"اللام القمرية تُكتب وتُنطق، ولا يأتي بعدها حرف مشدد.","concepts":["في «القمر» نكتب اللام وننطقها.","من أمثلتها: الكتاب، البحر، الولد.","نصنف الكلمات حسب نطق اللام: إن نُطقت فهي قمرية."],"definitions":[],"review":["اذكر كلمة فيها لام قمرية.","صنّف: الدرس، الكتاب."]}'::jsonb, 'claude', 'draft', null),
  ('g2-english-u1-l1', '{"overview":"We name the people in our family.","concepts":["mother, father, brother, sister.","grandmother and grandfather.","We say: \"This is my brother.\""],"definitions":[],"review":["Who is your mother''s husband?","Say a sentence with \"This is my ...\"."],"example":"This is my father. This is my sister."}'::jsonb, 'claude', 'draft', null),
  ('g2-english-u1-l2', '{"overview":"We name animals and say what they can do.","concepts":["A bird can fly. A fish can swim.","A camel has a hump and lives in the desert.","A cat can jump. A horse can run."],"definitions":[],"review":["Which animal can fly?","What can a fish do?"]}'::jsonb, 'claude', 'draft', null),
  ('g2-english-u2-l1', '{"overview":"We talk about the weather.","concepts":["sunny, rainy, windy, cloudy, hot, cold.","Ask: \"What''s the weather like?\"","Answer: \"It is sunny.\""],"definitions":[],"review":["What is the weather like when the sun shines?","Is it hot or cold in summer in Oman?"]}'::jsonb, 'claude', 'draft', null),
  ('g2-english-u2-l2', '{"overview":"We name clothes and say what people wear.","concepts":["shoes, socks, shirt, dress, jacket, cap.","We wear shoes on our feet and a cap on our head.","\"He is wearing a blue shirt.\""],"definitions":[],"review":["What do we wear on our feet?","What keeps us warm?"]}'::jsonb, 'claude', 'draft', null),
  ('g2-islamic-u1-l1', '{"overview":"الوضوء طهارة نستعد بها للصلاة، وله أعضاء نغسلها بترتيب.","concepts":["نبدأ بالنية ونقول «بسم الله» ثم نغسل الكفين.","نتمضمض ونستنشق ونغسل الوجه، ثم اليدين إلى المرفقين.","نمسح الرأس والأذنين، ثم نغسل الرجلين إلى الكعبين، وهما آخر الأعضاء."],"definitions":[{"term":"الوضوء","meaning":"غسل أعضاء معينة بالماء بنية الطهارة للصلاة."}],"review":["بماذا نبدأ الوضوء؟","ما آخر عضو نغسله في الوضوء؟"]}'::jsonb, 'claude', 'draft', null),
  ('g2-islamic-u1-l2', '{"overview":"فرض الله علينا خمس صلوات في اليوم والليلة، لكل صلاة وقتها.","concepts":["الفجر قبل طلوع الشمس، والظهر بعد منتصف النهار.","العصر بعد الظهر، والمغرب بعد غروب الشمس مباشرة.","العشاء بعد ذهاب ضوء النهار ودخول الليل."],"definitions":[],"review":["كم عدد الصلوات المفروضة؟","ما الصلاة التي نصليها بعد غروب الشمس؟"]}'::jsonb, 'claude', 'draft', null),
  ('g2-islamic-u2-l1', '{"overview":"نوح عليه السلام نبي كريم دعا قومه إلى عبادة الله وحده، وصبر عليهم سنين طويلة.","concepts":["دعا نوح قومه إلى عبادة الله وترك الأصنام.","لم يؤمن معه إلا قليل، فأمره الله أن يصنع السفينة.","نجّى الله نوحاً والمؤمنين في السفينة."],"definitions":[],"review":["ماذا صنع نوح عليه السلام بأمر الله؟","ما القيمة التي نتعلمها من قصته؟"]}'::jsonb, 'claude', 'draft', null),
  ('g2-islamic-u2-l2', '{"overview":"المسجد بيت الله، وله آداب نحافظ عليها.","concepts":["ندخل المسجد بالقدم اليمنى ونقول دعاء الدخول.","نجلس بهدوء ولا نرفع أصواتنا ولا نلعب.","نحافظ على نظافة المسجد ونخرج بالقدم اليسرى."],"definitions":[],"review":["بأي قدم ندخل المسجد؟","اذكر أدبين من آداب المسجد."]}'::jsonb, 'claude', 'draft', null),
  ('g2-math-u1-l1', '{"overview":"كل عدد من رقمين يتكون من عشرات وآحاد.","concepts":["في العدد 47: الرقم 4 في منزلة العشرات، والرقم 7 في منزلة الآحاد.","العدد المكون من 6 عشرات و3 آحاد هو 63.","نقارن العددين بالعشرات أولاً ثم بالآحاد."],"definitions":[{"term":"العشرة","meaning":"عشرة آحاد مجموعة معاً."}],"review":["كم عشرة في العدد 58؟","اكتب العدد: 3 عشرات و5 آحاد."],"example":"90 أكبر من 89 لأن عشراته 9 وعشرات 89 هي 8."}'::jsonb, 'claude', 'draft', null),
  ('g2-math-u1-l2', '{"overview":"نجمع ونطرح الأعداد حتى 100 بجمع العشرات مع العشرات والآحاد مع الآحاد.","concepts":["20 + 30 = 50: نجمع العشرات.","45 + 4 = 49: نجمع الآحاد.","نقرأ المسألة اللفظية جيداً لنعرف هل نجمع أم نطرح."],"definitions":[],"review":["70 − 20 = ؟","معك 35 بيسة وصرفت 10، كم بقي؟"],"example":"في الصف 24 طالباً وانضم 5 طلاب: 24 + 5 = 29 طالباً."}'::jsonb, 'claude', 'draft', null),
  ('g2-math-u2-l1', '{"overview":"نقرأ الوقت في الساعة بالساعات الكاملة.","concepts":["العقرب القصير يشير إلى الساعات.","العقرب الطويل يشير إلى الدقائق.","إذا كان العقرب الطويل على 12 فالوقت ساعة كاملة."],"definitions":[],"review":["إلى ماذا يشير العقرب القصير؟","كم ساعة في اليوم؟"],"example":"العقرب القصير على 3 والطويل على 12: الساعة الثالثة."}'::jsonb, 'claude', 'draft', null),
  ('g2-math-u2-l2', '{"overview":"عملة سلطنة عُمان الريال العماني، وجزؤه البيسة.","concepts":["الريال العماني = 1000 بيسة.","500 بيسة نصف ريال، و500 + 500 = ريال واحد.","نجمع المبالغ الصغيرة لنعرف كم ندفع."],"definitions":[],"review":["كم بيسة في الريال؟","كم يساوي نصف ريال بالبيسة؟"],"example":"اشتريت عصيراً بـ 200 بيسة وكعكة بـ 300 بيسة: المجموع 500 بيسة."}'::jsonb, 'claude', 'draft', null),
  ('g2-science-u1-l1', '{"overview":"الكائنات الحية تنمو وتتنفس وتتغذى وتتكاثر، أما غير الحية فلا تفعل ذلك.","concepts":["الإنسان والحيوان والنبات كائنات حية.","الكائنات الحية تحتاج إلى الغذاء والماء والهواء.","الحجر والسيارة أشياء غير حية حتى لو تحركت السيارة."],"definitions":[],"review":["اذكر صفتين من صفات الكائن الحي.","هل السيارة كائن حي؟ ولماذا؟"]}'::jsonb, 'claude', 'draft', null),
  ('g2-science-u1-l2', '{"overview":"للنبات أجزاء، ولكل جزء وظيفة.","concepts":["الجذر يثبت النبات ويمتص الماء من التربة.","الساق تحمل الأوراق وتنقل الماء.","الأوراق تصنع غذاء النبات بمساعدة ضوء الشمس، والزهرة تكوّن البذور."],"definitions":[],"review":["ما وظيفة الجذر؟","أي جزء يصنع غذاء النبات؟"]}'::jsonb, 'claude', 'draft', null),
  ('g2-science-u2-l1', '{"overview":"الماء ضروري لحياة الإنسان والحيوان والنبات، وعلينا أن نحافظ عليه.","concepts":["نستخدم الماء في الشرب والطبخ والنظافة والزراعة.","نغلق الصنبور أثناء تنظيف الأسنان.","الماء في عُمان ثمين لقلة الأمطار، فلا نسرف فيه."],"definitions":[{"term":"الترشيد","meaning":"استخدام الماء بقدر الحاجة دون إسراف."}],"review":["اذكر طريقتين لترشيد الماء.","لماذا نحتاج إلى الماء؟"]}'::jsonb, 'claude', 'draft', null),
  ('g2-science-u2-l2', '{"overview":"الطقس حالة الجو، ويتغير مع فصول السنة الأربعة.","concepts":["فصول السنة: الصيف، والخريف، والشتاء، والربيع.","الصيف في عُمان حار، والشتاء معتدل وأبرد.","نختار ملابسنا حسب الطقس."],"definitions":[],"review":["كم عدد فصول السنة؟","ماذا نلبس في الشتاء؟"]}'::jsonb, 'claude', 'draft', null),
  ('g3-arabic-u1-l1', '{"overview":"الكلمة في اللغة العربية ثلاثة أنواع: اسم وفعل وحرف.","concepts":["الاسم يدل على إنسان أو حيوان أو شيء أو مكان: سعيد، قطة، باب.","الفعل يدل على حدث مرتبط بزمن: كتب، يقرأ، اذهب.","الحرف لا يتم معناه إلا مع غيره: في، من، على."],"definitions":[],"review":["ما نوع كلمة «يلعب»؟","استخرج الحرف من: جلست على الكرسي."],"example":"كتبَ (فعل) سعيدٌ (اسم) في (حرف) الدفترِ (اسم)."}'::jsonb, 'claude', 'draft', null),
  ('g3-arabic-u1-l2', '{"overview":"الضمائر كلمات نستخدمها بدلاً من الأسماء حتى لا نكررها.","concepts":["للمتكلم: أنا، نحن.","للمخاطب: أنتَ، أنتِ، أنتم.","للغائب: هو، هي، هم."],"definitions":[{"term":"الضمير","meaning":"اسم يقوم مقام اسم آخر."}],"review":["ما الضمير المناسب: ____ تلميذة مجتهدة؟","بأي ضمير نشير إلى الولد الغائب؟"],"example":"سارة مجتهدة ← هي مجتهدة."}'::jsonb, 'claude', 'draft', null),
  ('g3-arabic-u2-l1', '{"overview":"أسماء الإشارة نشير بها إلى القريب.","concepts":["«هذا» للمفرد المذكر: هذا كتاب.","«هذه» للمفردة المؤنثة: هذه شجرة.","«هؤلاء» للجمع من الناس: هؤلاء طلاب."],"definitions":[],"review":["أشر إلى البنت القريبة.","أكمل: ____ طلاب مجتهدون."]}'::jsonb, 'claude', 'draft', null),
  ('g3-arabic-u2-l2', '{"overview":"أدوات الاستفهام نسأل بها عن أشياء مختلفة.","concepts":["«أين» للسؤال عن المكان، و«متى» عن الزمان.","«مَن» للسؤال عن الشخص، و«ما» عن الشيء.","«كيف» عن الحال، و«كم» عن العدد."],"definitions":[],"review":["بماذا نسأل عن المكان؟","ضع أداة مناسبة: ____ اسمك؟"],"example":"متى تبدأ الإجازة؟ — أين المكتبة؟ — كم عمرك؟"}'::jsonb, 'claude', 'draft', null),
  ('g3-english-u1-l1', '{"overview":"We name things in our classroom and use \"There is / There are\".","concepts":["Classroom things: pen, pencil, book, ruler, desk, board.","Use \"There is\" for one thing: There is a pen.","Use \"There are\" for more than one: There are two books."],"definitions":[],"review":["What do we write with?","Complete: There ____ two books on the desk."],"example":"There is a ruler on the desk. There are three pencils in the bag."}'::jsonb, 'claude', 'draft', null),
  ('g3-english-u1-l2', '{"overview":"We name the rooms in a house and say what we do there.","concepts":["We cook in the kitchen and sleep in the bedroom.","We wash in the bathroom.","We sit with our family in the living room."],"definitions":[],"review":["Where do we cook?","Where do we sleep?"]}'::jsonb, 'claude', 'draft', null),
  ('g3-english-u2-l1', '{"overview":"We talk about what we like to do in our free time.","concepts":["Hobbies: reading, drawing, swimming, playing football.","Use \"I like + verb-ing\": I like reading books.","Ask: \"What do you like doing?\""],"definitions":[],"review":["Say one hobby you like.","Complete: I like ____ (swim)."]}'::jsonb, 'claude', 'draft', null),
  ('g3-english-u2-l2', '{"overview":"We use \"can\" and \"can''t\" to talk about abilities.","concepts":["\"can\" means you are able to do something: A bird can fly.","\"can''t\" means you are not able: A fish can''t walk.","After can / can''t we use the verb without -s."],"definitions":[],"review":["What can a fish do?","Say one thing you can do."],"example":"I can ride a bike. I can''t fly."}'::jsonb, 'claude', 'draft', null),
  ('g3-islamic-u1-l1', '{"overview":"الصدق أن نقول الحقيقة ونطابق كلامنا مع أفعالنا، وهو من صفات المسلم.","concepts":["الصادق يقول الحق ولو كان على نفسه.","الصدق يجعل الناس يثقون بنا ويحبوننا.","إذا أخطأنا نعترف بالخطأ ونعتذر ولا نكذب."],"definitions":[{"term":"الصدق","meaning":"قول الحقيقة كما هي."}],"review":["ما معنى الصدق؟","اذكر موقفاً كنت فيه صادقاً."],"example":"كسر أحمد زجاج النافذة دون قصد، فأخبر المعلم بالحقيقة واعتذر."}'::jsonb, 'claude', 'draft', null),
  ('g3-islamic-u1-l2', '{"overview":"للوالدين مكانة عظيمة، وبرّهما من أحب الأعمال إلى الله.","concepts":["البر هو الإحسان إلى الوالدين وطاعتهما في المعروف.","من البر: مساعدة الأم في البيت، والكلام بأدب، وعدم رفع الصوت عليهما.","ندعو لوالدينا: ربّ ارحمهما كما ربياني صغيراً."],"definitions":[{"term":"البر","meaning":"الإحسان وفعل الخير."}],"review":["اذكر صورتين من بر الوالدين.","بماذا ندعو لوالدينا؟"]}'::jsonb, 'claude', 'draft', null),
  ('g3-islamic-u2-l1', '{"overview":"أوصى الإسلام بالجار، وجعل الإحسان إليه من الإيمان.","concepts":["من حق الجار ألا نؤذيه بالكلام أو الإزعاج.","نزوره إذا مرض، ونهنئه في فرحه، ونهديه من طعامنا.","نحافظ على نظافة المكان أمام بيته."],"definitions":[{"term":"الجار","meaning":"من يسكن قريباً من بيتنا."}],"review":["اذكر حقين من حقوق الجار.","كيف نحسن إلى جارنا؟"]}'::jsonb, 'claude', 'draft', null),
  ('g3-islamic-u2-l2', '{"overview":"الإسلام دين النظافة، والله يحب المتطهرين.","concepts":["نظافة الجسم: الوضوء والاغتسال وتقليم الأظافر.","نظافة الثياب والمكان من أدب المسلم.","نرمي النفايات في مكانها ونحافظ على نظافة المدرسة والشارع."],"definitions":[],"review":["ماذا يحب الله؟","اذكر عادتين تدلان على النظافة."]}'::jsonb, 'claude', 'draft', null),
  ('g3-math-u1-l1', '{"overview":"الضرب طريقة سريعة لجمع عدد مع نفسه عدة مرات.","concepts":["3 + 3 + 3 + 3 = 4 × 3 = 12.","جدول الضرب في 2: 2، 4، 6، 8، 10…","جدول الضرب في 5 ينتهي دائماً بـ 0 أو 5."],"definitions":[{"term":"الضرب","meaning":"جمع متكرر لعدد واحد."}],"review":["اكتب 2 + 2 + 2 في صورة ضرب.","5 × 6 = ؟"],"example":"5 أكياس في كل كيس 4 تمرات: 5 × 4 = 20 تمرة."}'::jsonb, 'claude', 'draft', null),
  ('g3-math-u1-l2', '{"overview":"نقرأ الأعداد حتى 1000 ونعرف قيمة كل رقم حسب منزلته.","concepts":["في العدد 735: 7 مئات، و3 عشرات، و5 آحاد.","«أربعمئة وستة» يُكتب 406، والصفر يحفظ منزلة العشرات.","599 أصغر من 600 لأن مئاته أقل."],"definitions":[{"term":"المنزلة","meaning":"مكان الرقم في العدد: آحاد، عشرات، مئات."}],"review":["كم مئة في العدد 862؟","اكتب بالأرقام: ثلاثمئة وعشرون."]}'::jsonb, 'claude', 'draft', null),
  ('g3-math-u2-l1', '{"overview":"الكسر جزء من شيء مقسوم إلى أجزاء متساوية.","concepts":["النصف (1/2): جزء من جزأين متساويين.","الربع (1/4): جزء من أربعة أجزاء متساوية.","نصف العدد 10 هو 5، وربع العدد 8 هو 2."],"definitions":[],"review":["ما نصف العدد 12؟","كم ربعاً في الشيء الكامل؟"],"example":"قسمنا كعكة إلى 4 قطع متساوية، فكل قطعة ربع الكعكة."}'::jsonb, 'claude', 'draft', null),
  ('g3-math-u2-l2', '{"overview":"المحيط هو طول الحدود المحيطة بالشكل.","concepts":["محيط أي شكل = مجموع أطوال أضلاعه.","محيط المربع = طول الضلع × 4.","نكتب الوحدة مع الناتج: سم أو م."],"definitions":[{"term":"المحيط","meaning":"مجموع أطوال أضلاع الشكل."}],"review":["ما محيط مربع طول ضلعه 5 سم؟","ما المحيط؟"],"example":"مثلث أضلاعه 2 و3 و4 سم: المحيط = 2 + 3 + 4 = 9 سم."}'::jsonb, 'claude', 'draft', null),
  ('g3-science-u1-l1', '{"overview":"المادة كل شيء له كتلة ويشغل حيزاً، ولها ثلاث حالات.","concepts":["الصلب له شكل ثابت مثل الحجر والقلم.","السائل يأخذ شكل الإناء مثل الماء والعصير.","الغاز ينتشر ويملأ المكان مثل الهواء."],"definitions":[],"review":["ما حالة الماء في الكوب؟","اذكر مثالاً على مادة غازية."]}'::jsonb, 'claude', 'draft', null),
  ('g3-science-u1-l2', '{"overview":"المغناطيس يجذب بعض المواد مثل الحديد.","concepts":["ينجذب الحديد إلى المغناطيس، ولا ينجذب الخشب والبلاستيك.","للمغناطيس قطبان: شمالي وجنوبي.","القطبان المتشابهان يتنافران، والمختلفان يتجاذبان."],"definitions":[],"review":["اذكر مادة ينجذب إليها المغناطيس.","ماذا يحدث إذا قربنا قطبين شماليين؟"]}'::jsonb, 'claude', 'draft', null),
  ('g3-science-u2-l1', '{"overview":"الضوء يساعدنا على رؤية الأشياء، وله مصادر طبيعية وصناعية.","concepts":["الشمس أهم مصدر طبيعي للضوء.","المصباح الكهربائي مصدر صناعي للضوء.","الظل يتكون عندما يحجب جسم معتم الضوء."],"definitions":[{"term":"الجسم المضيء","meaning":"جسم يصدر الضوء بنفسه."}],"review":["اذكر مصدراً صناعياً للضوء.","كيف يتكون الظل؟"]}'::jsonb, 'claude', 'draft', null),
  ('g3-science-u2-l2', '{"overview":"الصوت ينتج عن اهتزاز الأجسام وننقله إلى الأذن.","concepts":["عندما نضرب الطبل يهتز فيصدر صوتاً.","نسمع الأصوات بالأذن.","الأصوات العالية جداً قد تؤذي الأذن، فنحميها."],"definitions":[{"term":"الاهتزاز","meaning":"حركة سريعة ذهاباً وإياباً."}],"review":["كيف ينتج الصوت؟","لماذا نبتعد عن الأصوات العالية جداً؟"]}'::jsonb, 'claude', 'draft', null),
  ('g4-arabic-u1-l1', '{"overview":"الجملة العربية نوعان: اسمية تبدأ باسم، وفعلية تبدأ بفعل.","concepts":["الجملة الاسمية: مبتدأ وخبر، مثل: الطالبُ مجتهدٌ.","الجملة الفعلية: فعل وفاعل، مثل: يلعبُ الأطفالُ.","يمكن تحويل الجملة: الأطفالُ يلعبون (اسمية)."],"definitions":[{"term":"المبتدأ","meaning":"الاسم الذي نبدأ به الجملة الاسمية."},{"term":"الخبر","meaning":"ما نخبر به عن المبتدأ."}],"review":["ما نوع جملة «الشمسُ مشرقةٌ»؟","حوّل إلى جملة فعلية: الطالبُ يكتبُ."]}'::jsonb, 'claude', 'draft', null),
  ('g4-arabic-u1-l2', '{"overview":"الأسماء مذكرة ومؤنثة، ونحوّل المذكر إلى مؤنث غالباً بإضافة التاء المربوطة.","concepts":["معلّم ← معلّمة، طبيب ← طبيبة.","بعض الكلمات مؤنثة دون تاء مثل: شمس، أم.","نطابق بين الاسم والصفة: الولدُ نشيطٌ، البنتُ نشيطةٌ."],"definitions":[],"review":["ما مؤنث «مهندس»؟","اذكر كلمة مؤنثة بلا تاء."]}'::jsonb, 'claude', 'draft', null),
  ('g4-arabic-u2-l1', '{"overview":"المثنى اسم يدل على اثنين بزيادة ألف ونون أو ياء ونون.","concepts":["قلم ← قلمان أو قلمين.","شجرة ← شجرتان (تتحول التاء المربوطة إلى تاء مفتوحة).","نستخدم المثنى عندما يكون العدد اثنين فقط."],"definitions":[{"term":"المثنى","meaning":"ما يدل على اثنين."}],"review":["ما مثنى «باب»؟","ما مثنى «وردة»؟"],"example":"في الحديقة شجرتان، وعلى المكتب كتابان."}'::jsonb, 'claude', 'draft', null),
  ('g4-arabic-u2-l2', '{"overview":"حروف الجر تربط الكلمات وتغير آخر الاسم بعدها إلى الكسر.","concepts":["من حروف الجر: من، إلى، عن، على، في، الباء، اللام.","الاسم بعد حرف الجر مجرور: ذهبتُ إلى المدرسةِ.","لكل حرف معنى: «في» للمكان، و«إلى» لانتهاء الغاية."],"definitions":[],"review":["استخرج حرف الجر: جلست على الكرسي.","أكمل: خرجتُ ____ البيت."]}'::jsonb, 'claude', 'draft', null),
  ('g4-english-u1-l1', '{"overview":"We read the time and ask \"What time is it?\"","concepts":["There are 24 hours in a day and 60 minutes in an hour.","Ask: \"What time is it?\" — Answer: \"It''s three o''clock.\"","\"half past\" means 30 minutes after the hour."],"definitions":[],"review":["How many minutes are in an hour?","How do you ask about the time?"],"example":"It''s half past seven = 7:30."}'::jsonb, 'claude', 'draft', null),
  ('g4-english-u1-l2', '{"overview":"We talk about our day using the present simple.","concepts":["I get up at six. I go to school at seven.","With he / she / it, add -s: She goes to school by bus.","Words like \"every day\" and \"always\" show routines."],"definitions":[],"review":["Complete: I ____ up at six o''clock.","Complete: She ____ (go) to school by bus."]}'::jsonb, 'claude', 'draft', null),
  ('g4-english-u2-l1', '{"overview":"We ask for prices and buy things in a shop.","concepts":["Ask: \"How much is this bag?\"","Answer: \"It''s two rials.\"","Use \"a\" before a consonant sound and \"an\" before a vowel sound: an apple."],"definitions":[],"review":["How do you ask about a price?","Complete: I want ____ apple, please."]}'::jsonb, 'claude', 'draft', null),
  ('g4-english-u2-l2', '{"overview":"We use \"some\" and \"any\" to talk about food.","concepts":["Use \"some\" in positive sentences: There is some milk.","Use \"any\" in questions and negatives: Are there any eggs? There aren''t any oranges.","Both are used with uncountable nouns and plural nouns."],"definitions":[],"review":["Complete: There is ____ milk in the fridge.","Complete: Are there ____ eggs?"]}'::jsonb, 'claude', 'draft', null),
  ('g4-islamic-u1-l1', '{"overview":"وُلد النبي محمد ﷺ في مكة المكرمة، وعُرف بأخلاقه العظيمة قبل البعثة.","concepts":["وُلد النبي ﷺ في مكة في عام الفيل.","أبوه عبد الله وأمه آمنة بنت وهب.","لُقِّب قبل البعثة بالصادق الأمين لصدقه وأمانته."],"definitions":[{"term":"البعثة","meaning":"نزول الوحي على النبي ﷺ وبدء رسالته."}],"review":["أين وُلد النبي ﷺ؟","بماذا لُقِّب قبل البعثة؟"]}'::jsonb, 'claude', 'draft', null),
  ('g4-islamic-u1-l2', '{"overview":"الصوم عبادة فرضها الله في شهر رمضان، وفيه تربية للنفس على الصبر.","concepts":["الصوم: الامتناع عن الطعام والشراب وسائر المفطرات من طلوع الفجر إلى غروب الشمس بنية.","صوم رمضان ركن من أركان الإسلام.","من آداب الصائم: السحور، وتعجيل الفطور، وحفظ اللسان."],"definitions":[{"term":"السحور","meaning":"طعام نأكله قبل الفجر استعداداً للصوم."}],"review":["من متى إلى متى يصوم المسلم؟","اذكر أدبين من آداب الصائم."]}'::jsonb, 'claude', 'draft', null),
  ('g4-islamic-u2-l1', '{"overview":"التعاون أن نعمل معاً على الخير، وقد أمرنا الله به.","concepts":["قال تعالى: ﴿وَتَعَاوَنُوا عَلَى الْبِرِّ وَالتَّقْوَىٰ﴾.","نتعاون في البيت بمساعدة الأسرة، وفي المدرسة بتنظيف الفصل مع الزملاء.","التعاون يجعل العمل أسهل وأسرع."],"definitions":[{"term":"التعاون","meaning":"أن يساعد الناس بعضهم بعضاً على عمل الخير."}],"review":["ما معنى التعاون؟","اذكر مثالاً للتعاون في المدرسة."]}'::jsonb, 'claude', 'draft', null),
  ('g4-islamic-u2-l2', '{"overview":"للطريق آداب تحفظ سلامتنا وسلامة الآخرين.","concepts":["نمشي على الرصيف ونعبر الشارع من ممر المشاة.","ننتظر عندما تكون إشارة المشاة حمراء.","لا نرمي النفايات في الطريق ونزيل الأذى عنه."],"definitions":[],"review":["من أين نعبر الشارع؟","ماذا نفعل عندما تكون إشارة المشاة حمراء؟"]}'::jsonb, 'claude', 'draft', null),
  ('g4-math-u1-l1', '{"overview":"حفظ جداول الضرب حتى 10 يساعدنا على الحساب السريع.","concepts":["7 × 8 = 56، و6 × 9 = 54.","خاصية الإبدال: 4 × 6 = 6 × 4 = 24.","أي عدد × 1 = العدد نفسه، وأي عدد × 0 = 0."],"definitions":[{"term":"خاصية الإبدال","meaning":"تغيير ترتيب العددين في الضرب لا يغير الناتج."}],"review":["7 × 9 = ؟","إذا كان 8 × 3 = 24، فكم 3 × 8؟"]}'::jsonb, 'claude', 'draft', null),
  ('g4-math-u1-l2', '{"overview":"القسمة توزيع بالتساوي، وهي عكس الضرب.","concepts":["24 ÷ 6 = 4 لأن 6 × 4 = 24.","نستخدم القسمة عندما نوزع أشياء على مجموعات متساوية.","نتحقق من الناتج بالضرب."],"definitions":[],"review":["36 ÷ 9 = ؟","وزّع 20 حلوى على 4 أطفال بالتساوي."],"example":"30 قلماً على 5 طلاب بالتساوي: 30 ÷ 5 = 6 أقلام لكل طالب."}'::jsonb, 'claude', 'draft', null),
  ('g4-math-u2-l1', '{"overview":"الكسور المتكافئة كسور مختلفة في الشكل لكنها تمثل الجزء نفسه.","concepts":["1/2 = 2/4 = 4/8.","نكوّن كسراً مكافئاً بضرب البسط والمقام في العدد نفسه.","2/6 يكافئ 1/3 بقسمة البسط والمقام على 2."],"definitions":[{"term":"البسط","meaning":"العدد فوق خط الكسر."},{"term":"المقام","meaning":"العدد تحت خط الكسر."}],"review":["اكتب كسراً يكافئ 1/2.","أكمل: 1/3 = ؟/6."],"example":"1/4 = ؟/8: ضربنا المقام في 2، فنضرب البسط في 2: 2/8."}'::jsonb, 'claude', 'draft', null),
  ('g4-math-u2-l2', '{"overview":"المساحة مقدار السطح الذي يغطيه الشكل، ونقيسها بالمربعات.","concepts":["نعدّ المربعات التي تغطي الشكل لنعرف مساحته.","مساحة المستطيل = الطول × العرض.","نكتب وحدة المساحة: سم² أو وحدة مربعة."],"definitions":[{"term":"المساحة","meaning":"عدد الوحدات المربعة التي تغطي الشكل."}],"review":["ما مساحة مستطيل طوله 5 وعرضه 2؟","ما الفرق بين المساحة والمحيط؟"],"example":"مستطيل فيه 3 صفوف في كل صف 4 مربعات: 3 × 4 = 12 وحدة مربعة."}'::jsonb, 'claude', 'draft', null),
  ('g4-science-u1-l1', '{"overview":"الأرض تدور حول نفسها وحول الشمس، والقمر يدور حول الأرض.","concepts":["دوران الأرض حول نفسها يسبب تعاقب الليل والنهار.","دوران الأرض حول الشمس يستغرق سنة تقريباً.","الشمس نجم يضيء بنفسه، والقمر يعكس ضوء الشمس."],"definitions":[],"review":["ما سبب تعاقب الليل والنهار؟","هل يضيء القمر بنفسه؟"]}'::jsonb, 'claude', 'draft', null),
  ('g4-science-u1-l2', '{"overview":"التربة تتكون من فتات الصخور وبقايا الكائنات الحية والماء والهواء.","concepts":["الصخور تتفتت بفعل الماء والرياح والحرارة فتكوّن التربة.","التربة الطينية تحتفظ بالماء أكثر من الرملية.","التربة مهمة لنمو النبات لأنها تثبته وتمده بالماء والأملاح."],"definitions":[],"review":["مم تتكون التربة؟","أي تربة تحتفظ بالماء أكثر؟"]}'::jsonb, 'claude', 'draft', null),
  ('g4-science-u2-l1', '{"overview":"الحرارة صورة من صور الطاقة، ونقيس درجتها بميزان الحرارة.","concepts":["نقيس درجة الحرارة بالترمومتر (ميزان الحرارة) بوحدة الدرجة السيليزية.","الحرارة تحوّل الماء إلى بخار عند الغليان.","الحرارة تصهر بعض المواد مثل الثلج والشمع."],"definitions":[{"term":"الانصهار","meaning":"تحول المادة من صلبة إلى سائلة بالحرارة."}],"review":["بماذا نقيس درجة الحرارة؟","اذكر مادة تنصهر بالحرارة."]}'::jsonb, 'claude', 'draft', null),
  ('g4-science-u2-l2', '{"overview":"الغذاء الصحي متنوع ومتوازن ويمدنا بما نحتاجه للنمو والنشاط.","concepts":["البروتينات للبناء: اللحم والسمك والبيض والبقول.","الفواكه والخضراوات غنية بالفيتامينات والألياف.","نقلل من السكريات والمشروبات الغازية ونشرب الماء."],"definitions":[{"term":"الوجبة المتوازنة","meaning":"وجبة فيها أنواع مختلفة من الغذاء بكميات مناسبة."}],"review":["اذكر غذاء غنياً بالبروتين.","لماذا نقلل المشروبات الغازية؟"]}'::jsonb, 'claude', 'draft', null),
  ('g5-arabic-u1-l1', '{"overview":"الفعل ثلاثة أزمنة: ماضٍ ومضارع وأمر.","concepts":["الماضي حدث انتهى: كتبَ، سافرَ.","المضارع حدث يحدث الآن أو سيحدث: يكتبُ، يسافرُ.","الأمر طلب حدوث الفعل: اكتبْ، اجلسْ."],"definitions":[],"review":["ما زمن الفعل «يلعب»؟","ما فعل الأمر من «يجلس»؟"],"example":"كتبَ ← يكتبُ ← اكتبْ / جلسَ ← يجلسُ ← اجلسْ"}'::jsonb, 'claude', 'draft', null),
  ('g5-arabic-u1-l2', '{"overview":"الفاعل اسم مرفوع يأتي بعد الفعل ويدل على من قام بالفعل.","concepts":["في «قرأ خالدٌ القصة» الفاعل: خالدٌ.","الفاعل مرفوع دائماً.","علامة رفعه الأصلية الضمة: نجحَ المجتهدُ."],"definitions":[{"term":"الفاعل","meaning":"من قام بالفعل."}],"review":["حدد الفاعل في: كتبت سارةُ الدرس.","ما علامة رفع الفاعل في «فاز الفريقُ»؟"]}'::jsonb, 'claude', 'draft', null),
  ('g5-arabic-u2-l1', '{"overview":"الهمزة في أول الكلمة نوعان: همزة قطع تُنطق دائماً، وهمزة وصل تُنطق في البداية فقط.","concepts":["همزة القطع تُكتب على الألف (أ، إ) وتُنطق دائماً: أحمد، إسلام، أكتب.","همزة الوصل تُكتب ألفاً بلا همزة (ا) وتسقط في وسط الكلام: استمع، اكتب، ال التعريف.","نختبر الكلمة بوضع «و» قبلها: إن نُطقت الهمزة فهي قطع."],"definitions":[],"review":["اذكر كلمة تبدأ بهمزة قطع.","كيف نميز همزة الوصل؟"]}'::jsonb, 'claude', 'draft', null),
  ('g5-arabic-u2-l2', '{"overview":"الخبر يكون مفرداً أو جملة أو شبه جملة.","concepts":["خبر مفرد: الطالبُ مجتهدٌ.","خبر جملة فعلية: الطيرُ يغرّدُ.","خبر شبه جملة: الكتابُ على الطاولةِ."],"definitions":[],"review":["ما نوع الخبر في «الطيرُ يغرّد»؟","كوّن جملة خبرها شبه جملة."]}'::jsonb, 'claude', 'draft', null),
  ('g5-english-u1-l1', '{"overview":"We name places in a town and say what people do there.","concepts":["We buy medicine at the pharmacy.","We borrow books from the library.","A doctor works in a hospital and a teacher works in a school."],"definitions":[],"review":["Where do we buy medicine?","Where can you borrow books?"]}'::jsonb, 'claude', 'draft', null),
  ('g5-english-u1-l2', '{"overview":"We ask for and give simple directions.","concepts":["turn left, turn right, go straight on.","next to, opposite, between.","Ask: \"Where is the bank?\" — \"Go straight on and turn right.\""],"definitions":[],"review":["What is the opposite of \"left\"?","What does \"go straight on\" mean?"]}'::jsonb, 'claude', 'draft', null),
  ('g5-english-u2-l1', '{"overview":"We name jobs and say where people work.","concepts":["A nurse helps sick people in a hospital.","A pilot flies a plane. A fisherman catches fish.","A farmer works on a farm."],"definitions":[],"review":["Who flies a plane?","Where does a nurse work?"]}'::jsonb, 'claude', 'draft', null),
  ('g5-english-u2-l2', '{"overview":"We use the present continuous for actions happening now.","concepts":["Form: am / is / are + verb-ing.","I am writing. She is reading. They are playing.","Words like \"now\" and \"Look!\" show the action is happening now."],"definitions":[],"review":["Complete: She ____ a book now.","Make a sentence about what you are doing now."],"example":"Look! The boys are playing football."}'::jsonb, 'claude', 'draft', null),
  ('g5-islamic-u1-l1', '{"overview":"الإيمان تصديق بالقلب وقول باللسان وعمل بالجوارح، وله ستة أركان.","concepts":["أركان الإيمان: الإيمان بالله، وملائكته، وكتبه، ورسله، واليوم الآخر، والقدر خيره وشره.","أركان الإسلام أعمال ظاهرة كالصلاة والزكاة، وأركان الإيمان أمور يعتقدها القلب.","من الكتب السماوية: القرآن والتوراة والإنجيل والزبور."],"definitions":[{"term":"القدر","meaning":"أن كل ما يحدث في الكون بعلم الله وتقديره."}],"review":["اذكر أركان الإيمان الستة.","ما الفرق بين أركان الإسلام وأركان الإيمان؟"]}'::jsonb, 'claude', 'draft', null),
  ('g5-islamic-u1-l2', '{"overview":"الزكاة ركن من أركان الإسلام، وهي حق في مال الغني يُعطى للمستحقين.","concepts":["الزكاة جزء معلوم من المال يُخرج إذا بلغ النصاب ومر عليه عام.","تُعطى الزكاة للفقراء والمساكين وغيرهم من المستحقين.","تطهّر الزكاة النفس من البخل، وتنشر المحبة، وتقلل الفقر في المجتمع."],"definitions":[{"term":"النصاب","meaning":"أقل مقدار من المال تجب فيه الزكاة."}],"review":["ما الزكاة؟","اذكر أثرين للزكاة في المجتمع."]}'::jsonb, 'claude', 'draft', null),
  ('g5-islamic-u2-l1', '{"overview":"هاجر النبي ﷺ من مكة إلى المدينة المنورة بعد أن اشتد أذى قريش للمسلمين.","concepts":["رافق أبو بكر الصديق رضي الله عنه النبي ﷺ في الهجرة.","اختبأ النبي ﷺ وصاحبه في غار ثور ثلاث ليال.","استقبل أهل المدينة النبي ﷺ بالفرح، وبدأ التاريخ الهجري بهذه الهجرة."],"definitions":[{"term":"الهجرة","meaning":"الانتقال من مكان إلى آخر، والمقصود هنا انتقال النبي ﷺ إلى المدينة."}],"review":["إلى أين هاجر النبي ﷺ؟","اذكر درساً نتعلمه من الهجرة."]}'::jsonb, 'claude', 'draft', null),
  ('g5-islamic-u2-l2', '{"overview":"من أول ما فعله النبي ﷺ عند وصوله المدينة بناء المسجد النبوي.","concepts":["شارك النبي ﷺ أصحابه في بناء المسجد بيديه.","كان المسجد مكاناً للصلاة والتعليم والشورى واستقبال الوفود.","المسجد مركز يجمع المسلمين ويقوي الأخوة بينهم."],"definitions":[],"review":["ما أول عمل قام به النبي ﷺ في المدينة؟","اذكر وظيفتين للمسجد في عهد النبي ﷺ."]}'::jsonb, 'claude', 'draft', null),
  ('g5-math-u1-l1', '{"overview":"الكسر يمثل جزءاً من كل مقسوم إلى أجزاء متساوية.","concepts":["البسط عدد الأجزاء المأخوذة، والمقام عدد الأجزاء الكلية.","في الكسر 3/4: البسط 3 والمقام 4.","الكسور المتكافئة لها القيمة نفسها: 1/2 = 2/4."],"definitions":[],"review":["ما المقام في الكسر 5/7؟","اكتب كسراً يكافئ 1/3."],"example":"فطيرة قُسمت إلى 8 أجزاء وأكلنا 3: أكلنا 3/8 من الفطيرة."}'::jsonb, 'claude', 'draft', null),
  ('g5-math-u1-l2', '{"overview":"نجمع الكسور متساوية المقامات بجمع البسوط مع إبقاء المقام.","concepts":["2/7 + 3/7 = 5/7.","وفي الطرح نطرح البسوط ونبقي المقام: 5/9 − 2/9 = 3/9.","نبسّط الناتج إن أمكن: 2/4 = 1/2."],"definitions":[],"review":["3/8 + 4/8 = ؟","7/10 − 2/10 = ؟"],"example":"1/4 + 1/4 = 2/4 = 1/2"}'::jsonb, 'claude', 'draft', null),
  ('g5-math-u2-l1', '{"overview":"الزاوية تتكون من شعاعين يلتقيان في نقطة، ونقيسها بالمنقلة بالدرجات.","concepts":["الزاوية القائمة قياسها 90°.","الحادة أصغر من 90°، والمنفرجة أكبر من 90° وأصغر من 180°.","الزاوية المستقيمة قياسها 180°."],"definitions":[{"term":"المنقلة","meaning":"أداة لقياس الزوايا بالدرجات."}],"review":["ما نوع زاوية قياسها 45°؟","كم قياس الزاوية القائمة؟"],"example":"زاوية قياسها 120° زاوية منفرجة."}'::jsonb, 'claude', 'draft', null),
  ('g5-math-u2-l2', '{"overview":"نحسب محيط المستطيل ومساحته من طوله وعرضه.","concepts":["محيط المستطيل = (الطول + العرض) × 2.","مساحة المستطيل = الطول × العرض.","وحدة المحيط سم، ووحدة المساحة سم²."],"definitions":[],"review":["ما محيط مستطيل طوله 5 سم وعرضه 3 سم؟","ما مساحته؟"],"example":"مستطيل 6 × 4 سم: المحيط = (6 + 4) × 2 = 20 سم، والمساحة = 24 سم²."}'::jsonb, 'claude', 'draft', null),
  ('g5-science-u1-l1', '{"overview":"الجهاز الهضمي يحوّل الطعام إلى مواد بسيطة يمتصها الجسم.","concepts":["يبدأ الهضم في الفم بالمضغ واللعاب.","ينقل المريء الطعام إلى المعدة، ثم يمر إلى الأمعاء الدقيقة.","يُمتص معظم الغذاء في الأمعاء الدقيقة، والأمعاء الغليظة تمتص الماء."],"definitions":[{"term":"الهضم","meaning":"تحويل الطعام إلى مواد بسيطة يستفيد منها الجسم."}],"review":["رتب: معدة، فم، أمعاء دقيقة، مريء.","أين يُمتص معظم الغذاء؟"]}'::jsonb, 'claude', 'draft', null),
  ('g5-science-u1-l2', '{"overview":"الجهاز التنفسي يُدخل الأكسجين إلى الجسم ويخرج ثاني أكسيد الكربون.","concepts":["يدخل الهواء من الأنف إلى القصبة الهوائية ثم إلى الرئتين.","الرئتان العضو الرئيسي في التنفس.","في الشهيق نأخذ الأكسجين، وفي الزفير نُخرج ثاني أكسيد الكربون."],"definitions":[{"term":"الشهيق","meaning":"إدخال الهواء إلى الرئتين."},{"term":"الزفير","meaning":"إخراج الهواء من الرئتين."}],"review":["ما الغاز الذي نحتاجه عند الشهيق؟","ما العضو الرئيسي في الجهاز التنفسي؟"]}'::jsonb, 'claude', 'draft', null),
  ('g5-science-u2-l1', '{"overview":"البناء الضوئي عملية يصنع بها النبات غذاءه في الأوراق الخضراء.","concepts":["يحتاج النبات إلى ضوء الشمس والماء وثاني أكسيد الكربون.","ينتج النبات السكر (غذاءه) ويطلق الأكسجين.","الكائنات الحية كلها تعتمد على النبات في الغذاء والأكسجين."],"definitions":[{"term":"الكلوروفيل","meaning":"المادة الخضراء في الأوراق التي تمتص ضوء الشمس."}],"review":["ما متطلبات البناء الضوئي؟","ما الغاز الذي يطلقه النبات؟"]}'::jsonb, 'claude', 'draft', null),
  ('g5-science-u2-l2', '{"overview":"السلسلة الغذائية تبيّن انتقال الغذاء من كائن إلى آخر.","concepts":["تبدأ السلسلة دائماً بمنتج وهو النبات.","آكل الأعشاب مستهلك أول، وآكل اللحوم مستهلك ثانٍ.","عشب ← جراد ← طائر: العشب منتج."],"definitions":[{"term":"المنتج","meaning":"كائن يصنع غذاءه بنفسه."},{"term":"المستهلك","meaning":"كائن يتغذى على غيره."}],"review":["بماذا تبدأ السلسلة الغذائية؟","كوّن سلسلة غذائية من ثلاثة كائنات."]}'::jsonb, 'claude', 'draft', null),
  ('g5-social-u1-l1', '{"overview":"تقع سلطنة عُمان في الجنوب الشرقي من شبه الجزيرة العربية.","concepts":["عاصمتها مسقط.","تجاورها الإمارات والسعودية واليمن، ويحدها بحر عُمان وبحر العرب.","موقعها البحري جعلها مركزاً مهماً للتجارة عبر التاريخ."],"definitions":[],"review":["ما عاصمة سلطنة عُمان؟","اذكر دولتين تجاوران عُمان."]}'::jsonb, 'claude', 'draft', null),
  ('g5-social-u1-l2', '{"overview":"تتكون سلطنة عُمان من إحدى عشرة محافظة.","concepts":["من المحافظات: مسقط، وظفار، والداخلية، وشمال الباطنة، ومسندم.","صلالة أشهر مدن محافظة ظفار.","نزوى من مدن محافظة الداخلية، وصحار من مدن شمال الباطنة."],"definitions":[],"review":["كم عدد محافظات سلطنة عُمان؟","في أي محافظة تقع صلالة؟"]}'::jsonb, 'claude', 'draft', null),
  ('g5-social-u2-l1', '{"overview":"القلاع والحصون من أبرز معالم التراث العماني.","concepts":["من أشهرها: قلعة نزوى، وحصن بهلاء، وقلعة الجلالي.","حصن بهلاء مدرج في قائمة التراث العالمي.","كانت القلاع للدفاع والحكم وحفظ المؤن وحماية السكان."],"definitions":[],"review":["اذكر قلعتين عمانيتين.","ما وظائف القلاع قديماً؟"]}'::jsonb, 'claude', 'draft', null),
  ('g5-social-u2-l2', '{"overview":"الحرف التقليدية جزء من الهوية العمانية وتنقل المهارات بين الأجيال.","concepts":["من الحرف: الفخار، والنسيج، وصناعة الفضة، وسعف النخيل.","حرفة الصياغة تصنع الخناجر والحلي الفضية.","اشتهرت صور بصناعة السفن الخشبية."],"definitions":[],"review":["اذكر حرفتين تقليديتين.","بماذا اشتهرت مدينة صور؟"]}'::jsonb, 'claude', 'draft', null),
  ('g6-arabic-u1-l1', '{"overview":"الجملة الاسمية تتكون من مبتدأ وخبر، وكلاهما مرفوع.","concepts":["في «العلمُ نورٌ»: العلم مبتدأ، ونور خبر.","علامة رفعهما الأصلية الضمة.","الخبر يتمم معنى المبتدأ."],"definitions":[],"review":["حدد المبتدأ والخبر: الشمسُ مشرقةٌ.","أكمل بخبر: البحرُ ____."],"example":"البحرُ واسعٌ — الصدقُ منجاةٌ"}'::jsonb, 'claude', 'draft', null),
  ('g6-arabic-u1-l2', '{"overview":"بعض الأسماء تُرفع بعلامات فرعية بدلاً من الضمة.","concepts":["المثنى يُرفع بالألف: حضر الطالبان.","جمع المذكر السالم يُرفع بالواو: حضر المهندسون.","الأسماء المفردة وجمع التكسير تُرفع بالضمة."],"definitions":[],"review":["ما علامة رفع المثنى؟","ما علامة رفع «المعلمون» في: نجح المعلمون؟"]}'::jsonb, 'claude', 'draft', null),
  ('g6-arabic-u2-l1', '{"overview":"الفعل الصحيح خلت حروفه الأصلية من حروف العلة، والمعتل فيه حرف علة.","concepts":["حروف العلة: الألف والواو والياء.","أمثلة على الصحيح: كتب، جلس، فهم.","أمثلة على المعتل: قال، وعد، رمى."],"definitions":[],"review":["ما حروف العلة؟","هل «دعا» فعل صحيح أم معتل؟"]}'::jsonb, 'claude', 'draft', null),
  ('g6-arabic-u2-l2', '{"overview":"التاء المربوطة تُنطق هاء عند الوقف، والمفتوحة تُنطق تاء دائماً.","concepts":["المربوطة في آخر الأسماء المؤنثة: مدرسة، شجرة.","المفتوحة في آخر الفعل الماضي: كتبتْ، وفي جمع المؤنث: معلمات.","نقف على الكلمة: إن نطقناها هاء فهي مربوطة."],"definitions":[],"review":["اكتب كلمة بتاء مربوطة.","لماذا تُكتب التاء مفتوحة في «كتبتْ»؟"]}'::jsonb, 'claude', 'draft', null),
  ('g6-english-u1-l1', '{"overview":"We use the past simple for finished actions.","concepts":["Regular verbs add -ed: visit → visited, play → played.","Irregular verbs change: go → went, see → saw, eat → ate.","Time words: yesterday, last night, last week."],"definitions":[],"review":["What is the past of \"go\"?","Make a sentence with \"yesterday\"."],"example":"Yesterday, I visited my grandmother. We watched a film last night."}'::jsonb, 'claude', 'draft', null),
  ('g6-english-u1-l2', '{"overview":"We talk about a trip and ask questions with \"Did\".","concepts":["Question: Did + subject + verb? Did you go to Wahiba Sands?","Short answers: Yes, I did. / No, I didn''t.","After \"did\" we use the base verb: \"Did she go?\" not \"Did she went?\""],"definitions":[],"review":["Ask a question with \"Did\".","Why is \"Did she went?\" wrong?"]}'::jsonb, 'claude', 'draft', null),
  ('g6-english-u2-l1', '{"overview":"We name countries and nationalities.","concepts":["Oman → Omani, Egypt → Egyptian, Japan → Japanese.","Ask: \"Where are you from?\" — \"I''m from Oman.\"","Nationalities start with a capital letter."],"definitions":[],"review":["What are people from Oman called?","How do you ask about someone''s country?"]}'::jsonb, 'claude', 'draft', null),
  ('g6-english-u2-l2', '{"overview":"We use \"going to\" to talk about plans.","concepts":["Form: am / is / are + going to + verb.","We are going to visit Salalah in summer.","To travel by plane you need a passport and a ticket."],"definitions":[],"review":["Complete: We ____ going to visit Salalah.","Say one plan for the weekend."]}'::jsonb, 'claude', 'draft', null),
  ('g6-islamic-u1-l1', '{"overview":"القرآن الكريم كلام الله، ولتلاوته آداب نلتزم بها احتراماً له.","concepts":["نقول قبل التلاوة: أعوذ بالله من الشيطان الرجيم، ثم البسملة في أول السورة.","من آداب التلاوة: الطهارة، والجلوس باحترام، والتدبر.","نحافظ على المصحف ولا نضعه في مكان غير لائق."],"definitions":[{"term":"الاستعاذة","meaning":"قول: أعوذ بالله من الشيطان الرجيم."}],"review":["ماذا نقول قبل التلاوة؟","اذكر أدبين من آداب التلاوة."]}'::jsonb, 'claude', 'draft', null),
  ('g6-islamic-u1-l2', '{"overview":"الأمانة أداء الحقوق والمحافظة على ما يؤتمن عليه الإنسان.","concepts":["من صور الأمانة: رد الودائع، وحفظ السر، وإتقان العمل.","الغش في الاختبار يتعارض مع الأمانة.","الأمين يحبه الله ويثق به الناس."],"definitions":[],"review":["اذكر صورتين للأمانة.","لماذا يتعارض الغش مع الأمانة؟"]}'::jsonb, 'claude', 'draft', null),
  ('g6-islamic-u2-l1', '{"overview":"صلاة الجمعة واجبة على الرجال، وتحل محل صلاة الظهر يوم الجمعة.","concepts":["عدد ركعاتها ركعتان، تسبقهما خطبتان.","من آداب الجمعة: الاغتسال، ولبس أحسن الثياب، والتبكير إلى المسجد.","ننصت للخطبة ولا نتكلم أثناءها."],"definitions":[],"review":["كم عدد ركعات صلاة الجمعة؟","اذكر أدبين من آداب يوم الجمعة."]}'::jsonb, 'claude', 'draft', null),
  ('g6-islamic-u2-l2', '{"overview":"الدعاء عبادة نتقرب بها إلى الله ونطلب منه حاجاتنا.","concepts":["من آداب الدعاء: البدء بحمد الله والصلاة على النبي ﷺ، ورفع اليدين، واليقين بالإجابة.","من أوقات الإجابة: بين الأذان والإقامة، وفي السجود، وآخر الليل.","ندعو لأنفسنا ولوالدينا وللمسلمين."],"definitions":[],"review":["اذكر أدبين من آداب الدعاء.","اذكر وقتاً يُرجى فيه قبول الدعاء."]}'::jsonb, 'claude', 'draft', null),
  ('g6-math-u1-l1', '{"overview":"الكسر العشري طريقة أخرى لكتابة الكسر الذي مقامه 10 أو 100 أو 1000.","concepts":["1/2 = 0.5، و1/4 = 0.25.","نقارن الكسور العشرية بمقارنة الأرقام من اليسار منزلة منزلة.","0.7 أكبر من 0.65 لأن 0.70 > 0.65."],"definitions":[],"review":["اكتب 3/10 كسراً عشرياً.","أيهما أكبر: 0.4 أم 0.38؟"]}'::jsonb, 'claude', 'draft', null),
  ('g6-math-u1-l2', '{"overview":"النسبة المئوية جزء من مئة.","concepts":["50% تعني 50 من 100، أي النصف.","لإيجاد نسبة من عدد: نضرب العدد في النسبة ونقسم على 100.","100% تعني الشيء كاملاً."],"definitions":[],"review":["كم يساوي 25% من 80؟","ماذا تعني 100%؟"],"example":"10% من 200 = 200 × 10 ÷ 100 = 20."}'::jsonb, 'claude', 'draft', null),
  ('g6-math-u2-l1', '{"overview":"المتوسط الحسابي قيمة تمثل مجموعة من الأعداد.","concepts":["المتوسط = مجموع القيم ÷ عددها.","المتوسط يساعدنا على وصف البيانات بعدد واحد.","قد لا يكون المتوسط أحد القيم نفسها."],"definitions":[],"review":["ما متوسط 2، 4، 6؟","كيف نحسب المتوسط الحسابي؟"],"example":"درجات: 8، 9، 10 ← المجموع 27 ÷ 3 = 9."}'::jsonb, 'claude', 'draft', null),
  ('g6-math-u2-l2', '{"overview":"الحجم مقدار الحيز الذي يشغله المجسم.","concepts":["حجم متوازي المستطيلات = الطول × العرض × الارتفاع.","وحدة الحجم: سم³ أو م³.","المكعب حالة خاصة أبعاده متساوية."],"definitions":[],"review":["ما حجم صندوق أبعاده 5 × 2 × 3 سم؟","ما وحدة الحجم؟"],"example":"صندوق 2 × 3 × 4 سم: الحجم = 24 سم³."}'::jsonb, 'claude', 'draft', null),
  ('g6-science-u1-l1', '{"overview":"مصادر الطاقة نوعان: متجددة لا تنفد، وغير متجددة تنفد.","concepts":["المتجددة: الشمس، والرياح، والمياه.","غير المتجددة: النفط، والغاز الطبيعي، والفحم.","توربينات الهواء تحوّل طاقة الرياح إلى طاقة كهربائية."],"definitions":[],"review":["اذكر مصدر طاقة متجدداً.","لماذا يسمى النفط مصدراً غير متجدد؟"]}'::jsonb, 'claude', 'draft', null),
  ('g6-science-u1-l2', '{"overview":"الدائرة الكهربائية مسار مغلق يمر فيه التيار.","concepts":["مكوناتها: مصدر (بطارية)، وأسلاك، ومصباح، ومفتاح.","الموصلات تسمح بمرور الكهرباء مثل النحاس، والعوازل لا تسمح مثل البلاستيك.","المصباح يضيء عندما تكون الدائرة مغلقة."],"definitions":[],"review":["اذكر مكونات الدائرة البسيطة.","اذكر مادة عازلة."]}'::jsonb, 'claude', 'draft', null),
  ('g6-science-u2-l1', '{"overview":"البراكين والزلازل ظواهر طبيعية تغيّر سطح الأرض.","concepts":["البركان فتحة تخرج منها الصهارة، وتسمى الحمم عندما تصل إلى السطح.","الزلزال اهتزاز مفاجئ لسطح الأرض.","عند الزلزال نحتمي تحت طاولة قوية ونبتعد عن النوافذ."],"definitions":[{"term":"الحمم","meaning":"الصخور المنصهرة الخارجة من البركان."}],"review":["ما الحمم؟","ماذا نفعل عند حدوث زلزال؟"]}'::jsonb, 'claude', 'draft', null),
  ('g6-science-u2-l2', '{"overview":"دورة الماء حركة مستمرة للماء بين الأرض والسماء.","concepts":["التبخر: تحول الماء إلى بخار بحرارة الشمس.","التكاثف: تحول البخار إلى قطرات تكوّن السحب.","الهطول: سقوط المطر أو البرد، ثم يجري الماء ويتجمع ليتبخر من جديد."],"definitions":[],"review":["ما التكاثف؟","رتب مراحل دورة الماء."]}'::jsonb, 'claude', 'draft', null),
  ('g6-social-u1-l1', '{"overview":"لعُمان تاريخ عريق، وعُرفت قديماً بأسماء منها «مجان» و«مزون».","concepts":["اشتهرت عُمان قديماً بتجارة النحاس واللبان.","اشتهرت ظفار بإنتاج اللبان وتصديره.","العُمانيون بحّارة مهرة وصلوا بسفنهم إلى موانئ بعيدة."],"definitions":[],"review":["اذكر اسماً قديماً لعُمان.","بماذا اشتهرت ظفار تاريخياً؟"]}'::jsonb, 'claude', 'draft', null),
  ('g6-social-u1-l2', '{"overview":"الفلج قناة تنقل الماء من مصدره إلى القرى والمزارع.","concepts":["الأفلاج نظام ري عماني قديم يوزع الماء بالعدل.","بعض الأفلاج مدرجة في قائمة التراث العالمي.","من فوائدها: ري المزارع، وتوفير ماء الشرب، واستقرار السكان."],"definitions":[{"term":"الفلج","meaning":"قناة مائية تنقل الماء من الجبال أو باطن الأرض إلى القرى."}],"review":["ما الفلج؟","اذكر فائدتين للأفلاج."]}'::jsonb, 'claude', 'draft', null),
  ('g6-social-u2-l1', '{"overview":"تملك عُمان ساحلاً طويلاً جعلها غنية بالثروة السمكية.","concepts":["الأسماك مصدر غذاء ودخل لكثير من العُمانيين.","من الأسماك المشهورة: الكنعد والهامور والتونة.","الصيد الجائر والتلوث يضران بالثروة السمكية، فنلتزم بمواسم الصيد."],"definitions":[],"review":["اذكر سمكتين مشهورتين في عُمان.","كيف نحافظ على الثروة السمكية؟"]}'::jsonb, 'claude', 'draft', null),
  ('g6-social-u2-l2', '{"overview":"الزراعة نشاط مهم في عُمان، وتعتمد على مصادر المياه.","concepts":["النخلة أشهر شجرة تُزرع في عُمان.","سهل الباطنة سهل زراعي خصب في الشمال.","تعتمد الزراعة على الأفلاج والآبار، والري الحديث يوفر الماء."],"definitions":[],"review":["ما أشهر شجرة في عُمان؟","على ماذا تعتمد الزراعة في القرى؟"]}'::jsonb, 'claude', 'draft', null),
  ('g7-arabic-u1-l1', '{"overview":"المفعول به اسم منصوب يقع عليه فعل الفاعل.","concepts":["في «شرب الطفلُ الحليبَ» المفعول به: الحليبَ.","علامة نصبه الأصلية الفتحة.","يُنصب المثنى وجمع المذكر السالم بالياء: كرّمتُ الفائزَين."],"definitions":[{"term":"المفعول به","meaning":"من وقع عليه الفعل."}],"review":["حدد المفعول به: قرأ خالدٌ القصةَ.","ما علامة نصب المفعول به في: شاهدتُ المعلمين؟"]}'::jsonb, 'claude', 'draft', null),
  ('g7-arabic-u1-l2', '{"overview":"الحال اسم منصوب يبيّن هيئة صاحبه وقت حدوث الفعل.","concepts":["في «عاد الجنديُّ منتصراً» الحال: منتصراً.","يجيب الحال عن سؤال: كيف؟","الحال نكرة منصوبة غالباً."],"definitions":[{"term":"الحال","meaning":"وصف لهيئة الفاعل أو المفعول عند وقوع الفعل."}],"review":["استخرج الحال: أشرقت الشمسُ ساطعةً.","عن أي سؤال يجيب الحال؟"],"example":"جاء الطالبُ مسروراً ← كيف جاء؟ مسروراً."}'::jsonb, 'claude', 'draft', null),
  ('g7-arabic-u2-l1', '{"overview":"اسم الفاعل يدل على من قام بالفعل، واسم المفعول على من وقع عليه الفعل.","concepts":["من الثلاثي يصاغ اسم الفاعل على وزن «فاعل»: كتب ← كاتب.","واسم المفعول على وزن «مفعول»: كتب ← مكتوب.","نستخدمهما وصفاً: الطالب كاتبٌ، والدرس مكتوبٌ."],"definitions":[],"review":["ما اسم الفاعل من «شرب»؟","ما اسم المفعول من «فهم»؟"]}'::jsonb, 'claude', 'draft', null),
  ('g7-arabic-u2-l2', '{"overview":"الأفعال الخمسة أفعال مضارعة اتصلت بها ألف الاثنين أو واو الجماعة أو ياء المخاطبة.","concepts":["أمثلتها: يكتبان، تكتبان، يكتبون، تكتبون، تكتبين.","تُرفع بثبوت النون.","تُنصب وتُجزم بحذف النون: لن يكتبوا، لم يكتبوا."],"definitions":[],"review":["اذكر فعلاً من الأفعال الخمسة.","ما علامة رفع «يلعبون»؟"]}'::jsonb, 'claude', 'draft', null),
  ('g7-english-u1-l1', '{"overview":"We use \"going to\" for plans and intentions.","concepts":["Form: am / is / are + going to + base verb.","I am going to visit Nizwa next weekend.","Ask: \"What are you going to do?\""],"definitions":[],"review":["Complete: They are going ____ buy a new house.","What is wrong: \"She is going to visits\"?"]}'::jsonb, 'claude', 'draft', null),
  ('g7-english-u1-l2', '{"overview":"We use \"will\" for predictions about the future.","concepts":["I think it will rain tomorrow.","The negative is \"will not\" or \"won''t\".","After \"will\" use the base verb: He will go (not \"goes\")."],"definitions":[],"review":["What is the short form of \"will not\"?","Make a prediction about tomorrow."]}'::jsonb, 'claude', 'draft', null),
  ('g7-english-u2-l1', '{"overview":"We describe people''s appearance and personality.","concepts":["Appearance: tall, short, curly hair, brown eyes.","Personality: kind, helpful, funny, shy.","Opinion adjectives usually come before fact adjectives: a nice old house."],"definitions":[],"review":["Give two personality adjectives.","Describe a friend in one sentence."],"example":"My brother is very kind. He always helps people."}'::jsonb, 'claude', 'draft', null),
  ('g7-english-u2-l2', '{"overview":"We use the past continuous for actions in progress in the past.","concepts":["Form: was / were + verb-ing.","I was reading when the phone rang.","The long action uses past continuous; the short action uses past simple."],"definitions":[],"review":["Complete: They ____ playing in the garden.","Join: I was walking / it started to rain."]}'::jsonb, 'claude', 'draft', null),
  ('g7-islamic-u1-l1', '{"overview":"لله تعالى أسماء حسنى وصفات عُلا، ومعرفتها تزيد الإيمان وتهذب السلوك.","concepts":["من أسماء الله: الرحمن، والرحيم، والعليم، والسميع، والبصير، والرزاق.","من آمن بأن الله سميع بصير راقب كلامه وأفعاله.","من آمن بأن الله رزاق اطمأن قلبه وسعى في الرزق الحلال."],"definitions":[{"term":"الأسماء الحسنى","meaning":"أسماء الله التي تدل على كماله."}],"review":["اذكر ثلاثة من أسماء الله الحسنى.","كيف يؤثر الإيمان بأن الله بصير في سلوكك؟"]}'::jsonb, 'claude', 'draft', null),
  ('g7-islamic-u1-l2', '{"overview":"أباح الإسلام البيع والشراء ووضع لهما آداباً تحقق العدل.","concepts":["من آداب البيع: الصدق، وبيان العيب، والسماحة، والوفاء بالكيل والميزان.","حرّم الإسلام الغش والربا والاحتكار.","قال ﷺ: «من غشّنا فليس منا»."],"definitions":[{"term":"الربا","meaning":"زيادة مشروطة على الدين مقابل التأجيل."},{"term":"الاحتكار","meaning":"حبس السلع لرفع أسعارها."}],"review":["اذكر أدبين من آداب البيع.","اذكر معاملة محرّمة."]}'::jsonb, 'claude', 'draft', null),
  ('g7-islamic-u2-l1', '{"overview":"تلاوة القرآن من أعظم العبادات، ولقارئه أجر كبير.","concepts":["لقارئ القرآن بكل حرف حسنة، والحسنة بعشر أمثالها.","القرآن شفيع لأصحابه يوم القيامة.","نخصص ورداً يومياً للتلاوة ولو كان قليلاً، والمداومة أهم من الكثرة."],"definitions":[{"term":"الورد","meaning":"مقدار ثابت من القرآن يقرؤه المسلم يومياً."}],"review":["اذكر فضلاً من فضائل تلاوة القرآن.","ما الورد اليومي؟"]}'::jsonb, 'claude', 'draft', null),
  ('g7-islamic-u2-l2', '{"overview":"صلة الرحم الإحسان إلى الأقارب، وهي سبب للبركة في العمر والرزق.","concepts":["الأرحام هم الأقارب من جهة الأب والأم.","من صورها: الزيارة، والاتصال، والمساعدة، والسؤال عن الأحوال.","قطيعة الرحم من الذنوب الكبيرة."],"definitions":[{"term":"الرحم","meaning":"الأقارب من النسب."}],"review":["من هم الأرحام؟","اذكر صورتين لصلة الرحم."]}'::jsonb, 'claude', 'draft', null),
  ('g7-math-u1-l1', '{"overview":"الأعداد الصحيحة تشمل الموجبة والسالبة والصفر.","concepts":["نمثل الأعداد على خط الأعداد: السالبة يسار الصفر والموجبة يمينه.","جمع عددين لهما الإشارة نفسها: نجمع ونضع الإشارة المشتركة.","طرح عدد يساوي جمع معكوسه: 3 − (−2) = 3 + 2 = 5."],"definitions":[],"review":["أيهما أكبر: −2 أم −7؟","احسب: −5 + 9."],"example":"−4 + 6 = 2، و−3 + (−5) = −8."}'::jsonb, 'claude', 'draft', null),
  ('g7-math-u1-l2', '{"overview":"النسبة مقارنة بين كميتين، والتناسب تساوي نسبتين.","concepts":["نكتب النسبة بأبسط صورة بقسمة حديها على عامل مشترك: 6 : 8 = 3 : 4.","في التناسب a/b = c/d يكون حاصل ضرب الطرفين = حاصل ضرب الوسطين.","نستخدم التناسب في الوصفات والخرائط والأسعار."],"definitions":[],"review":["اكتب 10 : 15 بأبسط صورة.","حل: 2/5 = x/20."],"example":"3 أقلام بـ 600 بيسة، فكم ثمن 5 أقلام؟ 600 ÷ 3 × 5 = 1000 بيسة."}'::jsonb, 'claude', 'draft', null),
  ('g7-math-u2-l1', '{"overview":"العبارة الجبرية تحتوي على أعداد ومتغيرات وعمليات.","concepts":["«عدد مضافاً إليه 5» تُكتب: x + 5.","الحدود المتشابهة لها المتغير نفسه بالأس نفسه: 3x و5x.","نجمع الحدود المتشابهة بجمع معاملاتها: 3x + 5x = 8x."],"definitions":[{"term":"المتغير","meaning":"رمز مثل x يمثل عدداً مجهولاً."}],"review":["اكتب عبارة لـ «ضعف عدد ناقص 3».","بسّط: 4y + 2 + 3y."]}'::jsonb, 'claude', 'draft', null),
  ('g7-math-u2-l2', '{"overview":"حل المعادلة إيجاد قيمة المتغير التي تجعلها صحيحة.","concepts":["نجري العملية العكسية على الطرفين: x − 4 = 10 ← x = 14.","في 3x = 12 نقسم الطرفين على 3: x = 4.","نتحقق بالتعويض في المعادلة الأصلية."],"definitions":[],"review":["حل: x + 9 = 20.","حل: 5x = 35."],"example":"x + 7 = 15 ← x = 15 − 7 = 8، والتحقق: 8 + 7 = 15."}'::jsonb, 'claude', 'draft', null),
  ('g7-science-u1-l1', '{"overview":"الخلية وحدة بناء الكائن الحي ووظيفته.","concepts":["في كل خلية: غشاء خلوي، وسيتوبلازم، ونواة تتحكم في نشاطها.","الخلية النباتية لها جدار خلوي وبلاستيدات خضراء وفجوة كبيرة.","الخلية الحيوانية لا جدار لها ولا بلاستيدات."],"definitions":[{"term":"النواة","meaning":"مركز التحكم في الخلية."}],"review":["ما وظيفة النواة؟","اذكر فرقين بين الخلية النباتية والحيوانية."]}'::jsonb, 'claude', 'draft', null),
  ('g7-science-u1-l2', '{"overview":"تُصنّف الحيوانات إلى فقارية لها عمود فقري ولا فقارية.","concepts":["الفقاريات خمس مجموعات: الأسماك، والبرمائيات، والزواحف، والطيور، والثدييات.","اللافقاريات مثل الحشرات والديدان والرخويات.","الثدييات ترضع صغارها، والطيور مغطاة بالريش."],"definitions":[],"review":["اذكر مجموعات الفقاريات.","إلى أي مجموعة ينتمي الحوت؟"]}'::jsonb, 'claude', 'draft', null),
  ('g7-science-u2-l1', '{"overview":"للطاقة أشكال متعددة، وتتحول من شكل إلى آخر ولا تفنى.","concepts":["من أشكالها: الحركية، والحرارية، والضوئية، والكهربائية، والكيميائية.","المصباح يحوّل الطاقة الكهربائية إلى ضوئية وحرارية.","البطارية تحوّل الطاقة الكيميائية إلى كهربائية."],"definitions":[],"review":["ما تحول الطاقة في المروحة الكهربائية؟","اذكر ثلاثة أشكال للطاقة."]}'::jsonb, 'claude', 'draft', null),
  ('g7-science-u2-l2', '{"overview":"الكثافة كتلة وحدة الحجوم من المادة.","concepts":["الكثافة = الكتلة ÷ الحجم.","الجسم الأقل كثافة من الماء يطفو، والأكثر كثافة يغوص.","كثافة الماء تقريباً 1 غ/سم³."],"definitions":[],"review":["لماذا يطفو الخشب؟","احسب كثافة جسم كتلته 30 غ وحجمه 15 سم³."],"example":"جسم كتلته 20 غ وحجمه 10 سم³: كثافته 2 غ/سم³ فيغوص في الماء."}'::jsonb, 'claude', 'draft', null),
  ('g7-social-u1-l1', '{"overview":"تتنوع تضاريس سلطنة عُمان بين الجبال والسهول والصحارى والسواحل.","concepts":["جبال الحجر في الشمال، وأعلى قممها جبل شمس.","سهل الباطنة سهل ساحلي خصب.","من الصحارى: رمال الشرقية (وهيبة) والربع الخالي."],"definitions":[{"term":"التضاريس","meaning":"أشكال سطح الأرض من جبال وسهول وأودية وصحارى."}],"review":["ما أعلى قمة في عُمان؟","اذكر صحراء عمانية."]}'::jsonb, 'claude', 'draft', null),
  ('g7-social-u1-l2', '{"overview":"مناخ عُمان حار جاف في معظمه، مع اختلافات بين المناطق.","concepts":["الصيف حار، والشتاء معتدل، والأمطار قليلة.","تتأثر ظفار في الصيف بالرياح الموسمية فيحدث «الخريف».","الخريف: رذاذ وضباب وخضرة في جبال ظفار."],"definitions":[],"review":["صف مناخ عُمان.","ما سبب ظاهرة الخريف في ظفار؟"]}'::jsonb, 'claude', 'draft', null),
  ('g7-social-u2-l1', '{"overview":"يقع الوطن العربي في قارتي آسيا وأفريقيا.","concepts":["يمتد من المحيط الأطلسي غرباً إلى الخليج العربي شرقاً.","يضم 22 دولة يجمعها الدين واللغة والتاريخ.","موقعه متوسط بين قارات العالم ويطل على بحار مهمة."],"definitions":[],"review":["في أي قارتين يقع الوطن العربي؟","اذكر ما يجمع الدول العربية."]}'::jsonb, 'claude', 'draft', null),
  ('g7-social-u2-l2', '{"overview":"لكل دولة عربية عاصمة هي مركز الحكم فيها.","concepts":["الرياض عاصمة السعودية، والقاهرة عاصمة مصر.","أبوظبي عاصمة الإمارات، والدوحة عاصمة قطر.","الكويت عاصمتها مدينة الكويت، والمنامة عاصمة البحرين."],"definitions":[],"review":["ما عاصمة مصر؟","ما عاصمة الإمارات؟"]}'::jsonb, 'claude', 'draft', null),
  ('g8-arabic-u1-l1', '{"overview":"التشبيه عقد مقارنة بين شيئين يشتركان في صفة.","concepts":["أركانه: المشبه، والمشبه به، وأداة التشبيه، ووجه الشبه.","من أدوات التشبيه: الكاف، ومثل، وكأن.","في «الطالبُ كالنجمِ في تفوقه»: الطالب مشبه، والنجم مشبه به، والكاف أداة، والتفوق وجه الشبه."],"definitions":[{"term":"وجه الشبه","meaning":"الصفة المشتركة بين المشبه والمشبه به."}],"review":["اذكر أركان التشبيه.","استخرج التشبيه: العلمُ كالنورِ."]}'::jsonb, 'claude', 'draft', null),
  ('g8-arabic-u1-l2', '{"overview":"الاستفهام طلب العلم بشيء مجهول بأدوات مخصوصة.","concepts":["نسأل عن الزمان بـ «متى»، وعن المكان بـ «أين».","نسأل عن العدد بـ «كم»، وعن الحال بـ «كيف».","«هل» و«الهمزة» يُجاب عنهما بنعم أو لا."],"definitions":[],"review":["بماذا نسأل عن الزمان؟","ضع أداة مناسبة: ____ كتاباً قرأت؟"]}'::jsonb, 'claude', 'draft', null),
  ('g8-arabic-u2-l1', '{"overview":"المصدر اسم يدل على الحدث مجرداً من الزمن.","concepts":["فهم ← فَهْم، كتب ← كتابة، جلس ← جلوس.","مصادر الثلاثي سماعية نعرفها بالمعجم.","المصدر يأتي في الجملة بمواقع إعرابية مختلفة."],"definitions":[{"term":"المصدر","meaning":"ما دل على حدث بلا زمن."}],"review":["ما مصدر «شرب»؟","ما الفرق بين الفعل والمصدر؟"]}'::jsonb, 'claude', 'draft', null),
  ('g8-arabic-u2-l2', '{"overview":"النداء طلب إقبال المخاطب بأداة.","concepts":["أشهر أدوات النداء «يا».","في «يا طالبُ اجتهدْ» المنادى: طالبُ.","نستخدم «أيها» و«أيتها» لنداء ما فيه «ال»: يا أيها الطلاب."],"definitions":[{"term":"المنادى","meaning":"الاسم الذي يأتي بعد أداة النداء."}],"review":["ما أشهر أدوات النداء؟","حدد المنادى: يا محمدُ أقبلْ."]}'::jsonb, 'claude', 'draft', null),
  ('g8-english-u1-l1', '{"overview":"We give advice about healthy habits with \"should\".","concepts":["You should drink plenty of water every day.","You shouldn''t eat too much sugar.","After should / shouldn''t use the base verb."],"definitions":[],"review":["Give one piece of health advice.","Complete: You shouldn''t eat too much ____."]}'::jsonb, 'claude', 'draft', null),
  ('g8-english-u1-l2', '{"overview":"We compare things with comparatives and superlatives.","concepts":["Short adjectives: tall → taller → the tallest.","Long adjectives: interesting → more interesting → the most interesting.","Irregular: good → better → the best."],"definitions":[],"review":["Compare two cities.","What is the superlative of \"good\"?"],"example":"Jebel Shams is higher than Jebel Akhdar. It is the highest mountain in Oman."}'::jsonb, 'claude', 'draft', null),
  ('g8-english-u2-l1', '{"overview":"We describe towns and places.","concepts":["Muscat is a beautiful city by the sea.","There are many old forts in Oman.","Useful adjectives: busy, quiet, modern, historic."],"definitions":[],"review":["Describe your town in one sentence.","Complete: There ____ many old forts in Oman."]}'::jsonb, 'claude', 'draft', null),
  ('g8-english-u2-l2', '{"overview":"We talk about rules with must, mustn''t and have to.","concepts":["must / have to = it is necessary: You must wear a seatbelt.","mustn''t = it is not allowed: You mustn''t run in the corridor.","don''t have to = it is not necessary."],"definitions":[],"review":["Give one school rule with \"mustn''t\".","What is the difference between \"mustn''t\" and \"don''t have to\"?"]}'::jsonb, 'claude', 'draft', null),
  ('g8-islamic-u1-l1', '{"overview":"صلاة الجماعة أفضل من صلاة الفرد، وفيها تقوية للأخوة بين المسلمين.","concepts":["صلاة الجماعة تفضل صلاة الفرد بسبع وعشرين درجة.","نسوّي الصفوف ونتبع الإمام ولا نسبقه.","من آداب المسجد: الهدوء، والتطيب، وعدم المرور بين يدي المصلي."],"definitions":[],"review":["بكم درجة تفضل صلاة الجماعة صلاة الفرد؟","اذكر أدبين من آداب صلاة الجماعة."]}'::jsonb, 'claude', 'draft', null),
  ('g8-islamic-u1-l2', '{"overview":"حثّ الإسلام على حماية البيئة لأنها نعمة من الله وأمانة.","concepts":["نهى الإسلام عن الإسراف في الماء ولو كنا على نهر جارٍ.","غرس الأشجار صدقة يستمر أجرها.","إماطة الأذى عن الطريق والمحافظة على النظافة من الإيمان."],"definitions":[],"review":["اذكر سلوكاً يحمي البيئة.","ما أجر من يغرس شجرة؟"]}'::jsonb, 'claude', 'draft', null),
  ('g8-islamic-u2-l1', '{"overview":"الإيمان باليوم الآخر ركن من أركان الإيمان، وفيه يُحاسب الناس على أعمالهم.","concepts":["اليوم الآخر هو يوم القيامة، وفيه البعث والحساب والجزاء.","الإيمان به يدفع المسلم إلى العمل الصالح وترك المعاصي.","يجعل الإنسان صابراً لأنه يعلم أن الجزاء عند الله."],"definitions":[],"review":["ما اليوم الآخر؟","اذكر أثرين للإيمان به في السلوك."]}'::jsonb, 'claude', 'draft', null),
  ('g8-islamic-u2-l2', '{"overview":"الشورى تبادل الرأي للوصول إلى الصواب، وهي مبدأ إسلامي.","concepts":["قال تعالى: ﴿وَأَمْرُهُمْ شُورَىٰ بَيْنَهُمْ﴾.","كان النبي ﷺ يستشير أصحابه كما في غزوة بدر والخندق.","تُطبّق الشورى في الأسرة والمدرسة والدولة، ومنها مجلس الشورى في عُمان."],"definitions":[{"term":"الشورى","meaning":"طلب الرأي من أهل الخبرة قبل اتخاذ القرار."}],"review":["ما الشورى؟","اذكر مثالاً على الشورى في حياتك."]}'::jsonb, 'claude', 'draft', null),
  ('g8-math-u1-l1', '{"overview":"نحل المعادلات بإجراء العمليات العكسية على الطرفين.","concepts":["معادلة خطوة واحدة: x + 5 = 12 ← x = 7.","معادلة خطوتين: 2x + 3 = 11 ← 2x = 8 ← x = 4.","نتحقق بالتعويض."],"definitions":[],"review":["حل: 4x = 28.","حل: 2x − 5 = 9."],"example":"3x − 4 = 14 ← 3x = 18 ← x = 6."}'::jsonb, 'claude', 'draft', null),
  ('g8-math-u1-l2', '{"overview":"نستخدم النسبة المئوية في الخصم والزيادة والضريبة.","concepts":["الخصم = السعر × نسبة الخصم ÷ 100.","السعر بعد الخصم = السعر − الخصم.","الزيادة تُضاف إلى السعر الأصلي."],"definitions":[],"review":["احسب 20% من 50.","سعر 10 ريالات زاد 10%، كم أصبح؟"],"example":"قميص بـ 8 ريالات عليه خصم 25%: الخصم 2 ريال، فيصبح 6 ريالات."}'::jsonb, 'claude', 'draft', null),
  ('g8-math-u2-l1', '{"overview":"في المثلث القائم مربع الوتر يساوي مجموع مربعي الضلعين الآخرين.","concepts":["(الوتر)² = (الضلع الأول)² + (الضلع الثاني)².","الوتر أطول أضلاع المثلث القائم ويقابل الزاوية القائمة.","نستخدم النظرية لإيجاد طول ضلع مجهول."],"definitions":[{"term":"الوتر","meaning":"الضلع المقابل للزاوية القائمة."}],"review":["ما طول الوتر إذا كان الضلعان 6 و8؟","أين يقع الوتر في المثلث القائم؟"],"example":"ضلعا القائمة 3 و4: الوتر² = 9 + 16 = 25، فالوتر = 5."}'::jsonb, 'claude', 'draft', null),
  ('g8-math-u2-l2', '{"overview":"التحويلات الهندسية تغيّر موقع الشكل دون تغيير شكله وحجمه.","concepts":["الانسحاب: تحريك الشكل في اتجاه ومسافة محددين.","الانعكاس: صورة مرآة حول مستقيم.","الدوران: تدوير الشكل حول نقطة بزاوية معينة."],"definitions":[],"review":["ما التحويل الذي يحرك الشكل دون تدويره؟","ما صورة (4، 1) بالانسحاب 2 وحدة لليمين؟"],"example":"انعكاس النقطة (2، 3) حول محور السينات هو (2، −3)."}'::jsonb, 'claude', 'draft', null),
  ('g8-science-u1-l1', '{"overview":"العنصر مادة نقية من نوع واحد من الذرات، والمركب ينتج من اتحاد عنصرين أو أكثر.","concepts":["من العناصر: الأكسجين (O)، والهيدروجين (H)، والحديد (Fe).","الماء مركب صيغته H₂O.","خصائص المركب تختلف عن خصائص العناصر المكونة له."],"definitions":[{"term":"الرمز الكيميائي","meaning":"حرف أو حرفان يدلان على العنصر."}],"review":["ما رمز الحديد؟","لماذا يُعد الماء مركباً؟"]}'::jsonb, 'claude', 'draft', null),
  ('g8-science-u1-l2', '{"overview":"التغير الفيزيائي لا ينتج مادة جديدة، والكيميائي ينتج مادة جديدة.","concepts":["أمثلة فيزيائية: انصهار الثلج، وتمزيق الورق.","أمثلة كيميائية: احتراق الخشب، وصدأ الحديد، وطهي البيض.","من علامات التغير الكيميائي: تغير اللون، وتصاعد غاز، وانبعاث حرارة أو ضوء."],"definitions":[],"review":["هل صدأ الحديد تغير فيزيائي أم كيميائي؟","اذكر علامتين للتغير الكيميائي."]}'::jsonb, 'claude', 'draft', null),
  ('g8-science-u2-l1', '{"overview":"ينعكس الضوء عن السطوح، وينكسر عند انتقاله بين وسطين.","concepts":["الانعكاس: ارتداد الضوء عن سطح لامع كالمرآة.","الانكسار: انحراف الضوء عند انتقاله من الهواء إلى الماء.","من التطبيقات: المرايا، والعدسات في النظارات والكاميرات."],"definitions":[],"review":["ما الانكسار؟","اذكر تطبيقاً على الانعكاس."],"example":"القلم يبدو مكسوراً في كوب الماء بسبب الانكسار."}'::jsonb, 'claude', 'draft', null),
  ('g8-science-u2-l2', '{"overview":"الزهرة عضو التكاثر في النبات الزهري.","concepts":["العضو الذكري: السداة، وتنتج حبوب اللقاح.","العضو الأنثوي: المتاع، وفيه المبيض.","التلقيح انتقال حبوب اللقاح، ثم يتكون البذر والثمرة بعد الإخصاب."],"definitions":[{"term":"التلقيح","meaning":"انتقال حبوب اللقاح من السداة إلى الميسم."}],"review":["ما العضو الذكري في الزهرة؟","ما دور الحشرات في التلقيح؟"]}'::jsonb, 'claude', 'draft', null),
  ('g8-social-u1-l1', '{"overview":"قدّمت الحضارة الإسلامية إسهامات كبيرة في العلوم والمعرفة.","concepts":["برع المسلمون في الطب والفلك والرياضيات والجغرافيا.","من العلماء: ابن سينا في الطب، والخوارزمي في الرياضيات.","من علماء عُمان: الخليل بن أحمد الفراهيدي واضع علم العروض، وأحمد بن ماجد الملاح."],"definitions":[],"review":["اذكر عالماً مسلماً وإسهامه.","بماذا اشتهر أحمد بن ماجد؟"]}'::jsonb, 'claude', 'draft', null),
  ('g8-social-u1-l2', '{"overview":"يتكون سطح الأرض من سبع قارات وخمسة محيطات.","concepts":["القارات: آسيا، وأفريقيا، وأوروبا، وأمريكا الشمالية، وأمريكا الجنوبية، وأستراليا، وأنتاركتيكا.","المحيطات: الهادئ، والأطلسي، والهندي، والمتجمد الشمالي، والمتجمد الجنوبي.","آسيا أكبر القارات، وتقع فيها سلطنة عُمان."],"definitions":[],"review":["ما أكبر القارات؟","اذكر ثلاثة محيطات."]}'::jsonb, 'claude', 'draft', null),
  ('g8-social-u2-l1', '{"overview":"الموانئ والطرق شرايين الاقتصاد العماني.","concepts":["من أهم الموانئ: صلالة، وصحار، والدقم، والسلطان قابوس.","النقل يسهل حركة الناس والبضائع ويدعم التجارة.","موقع عُمان على طرق الملاحة الدولية يزيد أهمية موانئها."],"definitions":[],"review":["اذكر ميناءين عمانيين.","لماذا يُعد النقل مهماً للاقتصاد؟"]}'::jsonb, 'claude', 'draft', null),
  ('g8-social-u2-l2', '{"overview":"شهد التعليم في عُمان تطوراً كبيراً منذ عام 1970.","concepts":["انتشرت المدارس في كل المحافظات وأصبح التعليم مجانياً.","أُسست جامعة السلطان قابوس عام 1986.","التعليم أساس التنمية وبناء الإنسان."],"definitions":[],"review":["متى أُسست جامعة السلطان قابوس؟","لماذا يُعد التعليم أساس التنمية؟"]}'::jsonb, 'claude', 'draft', null),
  ('g9-arabic-u1-l1', '{"overview":"كان وأخواتها أفعال ناسخة تدخل على الجملة الاسمية فترفع الاسم وتنصب الخبر.","concepts":["من أخواتها: أصبح، أمسى، صار، ليس، ما زال، ظلّ.","في «كان الجوُّ جميلاً»: الجو اسم كان مرفوع، وجميلاً خبرها منصوب.","«ليس» تفيد النفي، و«صار» تفيد التحول."],"definitions":[],"review":["حدد اسم كان وخبرها: كان الطالبُ مجتهداً.","أدخل «أصبح» على: الجوُّ باردٌ."]}'::jsonb, 'claude', 'draft', null),
  ('g9-arabic-u1-l2', '{"overview":"تُكتب الهمزة المتوسطة على حرف يناسب أقوى الحركتين: حركتها وحركة ما قبلها.","concepts":["ترتيب القوة: الكسرة ثم الضمة ثم الفتحة ثم السكون.","الكسرة تناسبها الياء (النبرة): سُئِل، بِئْر.","الضمة تناسبها الواو: مُؤْمن، والفتحة تناسبها الألف: سَأَل."],"definitions":[],"review":["على أي حرف تُكتب الهمزة في «يسـ_ـل» (يسأل)؟","لماذا كُتبت الهمزة على نبرة في «بئر»؟"]}'::jsonb, 'claude', 'draft', null),
  ('g9-arabic-u2-l1', '{"overview":"النعت تابع يصف اسماً قبله ويطابقه.","concepts":["يطابق النعت منعوته في الإعراب والتذكير والتأنيث والإفراد والتعريف.","في «قرأتُ قصةً جميلةً»: جميلة نعت منصوب.","النعت يزيد المعنى وضوحاً."],"definitions":[{"term":"المنعوت","meaning":"الاسم الموصوف."}],"review":["حدد النعت: هذا طالبٌ مجتهدٌ.","صحح: رأيتُ الشجرةَ الطويل."]}'::jsonb, 'claude', 'draft', null),
  ('g9-arabic-u2-l2', '{"overview":"العطف ربط كلمة بكلمة قبلها بحرف عطف لتشاركها الحكم والإعراب.","concepts":["من حروف العطف: الواو، والفاء، وثم، وأو.","الواو للجمع، والفاء للترتيب مع التعقيب، وثم للترتيب مع التراخي.","المعطوف يتبع المعطوف عليه في الإعراب."],"definitions":[],"review":["اذكر ثلاثة حروف عطف.","ما الفرق بين الفاء وثم؟"],"example":"جاء محمدٌ وخالدٌ ← خالد معطوف مرفوع."}'::jsonb, 'claude', 'draft', null),
  ('g9-english-u1-l1', '{"overview":"We use the present perfect to talk about experiences.","concepts":["Form: have / has + past participle.","Have you ever been to Salalah? — Yes, I have. / No, I have never been there.","\"ever\" is used in questions; \"never\" means \"not at any time\"."],"definitions":[],"review":["Ask a question with \"ever\".","Complete: He has ____ (eat) shuwa."],"example":"I have visited Nizwa Fort. She has never seen snow."}'::jsonb, 'claude', 'draft', null),
  ('g9-english-u1-l2', '{"overview":"We read and talk about technology in our lives.","concepts":["Vocabulary: device, app, screen, download, online, password.","Technology helps us learn and communicate.","We should use it safely and not share personal information online."],"definitions":[],"review":["Name two devices you use.","Give one rule for staying safe online."]}'::jsonb, 'claude', 'draft', null),
  ('g9-english-u2-l1', '{"overview":"We use the past perfect for an action that happened before another past action.","concepts":["Form: had + past participle.","When I arrived, the bus had left.","The earlier action uses past perfect; the later action uses past simple."],"definitions":[],"review":["Complete: She ____ (finish) her homework before dinner.","Which action happened first: \"When we got there, the film had started\"?"]}'::jsonb, 'claude', 'draft', null),
  ('g9-english-u2-l2', '{"overview":"We use relative clauses to join sentences and add information.","concepts":["who for people: The man who lives next door is a doctor.","which for things: The book which I read was exciting.","where for places: This is the school where I study."],"definitions":[],"review":["Join: I have a friend. She speaks French.","Choose: This is the town ____ I was born."]}'::jsonb, 'claude', 'draft', null),
  ('g9-islamic-u1-l1', '{"overview":"نزل القرآن الكريم على النبي ﷺ منجّماً خلال نحو ثلاث وعشرين سنة.","concepts":["بدأ نزوله في ليلة القدر من شهر رمضان في غار حراء.","السور المكية نزلت قبل الهجرة، وتركز على العقيدة والتوحيد.","السور المدنية نزلت بعد الهجرة، وتكثر فيها الأحكام والتشريعات."],"definitions":[{"term":"منجّماً","meaning":"نزل مفرّقاً على أجزاء بحسب الأحداث."}],"review":["كم سنة استغرق نزول القرآن؟","ما الفرق بين السور المكية والمدنية؟"]}'::jsonb, 'claude', 'draft', null),
  ('g9-islamic-u1-l2', '{"overview":"للنون الساكنة والتنوين أربعة أحكام في التلاوة.","concepts":["الإظهار: إذا جاء بعدها حرف من حروف الحلق (ء هـ ع ح غ خ).","الإدغام: إذا جاء بعدها حرف من «يرملون».","الإقلاب: إذا جاء بعدها الباء فتُقلب ميماً، والإخفاء: مع باقي الحروف."],"definitions":[{"term":"التنوين","meaning":"نون ساكنة زائدة تلحق آخر الاسم لفظاً لا خطاً."}],"review":["ما حروف الإظهار؟","ما حكم النون الساكنة قبل الباء؟"],"example":"«مِنْ عِلْمٍ»: إظهار، «مِنْ بَعْدِ»: إقلاب."}'::jsonb, 'claude', 'draft', null),
  ('g9-islamic-u2-l1', '{"overview":"الصبر حبس النفس على ما يرضي الله، وهو مفتاح النجاح.","concepts":["الصبر على الطاعة: كالمحافظة على الصلاة.","الصبر عن المعصية: كترك ما حرّم الله.","الصبر على البلاء: كالمرض وفقد الأحبة، مع الرضا بقضاء الله."],"definitions":[],"review":["اذكر أنواع الصبر.","اذكر موقفاً يحتاج فيه الطالب إلى الصبر."]}'::jsonb, 'claude', 'draft', null),
  ('g9-islamic-u2-l2', '{"overview":"الأمانة العلمية نسبة الأقوال والمعلومات إلى أصحابها وعدم ادعاء جهد الآخرين.","concepts":["نذكر المصدر الذي أخذنا منه المعلومة.","نسخ بحث غيرنا ونسبته لأنفسنا خيانة للأمانة.","الأمانة العلمية تبني الثقة وتطوّر العلم."],"definitions":[],"review":["ما الأمانة العلمية؟","كيف نطبقها في البحوث المدرسية؟"]}'::jsonb, 'claude', 'draft', null),
  ('g9-math-u1-l1', '{"overview":"نحل المعادلات الخطية بتجميع المتغيرات في طرف والأعداد في الطرف الآخر.","concepts":["ننقل الحدود بعكس إشارتها: 5x − 3 = 2x + 9 ← 3x = 12.","نقسم على المعامل: x = 4.","نتحقق بالتعويض في الطرفين."],"definitions":[],"review":["حل: 3x + 2 = x + 10.","حل: 4(x − 1) = 12."],"example":"2(x + 3) = 14 ← 2x + 6 = 14 ← x = 4."}'::jsonb, 'claude', 'draft', null),
  ('g9-math-u1-l2', '{"overview":"الميل يقيس انحدار المستقيم.","concepts":["الميل m = (y₂ − y₁) ÷ (x₂ − x₁).","في y = mx + b: m الميل، وb المقطع الصادي.","الميل الموجب يعني أن المستقيم صاعد، والسالب أنه هابط."],"definitions":[],"review":["ما الميل والمقطع في y = 3x − 1؟","احسب الميل بين (0، 1) و(2، 5)."],"example":"النقطتان (1، 2) و(3، 6): الميل = (6 − 2) ÷ (3 − 1) = 2."}'::jsonb, 'claude', 'draft', null),
  ('g9-math-u2-l1', '{"overview":"الاحتمال عدد بين 0 و1 يقيس فرصة وقوع حدث.","concepts":["الاحتمال = عدد النواتج المطلوبة ÷ عدد النواتج الممكنة.","الحدث المستحيل احتماله 0، والمؤكد احتماله 1.","نعبّر عن الاحتمال بكسر أو كسر عشري أو نسبة مئوية."],"definitions":[],"review":["ما احتمال ظهور 6 عند رمي حجر نرد؟","ما احتمال الحدث المستحيل؟"],"example":"احتمال ظهور عدد زوجي عند رمي حجر نرد = 3/6 = 1/2."}'::jsonb, 'claude', 'draft', null),
  ('g9-math-u2-l2', '{"overview":"نحل المتباينة مثل المعادلة، مع قلب الإشارة عند الضرب أو القسمة على عدد سالب.","concepts":["x + 3 > 7 ← x > 4.","−2x < 6 ← x > −3 (انقلبت الإشارة).","نمثل الحل على خط الأعداد بدائرة مفتوحة لـ < و>، ومغلقة لـ ≤ و≥."],"definitions":[],"review":["حل: 2x − 1 ≤ 5.","متى نقلب إشارة المتباينة؟"]}'::jsonb, 'claude', 'draft', null),
  ('g9-science-u1-l1', '{"overview":"السرعة المسافة المقطوعة في وحدة الزمن.","concepts":["السرعة المتوسطة = المسافة الكلية ÷ الزمن الكلي.","وحداتها: م/ث أو كم/س.","للتحويل من كم/س إلى م/ث نضرب في 1000 ونقسم على 3600."],"definitions":[],"review":["احسب سرعة عدّاء قطع 100 م في 20 ث.","ما وحدة السرعة في النظام الدولي؟"],"example":"سيارة قطعت 180 كم في ساعتين: السرعة = 90 كم/س."}'::jsonb, 'claude', 'draft', null),
  ('g9-science-u1-l2', '{"overview":"القوة دفع أو سحب يغيّر حالة الجسم، ووحدتها النيوتن.","concepts":["القوة كمية متجهة لها مقدار واتجاه.","قانون نيوتن الأول: يبقى الجسم ساكناً أو متحركاً بسرعة ثابتة ما لم تؤثر فيه قوة محصلة.","القصور الذاتي سبب اندفاع الراكب للأمام عند توقف السيارة فجأة."],"definitions":[{"term":"القصور الذاتي","meaning":"ميل الجسم للمحافظة على حالته الحركية."}],"review":["ما وحدة القوة؟","لماذا نربط حزام الأمان؟"]}'::jsonb, 'claude', 'draft', null),
  ('g9-science-u2-l1', '{"overview":"الجهاز العصبي يستقبل المعلومات وينسق أعمال الجسم.","concepts":["يتكون من الدماغ والحبل الشوكي والأعصاب.","الخلية العصبية (العصبون) وحدة بناء الجهاز العصبي.","الفعل المنعكس استجابة سريعة لا إرادية يتحكم بها الحبل الشوكي، مثل سحب اليد عن جسم ساخن."],"definitions":[{"term":"الفعل المنعكس","meaning":"استجابة سريعة تلقائية لمؤثر دون تفكير."}],"review":["اذكر أجزاء الجهاز العصبي.","أعط مثالاً على فعل منعكس."]}'::jsonb, 'claude', 'draft', null),
  ('g9-science-u2-l2', '{"overview":"الأحماض والقواعد مواد نستخدمها يومياً، ونميزها بالكواشف.","concepts":["الأحماض طعمها لاذع مثل الليمون والخل، وتحوّل ورق تباع الشمس الأزرق إلى أحمر.","القواعد ملمسها صابوني مثل الصابون والمنظفات، وتحوّل الأحمر إلى أزرق.","الرقم الهيدروجيني pH: أقل من 7 حمضي، و7 متعادل، وأكبر من 7 قاعدي."],"definitions":[{"term":"الكاشف","meaning":"مادة يتغير لونها حسب نوع المحلول."}],"review":["اذكر حمضاً من حياتك اليومية.","ما قيمة pH للماء النقي؟"]}'::jsonb, 'claude', 'draft', null),
  ('g9-social-u1-l1', '{"overview":"تتنوع الموارد الاقتصادية في عُمان، وتسعى الدولة إلى تنويع مصادر الدخل.","concepts":["النفط والغاز من أهم مصادر الدخل.","من الموارد الأخرى: الثروة السمكية والزراعة والمعادن والسياحة.","التنويع الاقتصادي يقلل الاعتماد على النفط ويوفر فرص العمل."],"definitions":[{"term":"التنويع الاقتصادي","meaning":"تعدد مصادر الدخل الوطني."}],"review":["اذكر ثلاثة موارد اقتصادية.","لماذا تسعى عُمان إلى التنويع الاقتصادي؟"]}'::jsonb, 'claude', 'draft', null),
  ('g9-social-u1-l2', '{"overview":"الكثافة السكانية عدد السكان في الكيلومتر المربع.","concepts":["الكثافة = عدد السكان ÷ المساحة.","يتركز السكان في السواحل والسهول ومحافظة مسقط.","يقل السكان في الصحارى والمناطق الجبلية الوعرة."],"definitions":[],"review":["ما الكثافة السكانية؟","لماذا يتركز السكان في السواحل؟"]}'::jsonb, 'claude', 'draft', null),
  ('g9-social-u2-l1', '{"overview":"للعمانيين تاريخ عريق في الملاحة والتجارة البحرية.","concepts":["وصلت السفن العمانية إلى الهند والصين وشرق أفريقيا.","استخدم البحارة النجوم والبوصلة والرياح الموسمية في الإبحار.","أحمد بن ماجد من أشهر الملاحين العرب."],"definitions":[],"review":["اذكر أداتين من أدوات الملاحة القديمة.","إلى أين وصلت السفن العمانية؟"]}'::jsonb, 'claude', 'draft', null),
  ('g9-social-u2-l2', '{"overview":"امتد النفوذ العماني إلى سواحل شرق أفريقيا، ومنها زنجبار.","concepts":["أصبحت زنجبار مركزاً مهماً للحكم والتجارة العمانية.","نشر العمانيون الإسلام والثقافة العربية واللغة هناك.","ازدهرت تجارة القرنفل والعاج والتوابل."],"definitions":[],"review":["اذكر منطقة في شرق أفريقيا امتد إليها النفوذ العماني.","ما الأثر الحضاري لهذا الوجود؟"]}'::jsonb, 'claude', 'draft', null)
